INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C1','soc',5,1,'u2',1,'날씨와 기후 — 날씨는 짧은 시간 동안의 대기(공기) 상태로 하루 사이에도 바뀌고, 기후는 오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태 · 기후를 구성하는 요소는 기온(공기의 따뜻하고 차가운 정도)·강수(비·눈처럼 땅에 내린 물)·바람(공기가 움직이는 현상)이고 여러 해에 걸친 기록을 모아야 드러남 · 「사계절이 뚜렷하다」는 기후, 「오늘은 맑다」는 날씨',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C2','soc',5,1,'u2',1,'기후와 생활 — 기후는 의식주 생활과 산업 발전에 영향을 줌(기온이 높고 비가 많은 곳은 벼농사가 활발해 쌀 음식이 발달, 바람이 강한 곳은 바람으로 전기를 만드는 시설, 계절에 맞는 옷, 눈이 많은 겨울에 여는 축제) · 하루의 비로 행사를 못 하는 것은 날씨의 영향이고, 여러 해 되풀이되는 모습에 맞춘 생활이 기후의 영향',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C3','soc',5,1,'u2',2,'계절에 따른 바람과 기온 — 여름에는 남쪽 바다에서 뜨겁고 습한 바람이, 겨울에는 북서쪽 육지에서 차갑고 건조한 바람이 불어옴(바람이 지나온 곳이 바다냐 육지냐가 성질을 정함) · 우리나라는 남북으로 길어 대체로 남쪽으로 갈수록 기온이 높고, 남북 기온 차이는 여름보다 겨울에 훨씬 큼(여름엔 모두 덥고 겨울엔 북쪽만 크게 추워짐) · 등온선은 기온이 같은 곳을 이은 선',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C4','soc',5,1,'u2',2,'강수의 분포와 계절 — 연 강수량은 대체로 남쪽으로 갈수록 많아짐(분포도의 파란색이 진할수록 많음) · 계절로는 여름에 연 강수량의 절반 이상이 내리고 겨울에는 대체로 적음 · 봄은 온화하고 건조, 여름은 덥고 비가 잦음, 가을은 맑고 건조, 겨울은 춥고 건조하며 눈이 옴 — 통계 지도와 그래프에서 읽어 냄',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C5','soc',5,1,'u2',3,'계절별 자연재해 — 자연재해는 피할 수 없는 자연 현상으로 사람들이 입는 생명이나 재산상의 피해(자연 현상만으로는 재해가 아님) · 계절마다 바람·기온·강수가 달라 자주 생기는 재해도 다름: 봄 — 황사(사막의 모래 먼지가 바람을 타고 옴)·가뭄, 여름 — 폭염·호우(비가 많이 내림)·홍수(물이 흘러넘침), 여름과 가을 사이 — 태풍(많은 비와 강한 바람, 대체로 남서쪽에서 북동쪽으로), 겨울 — 폭설·한파',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C6','soc',5,1,'u2',3,'자연재해 피해를 줄이는 노력 — 자연재해는 막을 수 없지만 피해는 줄일 수 있음 · 저수지·댐·제방 같은 시설을 마련하고 재난 대비 훈련을 함 · 기상 특보(주의보·경보로 미리 알리는 정보)와 긴급 재난 문자로 알림 · 국민 행동 요령은 어린이를 포함한 국민 누구나 알고 실천함(태풍 때 외출 삼가기·시설물 정리) · 숲을 농경지로 일구거나 물길을 바꾸면 피해가 커지기도 함 · 예보 분석관이 날씨를 예측함',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C7','soc',5,1,'u2',4,'기후변화와 심해지는 자연재해 — 숲 파괴·석유와 석탄을 지나치게 쓰는 인간 활동으로 지구 온난화(지구의 기온이 높아지는 현상)가 심해져 전 세계에 기후변화가 나타남 · 우리나라는 연평균 기온이 꾸준히 올라가고(약 백 년 동안 1.9 ℃) 여름은 길어지고 겨울은 짧아짐 · 자연재해를 예측하기 어려워지고 강도가 세지며 횟수도 늘어 피해가 커짐(폭염·이상 고온·극한 호우·예측이 어려운 태풍)',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C8','soc',5,1,'u2',4,'기후 행동 — 기후변화를 막으려는 모든 노력 · 세계 여러 나라(파리 협정으로 기온 상승을 막기로 약속)·정부와 국회(기구 설치, 법과 제도)·기업(친환경 재료, 오염 물질 줄이기)·개인(에너지 아끼기, 대중교통, 일회용품 줄이기, 급식 남기지 않기, 빈 교실 전등 끄기)이 저마다 함 · 누구나 참여할 수 있고 매일 스스로 실천할 일을 골라 실천한 뒤 돌아보고 다시 이어 감',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C9','soc',5,1,'u2',5,'인구 분포와 인구 밀도 — 인구는 일정한 지역에 사는 사람의 수, 인구 분포는 그 인구가 모이거나 흩어져 있는 정도 · 인구 분포는 기후·지형 같은 자연환경과 일자리·교통·교육 같은 인문환경의 영향을 받음 · 인구 밀도는 일정한 넓이(1 km²) 안에 사는 사람의 수로 인구가 모여 있는 정도를 알려 줌 — 사람 수와 땅 넓이를 함께 봐야 함(좁은 땅에 많은 사람이면 높음) · 대체로 도시가 발달한 지역에서 높음',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C10','soc',5,1,'u2',6,'우리나라 인구 분포의 변화 — 과거(1960년 무렵)에는 벼농사 중심의 농업 사회라 자연환경의 영향을 많이 받아 기후가 온화하고 평야가 발달한 국토의 남서쪽에 모여 살았고, 기온이 낮고 산지가 많은 곳은 인구 밀도가 낮았음 · 1960년대 이후 산업화로 도시가 발달하며 많은 사람이 촌락에서 도시로 옮겨 인구 100명 중 92명 정도가 도시에 살고, 일자리·교통 같은 인문환경의 영향이 커져 수도권(서울특별시·인천광역시·경기도)과 대도시에 모임 — 인구의 절반 정도가 수도권, 옮겨 온 가장 큰 까닭은 직업',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C11','soc',5,1,'u2',6,'수도권과 비수도권의 인구 구조 — 인구 구조는 인구를 나이·성별 등으로 나누어 본 짜임새(유소년층 14세 이하·청장년층 15~64세·노년층 65세 이상) · 일자리와 교육 기회를 찾아 청장년층이 모인 수도권은 청장년층 비율이 높고, 청장년층이 빠져나간 비수도권은 노년층 비율이 더 높음',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C12','soc',5,1,'u2',7,'인구 분포의 불균형에 따른 문제 — 인구가 집중하는 수도권: 주택 부족과 가격 상승, 교통 혼잡과 주차 문제, 쓰레기와 환경 문제, 시설 부족, 삶의 질 저하 · 인구가 줄어드는 비수도권: 상점·병원·학교 같은 시설과 일자리 감소, 빈집과 폐교, 생활 편의 시설 감소, 청장년층 유출로 일손 부족, 식품 사막 · 두 지역의 일이 서로를 밀어붙이며 되풀이되어 지역 격차가 커지고 국가 경쟁력(다른 나라와 경쟁하는 힘)이 떨어질 수 있음 · 순이동은 들어온 인구수에서 나간 인구수를 뺀 값(20대 청년이 취업과 학업 때문에 수도권으로)',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C13','soc',5,1,'u2',8,'인구 분포의 불균형을 해결하는 노력 — 정부: 국가 균형 발전 기구·제도와 법, 공공 기관의 지방 이전(직원과 가족이 함께 옮겨 감)과 혁신 도시(공공 기관 이전을 계기로 새 성장 동력을 만드는 미래형 도시), 고향 사랑 기부제(고향이나 관심 지역에 기부, 답례품과 세금 혜택), 로컬 브랜딩(지역의 자원·문화로 지역만의 매력), 청년 마을 만들기(청년 정착 지원), 디지털 관광 주민증, 작은 학교 살리기 · 지역 스스로: 새 일자리, 주거·교육 환경 개선, 문화생활·창업 지원, 주민이 참여하는 발전 사업(소득 증가 → 지역 경제 활발 → 인구 증가) · 로컬 크리에이터 — 함께 잘 사는 국토',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C14','soc',5,1,'u2',8,'해결 방안을 평가하는 세 잣대 — 떠올린 방안은 ① 문제의 원인을 해결하는 데 도움이 되는가 ② 도덕적으로 옳은가(누구에게 억지로 시키거나 벌주지 않는가) ③ 드는 비용과 노력을 생각할 때 실현할 수 있는가를 모두 살핌 — 하나만 보면 좋아 보이던 방안도 다른 잣대에서 걸릴 수 있음 · 방안을 떠올릴 때는 원인을 줄이는 법, 수도권 인구를 나누는 법, 비수도권에 사람이 모이게 하는 법을 생각함',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C15','soc',5,1,'u2',9,'공부한 내용을 동시와 시화로 표현하기 — 단원에서 공부한 내용(기후·자연재해·기후 행동·인구 분포·불균형) 가운데 주제를 고름 → 주제에 대한 내 생각과 경험, 공부한 내용이 드러나게 순서를 생각하며 이야기로 씀 → 하고 싶은 말만 남겨 짧게 줄이고 운율(읽을 때 느껴지는 가락)을 살려 동시로 지음 → 다시 읽으며 이야기 내용이 잘 나타나게 고침 → 동시의 내용을 나타내는 장면을 그려 시화를 완성하고 친구와 바꿔 보며 좋은 점을 말해 줌',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X01','soc',5,'u2',ARRAY['SO5-1-u2-C1']::text[],'날씨와 기후를 바꾸어 쓴다(하루의 하늘을 기후라고, 여러 해의 모습을 날씨라고 한다)','하루 = 날씨 · 여러 해 = 기후') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X02','soc',5,'u2',ARRAY['SO5-1-u2-C1']::text[],'기후를 구성하는 요소(기온·강수·바람)를 놓치거나 지형·인구처럼 대기 상태가 아닌 것을 넣는다','기온 · 강수 · 바람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X03','soc',5,'u2',ARRAY['SO5-1-u2-C2']::text[],'기후와 생활 모습(음식·옷·시설·축제·산업)을 맞지 않게 짝짓거나, 그날의 날씨 때문에 생긴 일을 기후의 영향으로 여긴다','여러 해 되풀이되는 모습에 맞춘 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X04','soc',5,'u2',ARRAY['SO5-1-u2-C3']::text[],'계절마다 불어오는 바람의 방향과 성질을 바꾸어 안다(여름에 북서쪽 육지 바람, 겨울에 남쪽 바다 바람 등)','여름 — 남쪽 바다·뜨겁고 습함 · 겨울 — 북서쪽 육지·차갑고 건조') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X05','soc',5,'u2',ARRAY['SO5-1-u2-C3']::text[],'남북의 기온 차이를 거꾸로 안다(북쪽이 더 따뜻하다고, 또는 차이가 여름에 더 크다고)','남쪽일수록 따뜻 · 차이는 겨울에 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X06','soc',5,'u2',ARRAY['SO5-1-u2-C3','SO5-1-u2-C4']::text[],'등온선·분포도·그래프를 잘못 읽는다(등온선을 강수량이나 높이가 같은 선으로, 진한 색을 적다고 읽는 등)','등온선 = 기온이 같은 곳 · 진할수록 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X07','soc',5,'u2',ARRAY['SO5-1-u2-C4']::text[],'강수의 계절·지역 분포를 거꾸로 안다(겨울에 가장 많다고, 북쪽일수록 많다고)','여름에 절반 이상 · 남쪽으로 갈수록 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X08','soc',5,'u2',ARRAY['SO5-1-u2-C5']::text[],'자연재해의 뜻을 잘못 안다(사람이 일으킨 사고나 피해 없는 자연 현상도 자연재해라고 여긴다)','피할 수 없는 자연 현상 + 사람의 피해') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X09','soc',5,'u2',ARRAY['SO5-1-u2-C5']::text[],'계절과 자연재해, 자연재해와 그 특징을 바꾸어 짝짓는다','봄 황사·가뭄 · 여름 폭염·호우·홍수 · 태풍 · 겨울 폭설·한파') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X10','soc',5,'u2',ARRAY['SO5-1-u2-C6']::text[],'기상 특보·국민 행동 요령의 뜻을 오해하거나, 행동 요령은 어른만 알면 된다고, 특보가 나와도 평소처럼 지내도 된다고 여긴다','미리 알리는 정보 · 나를 지키는 것도 내 몫') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X11','soc',5,'u2',ARRAY['SO5-1-u2-C6']::text[],'사람이 땅의 모습을 바꾸는 일(숲을 일구기·물길 바꾸기)이 자연재해의 피해와 상관없다고 여긴다','숲과 물길은 물을 머금고 흘려보내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X12','soc',5,'u2',ARRAY['SO5-1-u2-C7']::text[],'기후변화의 원인과 방향을 거꾸로 안다(기온이 내려간다고, 겨울이 길어진다고, 숲 가꾸기가 원인이라고)','인간 활동 → 지구 온난화 → 기온 상승') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X13','soc',5,'u2',ARRAY['SO5-1-u2-C7']::text[],'자연재해가 잦고 세진 것을 우연으로 여겨 기후변화와의 관계를 놓친다','더 자주 · 더 세게 · 예측은 더 어렵게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X14','soc',5,'u2',ARRAY['SO5-1-u2-C8']::text[],'기후 행동의 뜻과 주체를 헷갈린다(관찰·기록으로 여기거나, 특별한 사람이나 나라만 하는 일로, 나 하나 해도 소용없다고 여긴다)','막으려는 모든 노력 · 누구나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X15','soc',5,'u2',ARRAY['SO5-1-u2-C8']::text[],'기후 행동을 고르기만 하고 실천과 돌아보기를 놓치거나, 잘 안 된 날 그만둔다','고르기 → 실천하기 → 돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X16','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구·인구 분포·인구 밀도의 뜻을 서로 바꾸어 안다','사람 수 · 모인 정도 · 1 km² 안의 사람 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X17','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구 분포에 영향을 주는 환경을 자연환경과 인문환경으로 잘못 나눈다','자연 — 기후·지형 · 인문 — 일자리·교통·교육') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X18','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구 밀도를 사람 수만으로, 또는 땅 넓이만으로 판단한다(넓은 땅이라서 밀도가 높다고 여기는 등)','사람 수와 넓이를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X19','soc',5,'u2',ARRAY['SO5-1-u2-C10']::text[],'과거와 오늘날의 인구 분포와 그 까닭을 바꾸어 안다(옛날부터 수도권에 모였다고, 사람들이 도시에서 촌락으로 옮겼다고, 오늘날에도 자연환경의 영향이 가장 크다고)','과거 남서쪽 평야·자연 · 오늘 수도권·인문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X20','soc',5,'u2',ARRAY['SO5-1-u2-C10','SO5-1-u2-C11']::text[],'수도권의 범위나 수도권·비수도권의 인구 구조를 잘못 안다','서울·인천·경기 · 수도권은 청장년층이 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X21','soc',5,'u2',ARRAY['SO5-1-u2-C12']::text[],'수도권의 문제와 비수도권의 문제를 바꾸어 짝짓는다(수도권에 빈집·폐교, 비수도권에 집값 상승·교통 혼잡)','몰리는 곳 · 빠져나가는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X22','soc',5,'u2',ARRAY['SO5-1-u2-C12']::text[],'인구 분포의 불균형이 저절로 풀린다고, 한 지역만의 문제라고, 나라 전체의 힘과 관계없다고 여긴다','되풀이되는 두 고리 · 국가 경쟁력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X23','soc',5,'u2',ARRAY['SO5-1-u2-C13']::text[],'불균형을 해결하는 노력의 뜻이나 방향을 헷갈린다(공공 기관을 수도권으로 모은다고, 고향에 사는 사람만 기부한다고 여기는 등)','사람과 일자리가 고르게 · 함께 잘 사는 국토') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X24','soc',5,'u2',ARRAY['SO5-1-u2-C14']::text[],'해결 방안을 한 가지 잣대로만 보아, 억지로 옮기게 하거나 벌주는 방안, 비용이 지나친 방안, 원인과 이어지지 않는 방안도 좋다고 여긴다','원인 · 옳음 · 실현 — 셋 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X25','soc',5,'u2',ARRAY['SO5-1-u2-C2','SO5-1-u2-C4','SO5-1-u2-C10','SO5-1-u2-C12']::text[],'기후와 인구 공부를 통계 수치·연도를 외우는 것으로 여겨 자료에서 특징과 까닭을 읽어 내는 것을 놓친다','외우기보다 자료를 읽고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X26','soc',5,'u2',ARRAY['SO5-1-u2-C15']::text[],'동시를 지을 때 겪지 않은 일을 넣거나, 이야기를 그대로 옮기거나, 고치지 않거나, 동시와 상관없는 그림을 그린다','내 이야기 · 짧게 · 다시 읽고 고치기 · 내용을 나타내는 그림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#1','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'mc','auto','어떤 날은 맑고 어떤 날은 비가 오는 것처럼, 짧은 시간 동안의 대기 상태를 무엇이라고 하나요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"어떤 날은 맑고 어떤 날은 비가 오는 것처럼, 짧은 시간 동안의 대기 상태를 무엇이라고 하나요?","options":[{"t":"날씨","correct":true},{"t":"기후","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"인구","mis":"SO5-1-u2-X02"}],"explanation":["하루 사이에도 바뀌어요.","나가기 전에 확인해요.","이것을 날씨라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#2','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'mc','auto','오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태는 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태는 어느 것인가요?","options":[{"t":"기후","correct":true},{"t":"날씨","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"계절","mis":"SO5-1-u2-X01"}],"explanation":["여러 해를 모아야 보여요.","평균적이고 종합적인 모습이에요.","기후라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#3','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'sa','auto','공기의 따뜻하고 차가운 정도를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"sa","stem":"공기의 따뜻하고 차가운 정도를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기온"],"explanation":["덥다·춥다를 나타내요.","온도계로 재요.","기온이에요."],"mis":"SO5-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#4','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'ox','auto','기온·강수·바람은 기후를 구성하는 요소예요.',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"ox","stem":"기온·강수·바람은 기후를 구성하는 요소예요.","answer":"O","reason_options":[{"t":"이 셋을 여러 해 동안 살펴보면 그 지역의 대기 상태가 드러나기 때문에","correct":true},{"t":"기후는 땅의 생김새로만 알 수 있기 때문에","mis":"SO5-1-u2-X02"}],"mis":"SO5-1-u2-X02","explanation":["기온은 따뜻하고 차가운 정도예요.","강수는 비·눈, 바람은 공기의 움직임이에요.","셋이 기후를 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#5','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','세 친구의 말 가운데 기후를 바르게 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"세 친구의 말 가운데 기후를 바르게 말한 친구는 누구인가요?","options":[{"t":"세아","correct":true},{"t":"하람","mis":"SO5-1-u2-X01"},{"t":"도윤","mis":"SO5-1-u2-X01"},{"t":"세 친구 모두","mis":"SO5-1-u2-X01"}],"explanation":["맑은 하늘은 오늘 하루의 일이에요.","매일 바뀌는 것은 날씨예요.","사계절이 뚜렷한 것이 기후예요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"오늘은 하늘이 맑아서 기후가 참 좋네."},{"who":"도윤","text":"어제는 비가 왔으니 기후가 매일 바뀌는 거야."},{"who":"세아","text":"우리나라는 봄·여름·가을·겨울이 뚜렷한 기후야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#6','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','기후를 구성하는 요소가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"기후를 구성하는 요소가 아닌 것은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"기온","mis":"SO5-1-u2-X02"},{"t":"강수","mis":"SO5-1-u2-X02"},{"t":"바람","mis":"SO5-1-u2-X02"}],"explanation":["기후는 대기의 상태예요.","기온·강수·바람이 요소예요.","지형은 땅의 생김새예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#7','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','눈이나 비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"눈이나 비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요?","options":[{"t":"강수","correct":true},{"t":"기온","mis":"SO5-1-u2-X02"},{"t":"바람","mis":"SO5-1-u2-X02"},{"t":"습지","mis":"SO5-1-u2-X02"}],"explanation":["비도 눈도 하늘에서 내려요.","땅에 내린 물이에요.","강수라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#8','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C2',2,'mc','auto','기온이 높고 비가 많이 내리는 지역에서 발달하기 쉬운 음식 문화는 어느 것인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"mc","stem":"기온이 높고 비가 많이 내리는 지역에서 발달하기 쉬운 음식 문화는 어느 것인가요?","options":[{"t":"벼농사가 활발해 쌀로 만든 음식","correct":true},{"t":"얼음으로만 만든 음식","mis":"SO5-1-u2-X03"},{"t":"물을 거의 쓰지 않는 음식","mis":"SO5-1-u2-X03"},{"t":"바람에 말린 음식만","mis":"SO5-1-u2-X03"}],"explanation":["벼는 물이 많이 필요해요.","덥고 비가 많으면 벼가 잘 자라요.","쌀 음식이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#9','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C2',2,'ox','auto','바람이 강하게 부는 지역에서는 바람의 힘으로 전기를 만드는 시설이 발달하기 쉬워요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"ox","stem":"바람이 강하게 부는 지역에서는 바람의 힘으로 전기를 만드는 시설이 발달하기 쉬워요.","answer":"O","reason_options":[{"t":"그 지역의 기후를 이용해 산업을 일으키기 때문에","correct":true},{"t":"바람은 기후와 아무 관계가 없기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["기후는 산업에도 영향을 줘요.","바람이 세면 그 힘을 써요.","바람으로 전기를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#10','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',3,'error','auto','날씨와 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C1","difficulty":3,"kind":"error","stem":"날씨와 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「내일 소풍 가니까 기후를 꼭 확인해야겠어.」","correct":true,"mis_target":"SO5-1-u2-X01"},{"t":"준혁 — 「기후는 여러 해 기록을 모아야 알 수 있어.」","mis":"SO5-1-u2-X01"},{"t":"나린 — 「날씨는 하루 사이에도 바뀌어.」","mis":"SO5-1-u2-X01"}],"explanation":["내일 하루의 대기 상태는 날씨예요.","소풍 전에는 날씨를 봐요.","윤서는 기후라고 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#1','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',2,'sa','auto','날씨와 달리 여러 해에 걸쳐 나타나는 평균적이며 종합적인 대기 상태를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"sa","stem":"날씨와 달리 여러 해에 걸쳐 나타나는 평균적이며 종합적인 대기 상태를 두 글자로 무엇이라고 하나요?","answer":["기후"],"explanation":["하루가 아니라 오랜 기간이에요.","평균적인 모습이에요.","기후예요."],"mis":"SO5-1-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#2','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',2,'match','auto','생활 모습 카드를 보고 카드와 영향을 준 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"match","stem":"생활 모습 카드를 보고 카드와 영향을 준 것을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"덥고 비가 많은 기후"},{"l":"㉡","r":"바람이 센 기후"},{"l":"㉢","r":"눈이 많은 겨울 기후"},{"l":"㉣","r":"그날의 날씨"}],"mis":"SO5-1-u2-X03","explanation":["㉠은 벼농사, ㉡은 바람 발전이에요.","㉢은 해마다 같은 때 여는 축제예요.","㉣은 그날 하루의 소나기 때문이에요."],"asset":{"type":"passage","lines":["㉠ 기온이 높고 비가 많은 들판 — 논이 넓고 밥을 지어 먹는다.","㉡ 바람이 늘 세게 부는 언덕 — 커다란 날개가 돌아간다.","㉢ 겨울에 눈이 많이 쌓이는 마을 — 해마다 같은 때 축제를 연다.","㉣ 지난 토요일 — 소나기가 와서 운동회를 미루었다."],"title":"생활 모습 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#3','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',3,'mc','auto','「오늘은 맑고 쾌청한 기후래요」라는 말이 알맞지 않은 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C1","difficulty":3,"kind":"mc","stem":"「오늘은 맑고 쾌청한 기후래요」라는 말이 알맞지 않은 까닭은 어느 것인가요?","options":[{"t":"하루의 대기 상태는 기후가 아니라 날씨이기 때문에","correct":true},{"t":"기후는 비가 오는 날에만 쓰는 말이기 때문에","mis":"SO5-1-u2-X01"},{"t":"맑은 날에는 대기가 없기 때문에","mis":"SO5-1-u2-X02"},{"t":"기후는 바람이 불 때만 쓰는 말이기 때문에","mis":"SO5-1-u2-X02"}],"explanation":["「오늘」은 하루예요.","하루의 대기 상태는 날씨예요.","기후는 여러 해를 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#4','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',3,'mc','auto','생활 모습 카드 가운데 기후가 아니라 날씨의 영향을 받은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"mc","stem":"생활 모습 카드 가운데 기후가 아니라 날씨의 영향을 받은 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SO5-1-u2-X03"},{"t":"㉡","mis":"SO5-1-u2-X03"},{"t":"㉢","mis":"SO5-1-u2-X03"}],"explanation":["㉠~㉢은 해마다 되풀이되는 모습이에요.","㉣은 지난 토요일 하루의 일이에요.","그래서 날씨의 영향이에요."],"asset":{"type":"passage","lines":["㉠ 기온이 높고 비가 많은 들판 — 논이 넓고 밥을 지어 먹는다.","㉡ 바람이 늘 세게 부는 언덕 — 커다란 날개가 돌아간다.","㉢ 겨울에 눈이 많이 쌓이는 마을 — 해마다 같은 때 축제를 연다.","㉣ 지난 토요일 — 소나기가 와서 운동회를 미루었다."],"title":"생활 모습 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#5','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',3,'mc','auto','세 해 동안 계절마다 기온·강수·바람을 기록해 모았어요. 이 기록으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C1","difficulty":3,"kind":"mc","stem":"세 해 동안 계절마다 기온·강수·바람을 기록해 모았어요. 이 기록으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"그 지역 계절별 기후의 특징","correct":true},{"t":"내일 비가 올지","mis":"SO5-1-u2-X01"},{"t":"그 지역에 사는 사람 수","mis":"SO5-1-u2-X02"},{"t":"그 지역 산의 높이","mis":"SO5-1-u2-X02"}],"explanation":["여러 해 기록을 모았어요.","평균적인 모습이 드러나요.","앞날의 날씨는 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#6','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',3,'ox','auto','계절마다 입는 옷이 다른 것도 기후가 생활에 주는 영향이에요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"ox","stem":"계절마다 입는 옷이 다른 것도 기후가 생활에 주는 영향이에요.","answer":"O","reason_options":[{"t":"해마다 되풀이되는 계절의 기온에 맞추어 옷을 입기 때문에","correct":true},{"t":"옷은 기후가 아니라 땅의 생김새에 따라 정하기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["여름엔 얇은 옷을 입어요.","겨울엔 두꺼운 옷을 입어요.","기후에 맞춘 의생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#7','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',3,'error','auto','기후와 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"error","stem":"기후와 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「비 때문에 체육 대회가 미뤄진 건 우리 지역 기후 탓이야.」","correct":true,"mis_target":"SO5-1-u2-X03"},{"t":"민지 — 「겨울에 눈이 많은 곳은 눈 축제를 열기 좋아.」","mis":"SO5-1-u2-X03"},{"t":"하율 — 「기후는 사람들이 먹고 입고 사는 모습에 영향을 줘.」","mis":"SO5-1-u2-X03"}],"explanation":["하루의 비는 날씨예요.","기후 탓이라고 할 수 없어요.","태오의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#8','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',4,'mc','auto','기후를 알아보는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02','SO5-1-u2-X25']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C1","difficulty":4,"kind":"mc","stem":"기후를 알아보는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 해 동안 쌓인 기온·강수·바람 기록을 함께 살펴보고 생활과 이어 생각한다","correct":true},{"t":"오늘 하루 하늘만 보고 그 지역의 기후를 정한다","mis":"SO5-1-u2-X01"},{"t":"기온만 재면 되므로 비와 바람은 살피지 않는다","mis":"SO5-1-u2-X02"},{"t":"기후는 생활과 관계없으니 기록만 외운다","mis":"SO5-1-u2-X25"}],"explanation":["여러 해를 모아요.","세 요소를 두루 봐요.","생활과 이어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#9','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',4,'mc','auto','기후가 우리 생활에 주는 영향을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X03','SO5-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":4,"kind":"mc","stem":"기후가 우리 생활에 주는 영향을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"먹는 음식, 입는 옷과 사는 집, 산업 발전까지 두루 영향을 준다","correct":true},{"t":"입는 옷에만 영향을 주고 음식과는 관계없다","mis":"SO5-1-u2-X03"},{"t":"산업에만 영향을 주고 생활과는 관계없다","mis":"SO5-1-u2-X03"},{"t":"비가 오는 날에만 생활에 영향을 준다","mis":"SO5-1-u2-X01"}],"explanation":["의식주 모두에 영향을 줘요.","산업에도 영향을 줘요.","기후에 맞추어 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#10','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',4,'essay','teacher','날씨와 기후의 차이를 쓰고, 기후가 우리 생활에 주는 영향을 보기 하나를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C1","difficulty":4,"kind":"essay","stem":"날씨와 기후의 차이를 쓰고, 기후가 우리 생활에 주는 영향을 보기 하나를 들어 쓰세요.","answer_guide":{"answer":"예: 날씨는 짧은 시간 동안의 대기 상태라 하루 사이에도 바뀌고, 기후는 오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태이다. 기온이 높고 비가 많은 지역에서는 벼농사가 활발해 쌀로 만든 음식이 발달했다.","scoring_points":["날씨의 뜻을 썼는가","기후의 뜻을 날씨와 견주어 썼는가","기후와 생활을 잇는 보기를 들었는가"]},"explanation":["날씨는 짧은 시간이에요.","기후는 여러 해의 평균이에요.","생활과 이어 보기를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#1','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',1,'mc','auto','여름에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"여름에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?","options":[{"t":"남쪽 바다에서 오는 뜨겁고 습한 바람","correct":true},{"t":"북서쪽 육지에서 오는 차갑고 건조한 바람","mis":"SO5-1-u2-X04"},{"t":"동쪽 하늘 높은 곳에서 내려오는 서늘한 바람","mis":"SO5-1-u2-X04"},{"t":"서쪽에서 오는 메마른 바람","mis":"SO5-1-u2-X04"}],"explanation":["여름 바람은 바다에서 와요.","바다를 지나 물기가 많아요.","그래서 덥고 비가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#2','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',1,'mc','auto','겨울에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"겨울에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?","options":[{"t":"북서쪽 육지에서 오는 차갑고 건조한 바람","correct":true},{"t":"남쪽 바다에서 오는 뜨겁고 습한 바람","mis":"SO5-1-u2-X04"},{"t":"동쪽 바다에서 오는 따뜻한 바람","mis":"SO5-1-u2-X04"},{"t":"남서쪽에서 오는 습한 바람","mis":"SO5-1-u2-X04"}],"explanation":["겨울 바람은 손발을 시리게 해요.","넓은 육지를 지나와요.","차갑고 건조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#3','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',1,'sa','auto','평균 기온 분포도에서 기온이 같은 곳을 이은 선을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"sa","stem":"평균 기온 분포도에서 기온이 같은 곳을 이은 선을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["등온선"],"explanation":["같을 등, 따뜻할 온이에요.","기온이 같은 곳을 이어요.","등온선이에요."],"mis":"SO5-1-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#4','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C4',1,'ox','auto','우리나라에서 강수량이 가장 많은 계절은 겨울이에요.',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"ox","stem":"우리나라에서 강수량이 가장 많은 계절은 겨울이에요.","answer":"X","reason_options":[{"t":"연 강수량의 절반 이상이 여름에 내리기 때문에","correct":true},{"t":"겨울에는 날마다 눈이 많이 쌓이기 때문에","mis":"SO5-1-u2-X07"}],"mis":"SO5-1-u2-X07","explanation":["여름에 비가 몰려요.","7월·8월 막대가 높아요.","겨울은 대체로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#5','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',2,'mc','auto','우리나라에서 대체로 남쪽으로 갈수록 기온은 어떻게 되나요?',ARRAY['SO5-1-u2-X05']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"mc","stem":"우리나라에서 대체로 남쪽으로 갈수록 기온은 어떻게 되나요?","options":[{"t":"높아진다","correct":true},{"t":"낮아진다","mis":"SO5-1-u2-X05"},{"t":"똑같다","mis":"SO5-1-u2-X05"},{"t":"계절마다 반대로 바뀐다","mis":"SO5-1-u2-X05"}],"explanation":["우리나라는 남북으로 길어요.","남쪽이 더 따뜻해요.","남쪽으로 갈수록 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#6','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',2,'mc','auto','남쪽과 북쪽의 계절별 평균 기온 자료에서 두 곳의 기온 차이가 더 큰 계절은 언제인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X06']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"mc","stem":"남쪽과 북쪽의 계절별 평균 기온 자료에서 두 곳의 기온 차이가 더 큰 계절은 언제인가요?","options":[{"t":"겨울","correct":true},{"t":"여름","mis":"SO5-1-u2-X05"},{"t":"두 계절이 같다","mis":"SO5-1-u2-X05"},{"t":"자료로 알 수 없다","mis":"SO5-1-u2-X06"}],"explanation":["여름 차이는 3.5 ℃예요.","겨울 차이는 21.1 ℃예요.","겨울에 훨씬 커요."],"asset":{"type":"passage","lines":["여름 평균 기온 — 북쪽 중강진 21.4 ℃ · 남쪽 서귀포 24.9 ℃","여름 두 곳의 차이 — 3.5 ℃","겨울 평균 기온 — 북쪽 중강진 -12.8 ℃ · 남쪽 서귀포 8.3 ℃","겨울 두 곳의 차이 — 21.1 ℃"],"title":"남쪽과 북쪽의 계절별 평균 기온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#7','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C4',2,'mc','auto','강수량 자료 메모에서 연 강수량이 가장 많은 곳은 어디인가요?',ARRAY['SO5-1-u2-X07','SO5-1-u2-X06']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C4","difficulty":2,"kind":"mc","stem":"강수량 자료 메모에서 연 강수량이 가장 많은 곳은 어디인가요?","options":[{"t":"제주","correct":true},{"t":"중강진","mis":"SO5-1-u2-X07"},{"t":"서울","mis":"SO5-1-u2-X06"},{"t":"세 곳이 같다","mis":"SO5-1-u2-X06"}],"explanation":["세 수를 견주어요.","제주가 가장 커요.","남쪽으로 갈수록 많아요."],"asset":{"type":"passage","lines":["연 강수량 — 북쪽 중강진 약 638 mm · 서울 약 1,418 mm · 제주 약 1,502 mm","서울의 달별 강수량 — 7월과 8월 막대가 가장 높다.","서울의 달별 강수량 — 12월·1월·2월 막대는 아주 낮다.","분포도 — 파란색이 진할수록 강수량이 많다."],"title":"강수량 자료 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#8','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',2,'mc','auto','일기 예보는 어느 계절의 예보일까요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X06']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"mc","stem":"일기 예보는 어느 계절의 예보일까요?","options":[{"t":"겨울","correct":true},{"t":"여름","mis":"SO5-1-u2-X04"},{"t":"봄","mis":"SO5-1-u2-X04"},{"t":"계절을 알 수 없다","mis":"SO5-1-u2-X06"}],"explanation":["북서쪽에서 찬 바람이 분대요.","기온이 크게 떨어진대요.","겨울철 예보예요."],"asset":{"type":"passage","lines":["비가 그친 뒤 오늘 밤부터 기온이 크게 떨어지겠습니다.","북서쪽에서 찬 바람이 불어오겠습니다.","내일 아침은 오늘보다 5~10 ℃ 낮겠습니다."],"title":"어느 날의 일기 예보(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#9','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C4',2,'ox','auto','연 강수량 분포도에서 파란색이 진할수록 강수량이 많아요.',ARRAY['SO5-1-u2-X06']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C4","difficulty":2,"kind":"ox","stem":"연 강수량 분포도에서 파란색이 진할수록 강수량이 많아요.","answer":"O","reason_options":[{"t":"분포도는 강수량이 많은 곳을 더 진한 색으로 나타내기 때문에","correct":true},{"t":"진한 파란색은 바다를 나타내기 때문에","mis":"SO5-1-u2-X06"}],"mis":"SO5-1-u2-X06","explanation":["분포도에는 범례가 있어요.","진할수록 많아요.","남쪽이 더 진해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#10','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C2',3,'mc','auto','같은 2월에 인천에는 눈이 쌓였는데 제주에서는 밭에서 무를 거두었어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X07']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"mc","stem":"같은 2월에 인천에는 눈이 쌓였는데 제주에서는 밭에서 무를 거두었어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"제주가 더 남쪽에 있어 겨울 평균 기온이 높기 때문에","correct":true},{"t":"인천이 제주보다 남쪽에 있기 때문에","mis":"SO5-1-u2-X05"},{"t":"제주에는 겨울이 없기 때문에","mis":"SO5-1-u2-X05"},{"t":"두 곳의 강수량이 같기 때문에","mis":"SO5-1-u2-X07"}],"explanation":["제주는 남쪽에 있어요.","겨울에도 따뜻해요.","그래서 밭농사를 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#1','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C4',2,'match','auto','계절과 그 계절의 기후 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C4","difficulty":2,"kind":"match","stem":"계절과 그 계절의 기후 특징을 알맞게 이으세요.","pairs":[{"l":"봄","r":"온화하고 건조하다"},{"l":"여름","r":"덥고 비가 자주 온다"},{"l":"가을","r":"맑고 건조하다"},{"l":"겨울","r":"춥고 건조하며 눈이 온다"}],"mis":"SO5-1-u2-X07","explanation":["봄과 가을은 건조해요.","여름은 비가 많아요.","겨울은 춥고 눈이 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#2','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',2,'sa','auto','여름 바람은 바다에서, 겨울 바람은 어디에서 불어오나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"sa","stem":"여름 바람은 바다에서, 겨울 바람은 어디에서 불어오나요? 두 글자로 쓰세요.","answer":["육지"],"explanation":["겨울 바람은 북서쪽에서 와요.","넓은 땅을 지나와요.","육지예요."],"mis":"SO5-1-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#3','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',3,'mc','auto','여름과 겨울에 남북의 기온 차이가 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X04']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"mc","stem":"여름과 겨울에 남북의 기온 차이가 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여름에는 남북 모두 덥지만 겨울에는 북쪽이 크게 추워지기 때문에","correct":true},{"t":"여름에는 북쪽만 크게 더워지기 때문에","mis":"SO5-1-u2-X05"},{"t":"겨울에는 남쪽이 북쪽보다 더 추워지기 때문에","mis":"SO5-1-u2-X05"},{"t":"두 계절의 바람이 똑같기 때문에","mis":"SO5-1-u2-X04"}],"explanation":["여름 차이는 작아요.","겨울 차이는 커요.","북쪽이 크게 추워져서예요."],"asset":{"type":"passage","lines":["여름 평균 기온 — 북쪽 중강진 21.4 ℃ · 남쪽 서귀포 24.9 ℃","여름 두 곳의 차이 — 3.5 ℃","겨울 평균 기온 — 북쪽 중강진 -12.8 ℃ · 남쪽 서귀포 8.3 ℃","겨울 두 곳의 차이 — 21.1 ℃"],"title":"남쪽과 북쪽의 계절별 평균 기온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#4','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',3,'mc','auto','바람이 계절마다 다른 성질을 띠는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"mc","stem":"바람이 계절마다 다른 성질을 띠는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바람이 지나온 곳이 바다인지 육지인지가 다르기 때문에","correct":true},{"t":"바람은 하늘 높은 곳에서만 생기기 때문에","mis":"SO5-1-u2-X04"},{"t":"바람은 계절과 상관없이 늘 같기 때문에","mis":"SO5-1-u2-X04"},{"t":"사람들이 바람의 방향을 정하기 때문에","mis":"SO5-1-u2-X04"}],"explanation":["바다를 지나면 습해요.","육지를 지나면 건조해요.","지나온 곳이 성질을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#5','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C4',3,'mc','auto','강수량 자료 메모를 보고 알 수 있는 것을 가장 바르게 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C4","difficulty":3,"kind":"mc","stem":"강수량 자료 메모를 보고 알 수 있는 것을 가장 바르게 묶은 것은 어느 것인가요?","options":[{"t":"남쪽으로 갈수록 연 강수량이 많고, 비는 여름에 몰린다","correct":true},{"t":"북쪽으로 갈수록 연 강수량이 많고, 비는 겨울에 몰린다","mis":"SO5-1-u2-X07"},{"t":"어디나 강수량이 같고, 비는 봄에 몰린다","mis":"SO5-1-u2-X07"},{"t":"남쪽으로 갈수록 적고, 달마다 비가 고르게 온다","mis":"SO5-1-u2-X07"}],"explanation":["중강진·서울·제주를 견줘요.","남쪽으로 갈수록 많아요.","7·8월 막대가 높아요."],"asset":{"type":"passage","lines":["연 강수량 — 북쪽 중강진 약 638 mm · 서울 약 1,418 mm · 제주 약 1,502 mm","서울의 달별 강수량 — 7월과 8월 막대가 가장 높다.","서울의 달별 강수량 — 12월·1월·2월 막대는 아주 낮다.","분포도 — 파란색이 진할수록 강수량이 많다."],"title":"강수량 자료 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#6','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C2',3,'ox','auto','눈꽃 축제는 불꽃 축제보다 기후의 영향을 더 많이 받는 축제예요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"ox","stem":"눈꽃 축제는 불꽃 축제보다 기후의 영향을 더 많이 받는 축제예요.","answer":"O","reason_options":[{"t":"눈이 많이 내리는 겨울에 해마다 열기 알맞기 때문에","correct":true},{"t":"불꽃 축제는 비가 오면 못 여니 기후의 영향이 가장 크기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["눈꽃 축제는 겨울 기후에 맞춰 열어요.","불꽃 축제가 비로 미뤄지는 건 날씨 때문이에요.","그래서 눈꽃 축제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#7','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',3,'error','auto','등온선을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X06','SO5-1-u2-X05']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"error","stem":"등온선을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「등온선은 비가 같은 만큼 내린 곳을 이은 선이야.」","correct":true,"mis_target":"SO5-1-u2-X06"},{"t":"채원 — 「선 끝에 적힌 숫자로 그곳 기온을 알 수 있어.」","mis":"SO5-1-u2-X06"},{"t":"지후 — 「등온선을 보면 남쪽이 더 따뜻한 걸 알 수 있어.」","mis":"SO5-1-u2-X05"}],"explanation":["등온선은 기온이 같은 곳을 이어요.","강수량을 잇는 선이 아니에요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#8','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C4',4,'mc','auto','여름에 비가 많이 내리는 까닭을 바람과 이어 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X05']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C4","difficulty":4,"kind":"mc","stem":"여름에 비가 많이 내리는 까닭을 바람과 이어 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"남쪽 바다를 지나온 바람이 물기를 많이 머금고 불어오기 때문에","correct":true},{"t":"북서쪽 육지를 지나온 바람이 물기를 가져오기 때문에","mis":"SO5-1-u2-X04"},{"t":"여름에는 바람이 전혀 불지 않기 때문에","mis":"SO5-1-u2-X04"},{"t":"여름에는 기온이 낮아 구름이 잘 생기기 때문에","mis":"SO5-1-u2-X05"}],"explanation":["여름 바람은 바다에서 와요.","바다를 지나 습해요.","그래서 비가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#9','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',4,'mc','auto','「계절 → 바람이 불어오는 곳 → 바람의 성질 → 기온과 강수」 차례로 겨울을 바르게 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X07']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C3","difficulty":4,"kind":"mc","stem":"「계절 → 바람이 불어오는 곳 → 바람의 성질 → 기온과 강수」 차례로 겨울을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"겨울 → 북서쪽 육지 → 차갑고 건조함 → 기온이 낮고 강수가 적음","correct":true},{"t":"겨울 → 남쪽 바다 → 뜨겁고 습함 → 기온이 높고 강수가 많음","mis":"SO5-1-u2-X04"},{"t":"겨울 → 북서쪽 육지 → 뜨겁고 습함 → 기온이 높고 강수가 적음","mis":"SO5-1-u2-X04"},{"t":"겨울 → 동쪽 바다 → 차갑고 습함 → 기온이 낮고 강수가 많음","mis":"SO5-1-u2-X07"}],"explanation":["겨울 바람은 북서쪽 육지에서 와요.","차갑고 건조해요.","그래서 춥고 강수가 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#10','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',4,'essay','teacher','여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 바람 때문에 두 계절의 기온과 강수가 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C3","difficulty":4,"kind":"essay","stem":"여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 바람 때문에 두 계절의 기온과 강수가 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 여름에는 남쪽 바다에서 뜨겁고 습한 바람이 불어와 기온이 높고 비가 많이 내린다. 겨울에는 북서쪽 육지에서 차갑고 건조한 바람이 불어와 기온이 낮고 강수가 적다.","scoring_points":["여름 바람의 방향과 성질을 썼는가","겨울 바람의 방향과 성질을 썼는가","바람과 기온·강수를 이어 썼는가"]},"explanation":["여름 — 남쪽 바다예요.","겨울 — 북서쪽 육지예요.","바람이 기온과 강수를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#1','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',1,'mc','auto','자연재해의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X08','SO5-1-u2-X03','SO5-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"자연재해의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"피할 수 없는 자연 현상으로 사람들이 입는 생명이나 재산상의 피해","correct":true},{"t":"사람이 일부러 일으킨 사고","mis":"SO5-1-u2-X08"},{"t":"계절마다 달라지는 옷차림","mis":"SO5-1-u2-X03"},{"t":"여러 해 동안 나타나는 평균적인 날씨","mis":"SO5-1-u2-X01"}],"explanation":["자연 현상에서 시작해요.","사람이 피해를 입어요.","그래서 자연재해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#2','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',1,'mc','auto','봄에 우리나라에서 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"봄에 우리나라에서 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?","options":[{"t":"황사와 가뭄","correct":true},{"t":"폭설과 한파","mis":"SO5-1-u2-X09"},{"t":"폭염과 호우","mis":"SO5-1-u2-X09"},{"t":"태풍과 홍수","mis":"SO5-1-u2-X09"}],"explanation":["모래 먼지가 날아오는 때예요.","비가 오래 오지 않기도 해요.","봄은 황사와 가뭄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#3','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',1,'sa','auto','많은 비와 강한 바람을 몰고 와 여름과 가을 사이에 우리나라에 영향을 주는 자연재해를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"sa","stem":"많은 비와 강한 바람을 몰고 와 여름과 가을 사이에 우리나라에 영향을 주는 자연재해를 쓰세요.","answer":["태풍"],"explanation":["비와 바람이 함께 몰아쳐요.","남서쪽에서 북동쪽으로 지나가요.","태풍이에요."],"mis":"SO5-1-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#4','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C6',1,'ox','auto','기상 특보는 자연재해를 주의시키려고 미리 알려 주는 정보예요.',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C6","difficulty":1,"kind":"ox","stem":"기상 특보는 자연재해를 주의시키려고 미리 알려 주는 정보예요.","answer":"O","reason_options":[{"t":"주의보·경보로 피해가 생기기 전에 알려 주기 때문에","correct":true},{"t":"자연재해가 끝난 뒤 피해를 세어 알려 주는 것이기 때문에","mis":"SO5-1-u2-X10"}],"mis":"SO5-1-u2-X10","explanation":["「○○ 주의보」처럼 알려요.","더 큰 피해가 걱정되면 경보예요.","미리 알려 주는 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#5','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'match','auto','재해 소식 카드를 보고 카드와 자연재해를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"match","stem":"재해 소식 카드를 보고 카드와 자연재해를 알맞게 이으세요.","pairs":[{"l":"㉠","r":"황사"},{"l":"㉡","r":"가뭄"},{"l":"㉣","r":"홍수"},{"l":"㉥","r":"한파"}],"mis":"SO5-1-u2-X09","explanation":["㉠은 모래 먼지, ㉡은 비가 오지 않음이에요.","㉣은 하천이 넘쳤어요.","㉥은 갑자기 추워졌어요."],"asset":{"type":"passage","lines":["㉠ 사막의 모래 먼지가 바람을 타고 날아와 하늘이 뿌옇다.","㉡ 오랫동안 비가 오지 않아 논밭이 갈라졌다.","㉢ 일상생활이 힘들 만큼 무더운 날이 이어진다.","㉣ 많은 비가 내려 하천이 넘치고 도로가 잠겼다.","㉤ 강한 바람과 많은 비가 남서쪽에서 북동쪽으로 지나갔다.","㉥ 기온이 갑자기 내려가 수도관이 얼었다."],"title":"재해 소식 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#6','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'mc','auto','재해 소식 카드 ㉤은 어떤 자연재해인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"mc","stem":"재해 소식 카드 ㉤은 어떤 자연재해인가요?","options":[{"t":"태풍","correct":true},{"t":"폭설","mis":"SO5-1-u2-X09"},{"t":"황사","mis":"SO5-1-u2-X09"},{"t":"폭염","mis":"SO5-1-u2-X09"}],"explanation":["강한 바람과 많은 비예요.","남서쪽에서 북동쪽으로 지나갔어요.","태풍이에요."],"asset":{"type":"passage","lines":["㉠ 사막의 모래 먼지가 바람을 타고 날아와 하늘이 뿌옇다.","㉡ 오랫동안 비가 오지 않아 논밭이 갈라졌다.","㉢ 일상생활이 힘들 만큼 무더운 날이 이어진다.","㉣ 많은 비가 내려 하천이 넘치고 도로가 잠겼다.","㉤ 강한 바람과 많은 비가 남서쪽에서 북동쪽으로 지나갔다.","㉥ 기온이 갑자기 내려가 수도관이 얼었다."],"title":"재해 소식 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#7','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'mc','auto','겨울에 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"mc","stem":"겨울에 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?","options":[{"t":"폭설과 한파","correct":true},{"t":"황사와 가뭄","mis":"SO5-1-u2-X09"},{"t":"폭염과 호우","mis":"SO5-1-u2-X09"},{"t":"홍수와 태풍","mis":"SO5-1-u2-X09"}],"explanation":["짧은 시간에 눈이 많이 내려요.","기온이 갑자기 내려가요.","폭설과 한파예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#8','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C6',2,'mc','auto','태풍 주의보가 내려졌을 때 알맞은 행동은 어느 것인가요?',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"mc","stem":"태풍 주의보가 내려졌을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"외출을 삼가고 바람에 넘어지기 쉬운 물건을 미리 정리한다","correct":true},{"t":"바닷가에 나가 큰 파도를 구경한다","mis":"SO5-1-u2-X10"},{"t":"창문을 활짝 열어 바람이 지나가게 한다","mis":"SO5-1-u2-X10"},{"t":"특보는 어른들의 일이니 평소처럼 밖에서 논다","mis":"SO5-1-u2-X10"}],"explanation":["강한 바람은 위험해요.","밖에 나가지 않아요.","날아갈 물건을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#9','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'ox','auto','비가 많이 내리는 현상을 호우, 비가 많이 내려 물이 흘러넘치는 현상을 홍수라고 해요.',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"ox","stem":"비가 많이 내리는 현상을 호우, 비가 많이 내려 물이 흘러넘치는 현상을 홍수라고 해요.","answer":"O","reason_options":[{"t":"호우는 비가 많이 오는 것이고 홍수는 그 물이 넘치는 것이기 때문에","correct":true},{"t":"호우와 홍수는 겨울에 눈이 많이 내리는 현상이기 때문에","mis":"SO5-1-u2-X09"}],"mis":"SO5-1-u2-X09","explanation":["호우는 많은 비예요.","홍수는 넘치는 물이에요.","둘 다 여름에 잦아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#10','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',3,'mc','auto','우리나라에서 계절마다 다른 자연재해가 자주 발생하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X08','SO5-1-u2-X09']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"mc","stem":"우리나라에서 계절마다 다른 자연재해가 자주 발생하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"계절마다 바람·기온·강수의 정도가 달라 기후 특성이 다르기 때문에","correct":true},{"t":"지역마다 사는 사람 수가 다르기 때문에","mis":"SO5-1-u2-X08"},{"t":"자연재해는 아무 때나 똑같이 일어나기 때문에","mis":"SO5-1-u2-X09"},{"t":"여름에만 자연재해가 일어나기 때문에","mis":"SO5-1-u2-X09"}],"explanation":["지난 차시를 떠올려요.","계절마다 기후가 달라요.","그래서 재해도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#1','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',2,'match','auto','자연재해와 그에 대비하는 시설을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"match","stem":"자연재해와 그에 대비하는 시설을 알맞게 이으세요.","pairs":[{"l":"가뭄","r":"저수지와 댐"},{"l":"호우·홍수","r":"제방"},{"l":"폭염","r":"그늘막과 무더위 쉼터"}],"mis":"SO5-1-u2-X10","explanation":["가뭄에는 물을 모아 둬요.","홍수에는 둑을 쌓아요.","폭염에는 더위를 피할 곳을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#2','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',2,'sa','auto','자연재해가 예상될 때 휴대 전화로 보내 위험을 알려 주는 것은 무엇인가요? (긴급 재난 □□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"sa","stem":"자연재해가 예상될 때 휴대 전화로 보내 위험을 알려 주는 것은 무엇인가요? (긴급 재난 □□)","answer":["문자"],"explanation":["주머니에서 울려요.","위험을 미리 알려요.","긴급 재난 문자예요."],"mis":"SO5-1-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#3','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',3,'mc','auto','신문 기사에서 기상청이 대비하라고 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09','SO5-1-u2-X08']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"mc","stem":"신문 기사에서 기상청이 대비하라고 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"태풍이 많은 비와 강한 바람으로 주택·도로·농작물에 피해를 줄 수 있기 때문에","correct":true},{"t":"태풍이 오면 기온이 갑자기 크게 떨어지기 때문에","mis":"SO5-1-u2-X09"},{"t":"태풍은 오랫동안 비가 오지 않게 하기 때문에","mis":"SO5-1-u2-X09"},{"t":"태풍은 사람이 일으키는 사고이기 때문에","mis":"SO5-1-u2-X08"}],"explanation":["태풍은 비와 바람을 몰고 와요.","집과 길이 잠기기도 해요.","그래서 미리 대비해요."],"asset":{"type":"passage","lines":["오늘 오후 남해안으로 태풍이 올라올 것으로 보인다.","전국 곳곳에 태풍 주의보와 경보가 내려졌다.","기상청은 인명과 재산 피해가 없도록 대비해 달라고 했다."],"title":"어느 해 여름의 신문 기사(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#4','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',3,'mc','auto','사람이 하는 일이 자연재해의 피해를 더 키우기도 한다는 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X11']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"mc","stem":"사람이 하는 일이 자연재해의 피해를 더 키우기도 한다는 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"숲을 농경지로 일구거나 물길을 바꾸면 가뭄이나 홍수 피해가 커지기도 한다","correct":true},{"t":"사람이 하는 일은 자연재해와 아무 관계가 없다","mis":"SO5-1-u2-X11"},{"t":"나무를 심으면 가뭄이 더 심해진다","mis":"SO5-1-u2-X11"},{"t":"도로를 만들면 자연재해가 사라진다","mis":"SO5-1-u2-X11"}],"explanation":["숲은 물을 머금어요.","물길을 바꾸면 흐름이 달라져요.","피해가 커지기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#5','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C5',3,'ox','auto','비가 많이 내렸지만 아무도 다치지 않고 재산 피해도 없었다면 그 비 자체를 자연재해라고 부르기는 어려워요.',ARRAY['SO5-1-u2-X08']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"ox","stem":"비가 많이 내렸지만 아무도 다치지 않고 재산 피해도 없었다면 그 비 자체를 자연재해라고 부르기는 어려워요.","answer":"O","reason_options":[{"t":"자연재해는 자연 현상으로 사람이 피해를 입었을 때를 말하기 때문에","correct":true},{"t":"비가 내리기만 하면 언제나 자연재해이기 때문에","mis":"SO5-1-u2-X08"}],"mis":"SO5-1-u2-X08","explanation":["자연 현상만으로는 재해가 아니에요.","사람의 피해가 있어야 해요.","그래서 부르기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#6','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',3,'error','auto','자연재해에 대비하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"error","stem":"자연재해에 대비하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서율 — 「국민 행동 요령은 어른들이 알면 되니 나는 몰라도 돼.」","correct":true,"mis_target":"SO5-1-u2-X10"},{"t":"지환 — 「기상 특보가 나오면 방송이나 인터넷으로 확인해.」","mis":"SO5-1-u2-X10"},{"t":"예린 — 「우리 지역의 대비 시설을 조사해 친구들과 나눠 볼래.」","mis":"SO5-1-u2-X10"}],"explanation":["국민 행동 요령은 국민 누구나의 몫이에요.","어린이도 알아야 해요.","나를 지키는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#7','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C5',3,'mc','auto','재해 소식 카드 가운데 여름에 자주 발생하는 자연재해만 고른 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"mc","stem":"재해 소식 카드 가운데 여름에 자주 발생하는 자연재해만 고른 것은 어느 것인가요?","options":[{"t":"㉢과 ㉣","correct":true},{"t":"㉠과 ㉡","mis":"SO5-1-u2-X09"},{"t":"㉥과 ㉠","mis":"SO5-1-u2-X09"},{"t":"㉡과 ㉥","mis":"SO5-1-u2-X09"}],"explanation":["㉢은 폭염이에요.","㉣은 홍수예요.","둘 다 여름에 잦아요."],"asset":{"type":"passage","lines":["㉠ 사막의 모래 먼지가 바람을 타고 날아와 하늘이 뿌옇다.","㉡ 오랫동안 비가 오지 않아 논밭이 갈라졌다.","㉢ 일상생활이 힘들 만큼 무더운 날이 이어진다.","㉣ 많은 비가 내려 하천이 넘치고 도로가 잠겼다.","㉤ 강한 바람과 많은 비가 남서쪽에서 북동쪽으로 지나갔다.","㉥ 기온이 갑자기 내려가 수도관이 얼었다."],"title":"재해 소식 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#8','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',4,'mc','auto','자연재해를 대하는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X10','SO5-1-u2-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"mc","stem":"자연재해를 대하는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연재해는 막을 수 없지만 시설·훈련·특보와 국민 행동 요령으로 피해를 줄일 수 있다","correct":true},{"t":"자연재해는 막을 수 없으니 아무 준비도 하지 않아도 된다","mis":"SO5-1-u2-X10"},{"t":"시설만 지어 두면 사람은 아무것도 하지 않아도 된다","mis":"SO5-1-u2-X10"},{"t":"자연재해는 사람이 일으키니 그 사람만 조심하면 된다","mis":"SO5-1-u2-X08"}],"explanation":["재해는 피할 수 없어요.","피해는 줄일 수 있어요.","시설·훈련·특보·행동 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#9','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',4,'mc','auto','날씨를 예측해 알려 주는 예보 분석관이 되려는 사람에게 가장 필요한 자세는 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X25','SO5-1-u2-X10']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"mc","stem":"날씨를 예측해 알려 주는 예보 분석관이 되려는 사람에게 가장 필요한 자세는 어느 것인가요?","options":[{"t":"하늘의 기상 현상에 관심을 두고 새로운 기술과 지식을 꾸준히 배우는 자세","correct":true},{"t":"하루 날씨만 보고 그 지역 기후를 정하는 자세","mis":"SO5-1-u2-X01"},{"t":"지형 이름을 빠짐없이 외우는 자세","mis":"SO5-1-u2-X25"},{"t":"특보는 미리 알리지 않고 지나간 뒤에 알리는 자세","mis":"SO5-1-u2-X10"}],"explanation":["기상학 지식이 필요해요.","하늘에 관심을 둬요.","계속 배우려는 자세가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#10','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',4,'essay','teacher','태풍 주의보가 내려졌다는 소식을 들었어요. 태풍이 어떤 피해를 줄 수 있는지 쓰고, 내가 실천할 국민 행동 요령 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"essay","stem":"태풍 주의보가 내려졌다는 소식을 들었어요. 태풍이 어떤 피해를 줄 수 있는지 쓰고, 내가 실천할 국민 행동 요령 두 가지를 쓰세요.","answer_guide":{"answer":"예: 태풍은 많은 비와 강한 바람을 몰고 와 도로와 주택이 물에 잠기고 농작물이 쓰러지거나 나무가 부러질 수 있다. 나는 외출을 삼가고 집에 머물며, 베란다나 마당에 바람에 날아가기 쉬운 물건을 미리 안으로 들여놓겠다.","scoring_points":["태풍의 피해를 썼는가","알맞은 행동 요령을 두 가지 썼는가","내가 실천할 일로 썼는가"]},"explanation":["비와 바람의 피해예요.","외출을 삼가요.","날아갈 물건을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#1','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',1,'mc','auto','지구의 기온이 높아지는 현상을 무엇이라고 하나요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X09','SO5-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"지구의 기온이 높아지는 현상을 무엇이라고 하나요?","options":[{"t":"지구 온난화","correct":true},{"t":"지구 한랭화","mis":"SO5-1-u2-X12"},{"t":"황사","mis":"SO5-1-u2-X09"},{"t":"인구 이동","mis":"SO5-1-u2-X16"}],"explanation":["기온이 높아져요.","따뜻할 온, 될 화예요.","지구 온난화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#2','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',1,'mc','auto','지구 온난화를 심하게 만드는 인간 활동은 어느 것인가요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"지구 온난화를 심하게 만드는 인간 활동은 어느 것인가요?","options":[{"t":"숲을 파괴하고 석유와 석탄을 지나치게 쓰는 일","correct":true},{"t":"나무를 심고 숲을 가꾸는 일","mis":"SO5-1-u2-X12"},{"t":"대중교통을 이용하는 일","mis":"SO5-1-u2-X12"},{"t":"빈 교실의 전등을 끄는 일","mis":"SO5-1-u2-X12"}],"explanation":["기온을 높이는 일을 찾아요.","숲이 줄고 연료를 많이 써요.","나머지는 막는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#3','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',1,'sa','auto','기후변화를 막으려는 모든 노력을 무엇이라고 하나요? (기후 □□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C8","difficulty":1,"kind":"sa","stem":"기후변화를 막으려는 모든 노력을 무엇이라고 하나요? (기후 □□)","answer":["행동"],"explanation":["막으려는 노력이에요.","누구나 할 수 있어요.","기후 행동이에요."],"mis":"SO5-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#4','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',1,'ox','auto','우리나라의 연평균 기온은 오랜 기간에 걸쳐 꾸준히 내려가고 있어요.',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"ox","stem":"우리나라의 연평균 기온은 오랜 기간에 걸쳐 꾸준히 내려가고 있어요.","answer":"X","reason_options":[{"t":"지구 온난화로 연평균 기온이 꾸준히 올라가고 있기 때문에","correct":true},{"t":"기후변화가 일어나면 기온은 언제나 내려가기 때문에","mis":"SO5-1-u2-X12"}],"mis":"SO5-1-u2-X12","explanation":["기온이 올라가고 있어요.","약 백 년 동안 높아졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#5','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'mc','auto','우리나라 기후의 변화 자료에서 계절 길이는 어떻게 달라졌나요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"mc","stem":"우리나라 기후의 변화 자료에서 계절 길이는 어떻게 달라졌나요?","options":[{"t":"여름이 길어지고 겨울이 짧아졌다","correct":true},{"t":"여름이 짧아지고 겨울이 길어졌다","mis":"SO5-1-u2-X12"},{"t":"봄과 가을만 크게 길어졌다","mis":"SO5-1-u2-X12"},{"t":"네 계절의 길이가 그대로이다","mis":"SO5-1-u2-X12"}],"explanation":["여름은 98일에서 118일이에요.","겨울은 109일에서 87일이에요.","여름이 늘고 겨울이 줄었어요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#6','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'mc','auto','우리나라 기후의 변화 자료에서 연평균 기온은 어떻게 달라졌나요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"mc","stem":"우리나라 기후의 변화 자료에서 연평균 기온은 어떻게 달라졌나요?","options":[{"t":"12.0 ℃에서 13.9 ℃로 올라갔다","correct":true},{"t":"13.9 ℃에서 12.0 ℃로 내려갔다","mis":"SO5-1-u2-X12"},{"t":"거의 달라지지 않았다","mis":"SO5-1-u2-X12"},{"t":"여름에만 올라갔다","mis":"SO5-1-u2-X12"}],"explanation":["두 수를 견주어요.","13.9가 더 커요.","기온이 올라갔어요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#7','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',2,'mc','auto','「친환경 재료로 제품을 만들고 생산 과정의 오염 물질을 줄인다」는 누구의 기후 행동인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"「친환경 재료로 제품을 만들고 생산 과정의 오염 물질을 줄인다」는 누구의 기후 행동인가요?","options":[{"t":"기업","correct":true},{"t":"세계 여러 나라","mis":"SO5-1-u2-X14"},{"t":"정부와 국회","mis":"SO5-1-u2-X14"},{"t":"학교 학생","mis":"SO5-1-u2-X14"}],"explanation":["제품을 만드는 곳이에요.","생산하는 주체예요.","기업의 기후 행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#8','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',2,'mc','auto','학교에서 할 수 있는 기후 행동으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"학교에서 할 수 있는 기후 행동으로 알맞은 것은 어느 것인가요?","options":[{"t":"급식을 남기지 않고 빈 교실과 화장실의 전등을 끈다","correct":true},{"t":"빈 교실의 냉방기를 켜 둔다","mis":"SO5-1-u2-X14"},{"t":"가까운 거리도 자가용을 타고 온다","mis":"SO5-1-u2-X14"},{"t":"일회용 컵을 하루에 여러 개 쓴다","mis":"SO5-1-u2-X14"}],"explanation":["음식과 에너지를 아껴요.","전등을 꺼요.","학교에서도 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#9','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'ox','auto','기후변화의 영향으로 자연재해를 예측하기 어려워지고 그 강도도 세지고 있어요.',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"ox","stem":"기후변화의 영향으로 자연재해를 예측하기 어려워지고 그 강도도 세지고 있어요.","answer":"O","reason_options":[{"t":"기후변화로 자연재해의 발생 횟수와 강도가 모두 늘고 있기 때문에","correct":true},{"t":"자연재해는 기후변화와 아무 관계가 없기 때문에","mis":"SO5-1-u2-X13"}],"mis":"SO5-1-u2-X13","explanation":["재해가 더 잦아요.","더 세졌어요.","예측도 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#10','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',3,'mc','auto','기후 행동을 실천하고 돌아봤더니 잘 안 된 날이 있었어요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"기후 행동을 실천하고 돌아봤더니 잘 안 된 날이 있었어요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"어려웠던 까닭을 생각해 보고 다음에도 이어서 실천한다","correct":true},{"t":"잘 안 된 행동은 목록에서 모두 지운다","mis":"SO5-1-u2-X15"},{"t":"나 하나 해도 달라지지 않으니 그만둔다","mis":"SO5-1-u2-X14"},{"t":"어른이 될 때까지 기후 행동을 미룬다","mis":"SO5-1-u2-X14"}],"explanation":["실천이 어려운 날도 있어요.","까닭을 돌아봐요.","다시 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#1','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',2,'match','auto','기후 행동 카드를 보고 카드와 기후 행동을 하는 주체를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"match","stem":"기후 행동 카드를 보고 카드와 기후 행동을 하는 주체를 알맞게 이으세요.","pairs":[{"l":"㉮","r":"세계 여러 나라"},{"l":"㉯","r":"정부와 국회"},{"l":"㉰","r":"기업"},{"l":"㉱","r":"개인"}],"mis":"SO5-1-u2-X14","explanation":["㉮는 나라들의 약속이에요.","㉯는 법과 제도, ㉰는 제품이에요.","㉱는 내가 매일 할 수 있어요."],"asset":{"type":"passage","lines":["㉮ 기온이 크게 오르지 않도록 함께 약속을 맺었다.","㉯ 기후변화를 막는 법과 제도를 만들었다.","㉰ 친환경 재료로 제품을 만들고 오염 물질을 줄였다.","㉱ 가까운 길은 걷고 휴지 대신 손수건을 쓴다."],"title":"기후 행동 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#2','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',2,'sa','auto','2015년 세계 여러 나라가 기온 상승을 막기로 약속하며 채택한 협정의 이름을 쓰세요. (□□ 협정)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"sa","stem":"2015년 세계 여러 나라가 기온 상승을 막기로 약속하며 채택한 협정의 이름을 쓰세요. (□□ 협정)","answer":["파리"],"explanation":["여러 나라가 함께 맺었어요.","기온 상승을 막기로 했어요.","파리 협정이에요."],"mis":"SO5-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#3','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'mc','auto','어느 해에 역대 가장 긴 가뭄과 가장 많은 장맛비, 이상 고온과 한파가 한 해에 모두 나타났어요. 가장 알맞은 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"어느 해에 역대 가장 긴 가뭄과 가장 많은 장맛비, 이상 고온과 한파가 한 해에 모두 나타났어요. 가장 알맞은 까닭은 어느 것인가요?","options":[{"t":"기후변화로 자연재해가 더 잦아지고 세졌기 때문에","correct":true},{"t":"그해에만 우연히 생긴 일이기 때문에","mis":"SO5-1-u2-X13"},{"t":"우리나라에 계절이 넷이기 때문에","mis":"SO5-1-u2-X13"},{"t":"자연재해는 원래 미리 다 알 수 있기 때문에","mis":"SO5-1-u2-X13"}],"explanation":["「역대」라는 말이 잦아요.","재해가 더 자주, 더 세게 와요.","기후변화의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#4','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'mc','auto','기후변화가 일어나는 과정을 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"기후변화가 일어나는 과정을 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"인간 활동 → 지구 온난화 → 기후변화","correct":true},{"t":"기후변화 → 인간 활동 → 지구 온난화","mis":"SO5-1-u2-X12"},{"t":"지구 온난화 → 인간 활동 → 기후변화","mis":"SO5-1-u2-X12"},{"t":"기후 행동 → 지구 온난화 → 인간 활동","mis":"SO5-1-u2-X14"}],"explanation":["사람의 활동이 먼저예요.","그래서 지구가 더워져요.","그 결과 기후가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#5','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',3,'mc','auto','「나의 기후 행동 수첩」에 적기 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"「나의 기후 행동 수첩」에 적기 가장 알맞은 것은 어느 것인가요?","options":[{"t":"휴지 대신 손수건 쓰기","correct":true},{"t":"기후변화를 막는 법 만들기","mis":"SO5-1-u2-X15"},{"t":"생산 과정의 오염 물질 줄이는 기술 개발하기","mis":"SO5-1-u2-X15"},{"t":"에어컨을 세게 틀어 시원하게 지내기","mis":"SO5-1-u2-X14"}],"explanation":["수첩에는 내가 매일 할 일을 적어요.","법은 국회, 기술은 기업의 일이에요.","손수건은 내가 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#6','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',3,'ox','auto','기후 행동 수첩은 행동을 고르고 적는 데서 끝내고, 실천한 결과는 돌아보지 않아도 돼요.',ARRAY['SO5-1-u2-X15']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"ox","stem":"기후 행동 수첩은 행동을 고르고 적는 데서 끝내고, 실천한 결과는 돌아보지 않아도 돼요.","answer":"X","reason_options":[{"t":"실천한 뒤 돌아보는 일까지 이어져야 생활 속에서 계속할 수 있기 때문에","correct":true},{"t":"기후 행동은 적어 두기만 하면 저절로 이루어지기 때문에","mis":"SO5-1-u2-X15"}],"mis":"SO5-1-u2-X15","explanation":["고르고 실천하고 돌아봐요.","돌아보기까지가 기후 행동이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#7','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'error','auto','기후변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X13']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"error","stem":"기후변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「기후변화로 우리나라는 겨울이 길어지고 여름이 짧아지고 있어.」","correct":true,"mis_target":"SO5-1-u2-X12"},{"t":"수안 — 「연평균 기온이 꾸준히 올라가고 있어.」","mis":"SO5-1-u2-X12"},{"t":"도경 — 「폭염과 극한 호우가 더 심해지고 있어.」","mis":"SO5-1-u2-X13"}],"explanation":["여름이 길어지고 있어요.","겨울은 짧아지고 있어요.","하준의 말이 거꾸로예요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#8','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',4,'mc','auto','기후 행동을 가장 바르게 이해한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X14','SO5-1-u2-X15']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C8","difficulty":4,"kind":"mc","stem":"기후 행동을 가장 바르게 이해한 것은 어느 것인가요?","options":[{"t":"세계·정부와 국회·기업·개인이 저마다 할 수 있는 일을 하므로 나도 오늘부터 참여할 수 있다","correct":true},{"t":"기후 행동은 나라가 하는 일이라 개인은 할 수 없다","mis":"SO5-1-u2-X14"},{"t":"기후 행동은 기후를 매일 관찰해 기록하는 일이다","mis":"SO5-1-u2-X14"},{"t":"기후 행동은 한 번 하면 끝나는 일이다","mis":"SO5-1-u2-X15"}],"explanation":["여러 주체가 함께해요.","누구나 참여해요.","날마다 실천하고 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#9','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',4,'mc','auto','주제 「우리나라의 기후」에서 배운 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X13','SO5-1-u2-X14']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C7","difficulty":4,"kind":"mc","stem":"주제 「우리나라의 기후」에서 배운 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"우리나라의 기후는 매일 다르게 나타난다","correct":true},{"t":"대체로 남쪽으로 갈수록 기온이 높다","mis":"SO5-1-u2-X05"},{"t":"기후변화로 자연재해가 점점 심해지고 있다","mis":"SO5-1-u2-X13"},{"t":"기후 행동은 누구나 참여할 수 있다","mis":"SO5-1-u2-X14"}],"explanation":["매일 달라지는 것은 날씨예요.","기후는 오랜 기간의 평균이에요.","그래서 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#10','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',4,'essay','teacher','기후변화가 우리나라에 가져온 변화 두 가지를 쓰고, 내가 매일 실천할 기후 행동 두 가지와 실천한 뒤 할 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C8","difficulty":4,"kind":"essay","stem":"기후변화가 우리나라에 가져온 변화 두 가지를 쓰고, 내가 매일 실천할 기후 행동 두 가지와 실천한 뒤 할 일을 쓰세요.","answer_guide":{"answer":"예: 기후변화로 우리나라의 연평균 기온이 꾸준히 올라가고 여름은 길어지고 겨울은 짧아졌다. 또 폭염과 극한 호우 같은 자연재해가 더 자주, 더 세게 나타난다. 나는 가까운 거리는 걸어 다니고 급식을 남기지 않겠다. 실천한 뒤에는 수첩에 결과를 표시하고 잘 안 된 날은 까닭을 생각해 다시 실천하겠다.","scoring_points":["기후변화가 가져온 변화를 두 가지 썼는가","내가 매일 할 수 있는 기후 행동을 두 가지 썼는가","실천한 뒤 돌아보기를 썼는가"]},"explanation":["기온이 오르고 계절이 바뀌어요.","내가 매일 할 일을 골라요.","돌아보고 다시 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#1','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'mc','auto','일정한 지역에 살고 있는 사람의 수를 무엇이라고 하나요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"일정한 지역에 살고 있는 사람의 수를 무엇이라고 하나요?","options":[{"t":"인구","correct":true},{"t":"인구 분포","mis":"SO5-1-u2-X16"},{"t":"인구 밀도","mis":"SO5-1-u2-X16"},{"t":"기후","mis":"SO5-1-u2-X01"}],"explanation":["사람의 수예요.","한 지역에 사는 사람이에요.","인구라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#2','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'mc','auto','인구가 모이거나 흩어져 있는 정도를 무엇이라고 하나요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"인구가 모이거나 흩어져 있는 정도를 무엇이라고 하나요?","options":[{"t":"인구 분포","correct":true},{"t":"인구","mis":"SO5-1-u2-X16"},{"t":"인구 밀도","mis":"SO5-1-u2-X16"},{"t":"인구 이동","mis":"SO5-1-u2-X16"}],"explanation":["모이거나 흩어진 모양이에요.","분포는 퍼져 있는 모양이에요.","인구 분포예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#3','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'sa','auto','일정한 넓이(1 km²) 안에 사는 사람의 수를 무엇이라고 하나요? (인구 □□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"sa","stem":"일정한 넓이(1 km²) 안에 사는 사람의 수를 무엇이라고 하나요? (인구 □□)","answer":["밀도"],"explanation":["빽빽한 정도예요.","1 km² 안을 봐요.","인구 밀도예요."],"mis":"SO5-1-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#4','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'ox','auto','기후와 지형은 인구 분포에 영향을 주는 자연환경이에요.',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"ox","stem":"기후와 지형은 인구 분포에 영향을 주는 자연환경이에요.","answer":"O","reason_options":[{"t":"기후와 지형은 사람이 만든 것이 아니라 자연이 만든 환경이기 때문에","correct":true},{"t":"기후와 지형은 사람이 만든 인문환경이기 때문에","mis":"SO5-1-u2-X17"}],"mis":"SO5-1-u2-X17","explanation":["날씨와 땅의 생김새예요.","자연이 만들었어요.","자연환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#5','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','인구 분포에 영향을 주는 인문환경끼리 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"인구 분포에 영향을 주는 인문환경끼리 묶인 것은 어느 것인가요?","options":[{"t":"일자리·교통·교육","correct":true},{"t":"기후·지형·하천","mis":"SO5-1-u2-X17"},{"t":"기후·일자리·지형","mis":"SO5-1-u2-X17"},{"t":"지형·교통·기후","mis":"SO5-1-u2-X17"}],"explanation":["사람이 만든 환경이에요.","일할 곳, 다닐 길, 배울 곳이에요.","일자리·교통·교육이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#6','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','「이 지역에 있는 회사에 취직해서 이사 왔어요」라는 말에서 사는 곳을 정하는 데 영향을 준 환경은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"「이 지역에 있는 회사에 취직해서 이사 왔어요」라는 말에서 사는 곳을 정하는 데 영향을 준 환경은 어느 것인가요?","options":[{"t":"일자리","correct":true},{"t":"기후","mis":"SO5-1-u2-X17"},{"t":"지형","mis":"SO5-1-u2-X17"},{"t":"교육","mis":"SO5-1-u2-X17"}],"explanation":["회사에 취직했어요.","일할 곳 때문에 왔어요.","일자리예요."],"asset":{"type":"speech","turns":[{"who":"회사원","text":"이 지역 회사에 취직해서 이사 왔어요."},{"who":"부모님","text":"아이 공부를 생각해서 이 동네에 살아요."},{"who":"할아버지","text":"날씨가 따뜻하고 좋아서 이곳에 살아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#7','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','인구 밀도를 살펴보면 무엇을 알 수 있나요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"인구 밀도를 살펴보면 무엇을 알 수 있나요?","options":[{"t":"인구가 모여 있는 정도","correct":true},{"t":"그 지역까지 가는 길","mis":"SO5-1-u2-X16"},{"t":"그 지역 사람들의 나이","mis":"SO5-1-u2-X16"},{"t":"그 지역의 산 높이","mis":"SO5-1-u2-X16"}],"explanation":["1 km² 안의 사람 수예요.","빽빽한 정도를 알려 줘요.","모여 있는 정도를 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#8','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','두 지역 자료를 알맞게 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"두 지역 자료를 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"서울특별시는 강원특별자치도보다 면적이 좁지만 사람이 많아 인구 밀도가 높다","correct":true},{"t":"서울특별시는 면적이 넓어서 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"강원특별자치도는 면적이 넓어서 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"두 지역의 인구 밀도는 거의 같다","mis":"SO5-1-u2-X18"}],"explanation":["서울은 넓이가 좁아요.","그런데 사람이 많아요.","그래서 밀도가 높아요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#9','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'ox','auto','대체로 도시가 발달한 지역에서 인구 밀도가 높게 나타나요.',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"ox","stem":"대체로 도시가 발달한 지역에서 인구 밀도가 높게 나타나요.","answer":"O","reason_options":[{"t":"일자리·교통·교육 같은 인문환경이 잘 갖춰져 사람이 모이기 때문에","correct":true},{"t":"도시는 땅이 넓어 사람들이 흩어져 살기 때문에","mis":"SO5-1-u2-X18"}],"mis":"SO5-1-u2-X18","explanation":["도시에는 일할 곳이 많아요.","교통과 학교도 많아요.","그래서 사람이 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#10','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',3,'mc','auto','어느 곳에 사람이 더 모여 사는지 알아볼 때 사는 사람의 수만 세면 부족한 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X03']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"어느 곳에 사람이 더 모여 사는지 알아볼 때 사는 사람의 수만 세면 부족한 까닭은 어느 것인가요?","options":[{"t":"땅의 넓이에 따라 모여 사는 정도가 달라지기 때문에","correct":true},{"t":"사람 수는 해마다 달라지기 때문에","mis":"SO5-1-u2-X18"},{"t":"사람마다 집 크기가 다르기 때문에","mis":"SO5-1-u2-X18"},{"t":"지역마다 계절이 다르기 때문에","mis":"SO5-1-u2-X03"}],"explanation":["사람 수가 같아도 땅이 넓으면 흩어져요.","좁으면 모여요.","넓이도 함께 봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#1','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',2,'match','auto','세 사람의 말을 보고 말한 사람과 사는 곳을 정하는 데 영향을 준 환경을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"match","stem":"세 사람의 말을 보고 말한 사람과 사는 곳을 정하는 데 영향을 준 환경을 알맞게 이으세요.","pairs":[{"l":"회사원","r":"일자리"},{"l":"부모님","r":"교육"},{"l":"할아버지","r":"기후"}],"mis":"SO5-1-u2-X17","explanation":["취직은 일자리예요.","아이 공부는 교육이에요.","날씨가 좋은 것은 기후예요."],"asset":{"type":"speech","turns":[{"who":"회사원","text":"이 지역 회사에 취직해서 이사 왔어요."},{"who":"부모님","text":"아이 공부를 생각해서 이 동네에 살아요."},{"who":"할아버지","text":"날씨가 따뜻하고 좋아서 이곳에 살아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#2','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',2,'sa','auto','일자리·교통·교육처럼 사람이 만든 환경을 무엇이라고 하나요? (□□환경)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"sa","stem":"일자리·교통·교육처럼 사람이 만든 환경을 무엇이라고 하나요? (□□환경)","answer":["인문"],"explanation":["자연이 만든 것이 아니에요.","사람이 만들었어요.","인문환경이에요."],"mis":"SO5-1-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#3','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'mc','auto','두 마을에 똑같이 여덟 명이 사는데, 한 마을은 한쪽에 몰려 살고 다른 마을은 골고루 퍼져 살아요. 이것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X18']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"두 마을에 똑같이 여덟 명이 사는데, 한 마을은 한쪽에 몰려 살고 다른 마을은 골고루 퍼져 살아요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"인구가 같아도 인구 분포는 다를 수 있다","correct":true},{"t":"인구가 같으면 인구 분포도 언제나 같다","mis":"SO5-1-u2-X16"},{"t":"인구 분포는 사람 수만 뜻한다","mis":"SO5-1-u2-X16"},{"t":"두 마을의 인구 밀도는 볼 필요가 없다","mis":"SO5-1-u2-X18"}],"explanation":["사람 수는 같아요.","모인 모양은 달라요.","인구 분포가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#4','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'mc','auto','두 지역 자료에서 인구 밀도를 견주려면 꼭 함께 보아야 하는 두 가지는 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"두 지역 자료에서 인구 밀도를 견주려면 꼭 함께 보아야 하는 두 가지는 어느 것인가요?","options":[{"t":"땅 넓이와 사는 사람의 수","correct":true},{"t":"사는 사람의 수와 사람들의 나이","mis":"SO5-1-u2-X18"},{"t":"땅 넓이와 산의 높이","mis":"SO5-1-u2-X18"},{"t":"기온과 강수량","mis":"SO5-1-u2-X02"}],"explanation":["인구 밀도는 1 km² 안의 사람 수예요.","사람 수를 넓이로 나눠요.","두 가지가 꼭 필요해요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#5','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'mc','auto','「산지보다 평평한 땅에 사람이 많이 산다」는 것은 어떤 환경이 인구 분포에 준 영향인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"「산지보다 평평한 땅에 사람이 많이 산다」는 것은 어떤 환경이 인구 분포에 준 영향인가요?","options":[{"t":"지형 — 자연환경","correct":true},{"t":"지형 — 인문환경","mis":"SO5-1-u2-X17"},{"t":"교통 — 자연환경","mis":"SO5-1-u2-X17"},{"t":"교육 — 인문환경","mis":"SO5-1-u2-X17"}],"explanation":["땅의 생김새는 지형이에요.","지형은 자연이 만들었어요.","자연환경의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#6','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'ox','auto','인구 분포에 영향을 주는 환경의 정도는 시간이 흘러 사람들이 하는 일이 바뀌어도 늘 똑같아요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"ox","stem":"인구 분포에 영향을 주는 환경의 정도는 시간이 흘러 사람들이 하는 일이 바뀌어도 늘 똑같아요.","answer":"X","reason_options":[{"t":"사람들의 생각이나 하는 일이 바뀌면 영향을 주는 정도도 달라지기 때문에","correct":true},{"t":"한 번 정해진 인구 분포는 절대 바뀌지 않기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["영향의 정도는 저마다 달라요.","시간이 흐르면 바뀌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#7','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'error','auto','인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"error","stem":"인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「강원특별자치도는 땅이 넓으니까 인구 밀도도 높을 거야.」","correct":true,"mis_target":"SO5-1-u2-X18"},{"t":"시우 — 「인구 밀도를 보려면 사람 수와 넓이를 함께 봐야 해.」","mis":"SO5-1-u2-X18"},{"t":"다인 — 「인구가 모이거나 흩어진 정도가 인구 분포야.」","mis":"SO5-1-u2-X16"}],"explanation":["넓은 땅에 사람이 적으면 밀도가 낮아요.","강원은 약 91명/km²예요.","라온의 말이 틀렸어요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#8','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',4,'mc','auto','「인구 분포」 마인드맵을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X02']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"mc","stem":"「인구 분포」 마인드맵을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"뜻 — 인구가 모이거나 흩어진 정도 / 영향 — 자연환경·인문환경 / 알아보는 방법 — 인구 밀도","correct":true},{"t":"뜻 — 한 지역의 사람 수 / 영향 — 인문환경만 / 알아보는 방법 — 땅 넓이","mis":"SO5-1-u2-X16"},{"t":"뜻 — 1 km² 안의 사람 수 / 영향 — 자연환경만 / 알아보는 방법 — 인구수","mis":"SO5-1-u2-X16"},{"t":"뜻 — 대기의 상태 / 영향 — 지형 / 알아보는 방법 — 등온선","mis":"SO5-1-u2-X02"}],"explanation":["뜻은 모인 정도예요.","두 환경의 영향을 받아요.","인구 밀도로 알아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#9','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',4,'mc','auto','사람이 너무 많이 모여 활력이 넘치지만 살 집이 부족해진 ◇◇시를 설명한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X17','SO5-1-u2-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"mc","stem":"사람이 너무 많이 모여 활력이 넘치지만 살 집이 부족해진 ◇◇시를 설명한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일자리·교육 같은 인문환경이 좋아 사람이 모여 인구 밀도가 높아진 곳이다","correct":true},{"t":"땅이 넓어 사람이 흩어져 사는 곳이다","mis":"SO5-1-u2-X18"},{"t":"기후가 나빠 사람이 떠나는 곳이다","mis":"SO5-1-u2-X17"},{"t":"인구는 많지만 인구 분포와는 관계없는 곳이다","mis":"SO5-1-u2-X16"}],"explanation":["일자리·대학교가 있어 모였어요.","인문환경의 영향이에요.","좁은 곳에 사람이 많아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#10','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',4,'essay','teacher','두 지역 자료를 보고 어느 지역의 인구 밀도가 더 높은지 쓰고, 그 까닭을 넓이와 인구를 함께 들어 쓰세요. 또 인구 밀도가 높은 곳에 사람이 모이는 까닭을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"essay","stem":"두 지역 자료를 보고 어느 지역의 인구 밀도가 더 높은지 쓰고, 그 까닭을 넓이와 인구를 함께 들어 쓰세요. 또 인구 밀도가 높은 곳에 사람이 모이는 까닭을 한 가지 쓰세요.","answer_guide":{"answer":"예: 서울특별시의 인구 밀도가 더 높다. 서울특별시는 강원특별자치도보다 넓이가 훨씬 좁지만 사는 사람은 훨씬 많기 때문이다. 서울특별시처럼 도시가 발달한 곳에는 일자리와 교통, 교육 같은 인문환경이 잘 갖춰져 사람이 모인다.","scoring_points":["인구 밀도가 높은 지역을 바르게 골랐는가","넓이와 인구를 함께 들어 까닭을 썼는가","사람이 모이는 까닭을 썼는가"]},"explanation":["서울이 더 높아요.","좁은 땅에 사람이 많아요.","인문환경이 사람을 모아요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#1','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',1,'mc','auto','1960년 무렵까지 우리나라 사람들은 주로 어디에 모여 살았나요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"1960년 무렵까지 우리나라 사람들은 주로 어디에 모여 살았나요?","options":[{"t":"국토의 남서쪽 평야 지대","correct":true},{"t":"국토의 북동쪽 산지","mis":"SO5-1-u2-X19"},{"t":"바다 위의 작은 섬","mis":"SO5-1-u2-X19"},{"t":"연평균 기온이 낮은 곳","mis":"SO5-1-u2-X19"}],"explanation":["벼농사를 짓던 때예요.","평야가 농사짓기 좋아요.","남서쪽 평야에 모였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#2','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',1,'mc','auto','우리나라의 수도권에 속하는 곳끼리 바르게 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"우리나라의 수도권에 속하는 곳끼리 바르게 묶인 것은 어느 것인가요?","options":[{"t":"서울특별시·인천광역시·경기도","correct":true},{"t":"서울특별시·부산광역시·제주특별자치도","mis":"SO5-1-u2-X20"},{"t":"인천광역시·대구광역시·강원특별자치도","mis":"SO5-1-u2-X20"},{"t":"경기도·전라남도·경상북도","mis":"SO5-1-u2-X20"}],"explanation":["수도를 가운데 두고 이어져요.","서울과 맞닿은 곳이에요.","서울·인천·경기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#3','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C11',1,'sa','auto','인구를 나이·성별 등의 기준으로 나누어 본 짜임새를 무엇이라고 하나요? (인구 □□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C11","difficulty":1,"kind":"sa","stem":"인구를 나이·성별 등의 기준으로 나누어 본 짜임새를 무엇이라고 하나요? (인구 □□)","answer":["구조"],"explanation":["짜임새를 뜻해요.","나이별로 나누어 봐요.","인구 구조예요."],"mis":"SO5-1-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#4','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',1,'ox','auto','오늘날 우리나라 인구의 절반 정도가 수도권에 모여 살아요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"ox","stem":"오늘날 우리나라 인구의 절반 정도가 수도권에 모여 살아요.","answer":"O","reason_options":[{"t":"산업화로 일자리와 교통이 갖춰진 수도권에 인구가 집중했기 때문에","correct":true},{"t":"수도권은 평야가 넓어 농사짓기가 가장 좋기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["수도권으로 사람이 모였어요.","일자리가 많아서예요.","절반 정도가 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#5','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'mc','auto','두 시기 인구분포도 읽기 메모에서 1960년에 인구가 몰린 곳은 어떤 곳인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 시기 인구분포도 읽기 메모에서 1960년에 인구가 몰린 곳은 어떤 곳인가요?","options":[{"t":"평야가 발달하고 기후가 온화한 서쪽과 남쪽 바닷가 가까이","correct":true},{"t":"산지가 많고 기온이 낮은 동쪽과 북쪽","mis":"SO5-1-u2-X19"},{"t":"바다에서 멀리 떨어진 안쪽 땅","mis":"SO5-1-u2-X19"},{"t":"서울 둘레의 대도시","mis":"SO5-1-u2-X19"}],"explanation":["진한 칸은 서쪽과 남쪽이에요.","평야가 넓고 따뜻해요.","농사짓기 좋은 곳이에요."],"asset":{"type":"passage","lines":["1960년 — 진한 색 칸이 서쪽과 남쪽 바닷가 가까이에 몰려 있다.","1960년 — 산지가 많은 동쪽과 북쪽 칸은 색이 옅다.","2023년 — 서울 둘레의 칸이 가장 진하다.","2023년 — 몇몇 대도시 칸도 진하고 촌락 칸은 옅어졌다."],"title":"두 시기 인구분포도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#6','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'mc','auto','두 시기 인구분포도 읽기 메모에서 2023년에 가장 진한 칸은 어디인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 시기 인구분포도 읽기 메모에서 2023년에 가장 진한 칸은 어디인가요?","options":[{"t":"서울 둘레의 수도권","correct":true},{"t":"농사짓기 좋은 촌락","mis":"SO5-1-u2-X19"},{"t":"산과 숲이 많은 곳","mis":"SO5-1-u2-X19"},{"t":"남서쪽 평야 지대","mis":"SO5-1-u2-X19"}],"explanation":["서울 둘레 칸이 가장 진해요.","대도시도 진해요.","촌락은 옅어졌어요."],"asset":{"type":"passage","lines":["1960년 — 진한 색 칸이 서쪽과 남쪽 바닷가 가까이에 몰려 있다.","1960년 — 산지가 많은 동쪽과 북쪽 칸은 색이 옅다.","2023년 — 서울 둘레의 칸이 가장 진하다.","2023년 — 몇몇 대도시 칸도 진하고 촌락 칸은 옅어졌다."],"title":"두 시기 인구분포도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#7','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'mc','auto','오늘날 우리나라의 인구 분포에 더 큰 영향을 주는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"mc","stem":"오늘날 우리나라의 인구 분포에 더 큰 영향을 주는 것은 어느 것인가요?","options":[{"t":"일자리·교통 같은 인문환경","correct":true},{"t":"기후·지형 같은 자연환경","mis":"SO5-1-u2-X19"},{"t":"환경의 영향이 모두 사라졌다","mis":"SO5-1-u2-X19"},{"t":"평야의 넓이","mis":"SO5-1-u2-X19"}],"explanation":["공업과 서비스업에서 많이 일해요.","사람이 만든 환경이 중요해요.","인문환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#8','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C11',2,'mc','auto','수도권과 비수도권 인구 자료에서 수도권인 경기도가 비수도권인 경상북도보다 비율이 더 높은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"mc","stem":"수도권과 비수도권 인구 자료에서 수도권인 경기도가 비수도권인 경상북도보다 비율이 더 높은 것은 어느 것인가요?","options":[{"t":"청장년층","correct":true},{"t":"노년층","mis":"SO5-1-u2-X20"},{"t":"유소년층과 노년층 모두","mis":"SO5-1-u2-X20"},{"t":"비율이 모두 같다","mis":"SO5-1-u2-X20"}],"explanation":["경기도 청장년층은 약 73%예요.","경상북도는 약 66%예요.","수도권이 더 높아요."],"asset":{"type":"passage","lines":["경기도(수도권) — 청장년층 약 73% · 노년층이 비교적 적다.","경상북도(비수도권) — 청장년층 약 66% · 노년층이 비교적 많다.","수도권으로 옮겨 온 까닭 — 직업이 가장 많다.","우리나라 인구의 절반 정도가 수도권에 산다."],"title":"수도권과 비수도권 인구 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#9','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'ox','auto','산업화로 도시가 발달하면서 많은 사람이 도시에서 촌락으로 옮겨 갔어요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"ox","stem":"산업화로 도시가 발달하면서 많은 사람이 도시에서 촌락으로 옮겨 갔어요.","answer":"X","reason_options":[{"t":"많은 사람이 일자리를 찾아 촌락에서 도시로 옮겨 갔기 때문에","correct":true},{"t":"도시에는 일자리가 없어 사람들이 떠났기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["방향이 반대예요.","촌락에서 도시로 갔어요.","그래서 도시 인구가 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#10','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',3,'mc','auto','과거 우리나라 사람들이 남서쪽 평야 지대에 모여 산 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"과거 우리나라 사람들이 남서쪽 평야 지대에 모여 산 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"벼농사 중심의 농업 사회라 기후가 온화하고 평야가 발달한 곳이 살기 좋았기 때문에","correct":true},{"t":"그곳에 공장과 회사가 가장 많았기 때문에","mis":"SO5-1-u2-X19"},{"t":"그곳에 높은 산이 많았기 때문에","mis":"SO5-1-u2-X19"},{"t":"그곳에 큰 대학교가 몰려 있었기 때문에","mis":"SO5-1-u2-X19"}],"explanation":["그때는 농사를 많이 지었어요.","평야와 따뜻한 기후가 중요했어요.","자연환경의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#1','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C11',2,'match','auto','인구 구조의 세 무리와 나이를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"match","stem":"인구 구조의 세 무리와 나이를 알맞게 이으세요.","pairs":[{"l":"유소년층","r":"14세 이하"},{"l":"청장년층","r":"15~64세"},{"l":"노년층","r":"65세 이상"}],"mis":"SO5-1-u2-X20","explanation":["어린이는 유소년층이에요.","일하는 나이는 청장년층이에요.","65세부터 노년층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#2','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',2,'sa','auto','수도를 중심으로 이루어진 대도시권을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"sa","stem":"수도를 중심으로 이루어진 대도시권을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["수도권"],"explanation":["수도를 가운데 둬요.","서울·인천·경기예요.","수도권이에요."],"mis":"SO5-1-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#3','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'mc','auto','수도권으로 옮겨 온 까닭 가운데 「직업」이 가장 많았다는 자료로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"수도권으로 옮겨 온 까닭 가운데 「직업」이 가장 많았다는 자료로 알 수 있는 것은 어느 것인가요?","options":[{"t":"수도권에 일자리가 많아 사람을 끌어모은다","correct":true},{"t":"수도권에는 평야가 넓게 펼쳐져 있다","mis":"SO5-1-u2-X19"},{"t":"수도권은 기후가 가장 온화하다","mis":"SO5-1-u2-X19"},{"t":"수도권으로 오는 사람은 거의 없다","mis":"SO5-1-u2-X19"}],"explanation":["직업 때문에 옮겨 왔어요.","일할 곳이 많다는 뜻이에요.","일자리는 인문환경이에요."],"asset":{"type":"passage","lines":["경기도(수도권) — 청장년층 약 73% · 노년층이 비교적 적다.","경상북도(비수도권) — 청장년층 약 66% · 노년층이 비교적 많다.","수도권으로 옮겨 온 까닭 — 직업이 가장 많다.","우리나라 인구의 절반 정도가 수도권에 산다."],"title":"수도권과 비수도권 인구 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#4','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C11',3,'mc','auto','비수도권이 수도권보다 노년층 인구 비율이 높게 나타나는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C11","difficulty":3,"kind":"mc","stem":"비수도권이 수도권보다 노년층 인구 비율이 높게 나타나는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일자리와 교육 기회를 찾아 청장년층이 수도권으로 빠져나갔기 때문에","correct":true},{"t":"비수도권에 아기가 가장 많이 태어나기 때문에","mis":"SO5-1-u2-X20"},{"t":"노년층이 모두 수도권을 떠나 왔기 때문에","mis":"SO5-1-u2-X20"},{"t":"비수도권은 기온이 높아 살기 어렵기 때문에","mis":"SO5-1-u2-X20"}],"explanation":["청장년층이 수도권으로 갔어요.","남은 사람 가운데 노년층이 많아요.","그래서 비율이 높아요."],"asset":{"type":"passage","lines":["경기도(수도권) — 청장년층 약 73% · 노년층이 비교적 적다.","경상북도(비수도권) — 청장년층 약 66% · 노년층이 비교적 많다.","수도권으로 옮겨 온 까닭 — 직업이 가장 많다.","우리나라 인구의 절반 정도가 수도권에 산다."],"title":"수도권과 비수도권 인구 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#5','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'mc','auto','두 시기 인구분포도 읽기 메모를 함께 볼 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"두 시기 인구분포도 읽기 메모를 함께 볼 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"인구가 남서쪽 평야에서 수도권과 대도시로 옮겨 모였다","correct":true},{"t":"인구가 수도권에서 남서쪽 평야로 옮겨 갔다","mis":"SO5-1-u2-X19"},{"t":"두 시기의 인구 분포가 똑같다","mis":"SO5-1-u2-X19"},{"t":"두 시기 모두 산지에 가장 많이 산다","mis":"SO5-1-u2-X19"}],"explanation":["1960년엔 서쪽·남쪽 바닷가예요.","2023년엔 서울 둘레와 대도시예요.","모이는 곳이 바뀌었어요."],"asset":{"type":"passage","lines":["1960년 — 진한 색 칸이 서쪽과 남쪽 바닷가 가까이에 몰려 있다.","1960년 — 산지가 많은 동쪽과 북쪽 칸은 색이 옅다.","2023년 — 서울 둘레의 칸이 가장 진하다.","2023년 — 몇몇 대도시 칸도 진하고 촌락 칸은 옅어졌다."],"title":"두 시기 인구분포도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#6','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'ox','auto','인구분포도에서는 색이 진할수록 인구 밀도가 높은 지역이에요.',ARRAY['SO5-1-u2-X06']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"ox","stem":"인구분포도에서는 색이 진할수록 인구 밀도가 높은 지역이에요.","answer":"O","reason_options":[{"t":"인구 밀도를 몇 단계로 나누어 높을수록 진한 색으로 칠하기 때문에","correct":true},{"t":"진한 색은 땅이 높은 산지를 나타내기 때문에","mis":"SO5-1-u2-X06"}],"mis":"SO5-1-u2-X06","explanation":["인구 밀도를 단계로 나눠요.","높을수록 진하게 칠해요.","진한 곳이 많이 모인 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#7','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'error','auto','우리나라 인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X19','SO5-1-u2-X20']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"error","stem":"우리나라 인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「옛날이나 지금이나 인구 분포는 기후와 지형만 보면 다 알 수 있어.」","correct":true,"mis_target":"SO5-1-u2-X19"},{"t":"선호 — 「오늘날에는 인구 100명 중 92명 정도가 도시에 살아.」","mis":"SO5-1-u2-X19"},{"t":"보미 — 「수도권에는 청장년층 비율이 높아.」","mis":"SO5-1-u2-X20"}],"explanation":["옛날엔 자연환경의 영향이 컸어요.","오늘날엔 인문환경의 영향이 커요.","지율의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#8','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',4,'mc','auto','1960년과 오늘날의 인구 분포를 가장 바르게 견준 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"mc","stem":"1960년과 오늘날의 인구 분포를 가장 바르게 견준 것은 어느 것인가요?","options":[{"t":"1960년에는 자연환경의 영향으로 남서쪽 평야에, 오늘날에는 인문환경의 영향으로 수도권과 대도시에 모여 산다","correct":true},{"t":"1960년에는 인문환경의 영향으로 수도권에, 오늘날에는 자연환경의 영향으로 평야에 모여 산다","mis":"SO5-1-u2-X19"},{"t":"두 시기 모두 인구가 전국에 고르게 퍼져 있다","mis":"SO5-1-u2-X19"},{"t":"두 시기 모두 산지가 많은 동쪽에 모여 산다","mis":"SO5-1-u2-X19"}],"explanation":["그때는 농업 사회였어요.","지금은 산업화된 도시 사회예요.","영향을 준 환경이 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#9','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',4,'mc','auto','「우리나라 인구의 절반 정도가 수도권에 산다」는 사실과 「1학년 신입생이 없는 학교가 대부분 비수도권에 있다」는 사실을 이어 보면 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20','SO5-1-u2-X22']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"mc","stem":"「우리나라 인구의 절반 정도가 수도권에 산다」는 사실과 「1학년 신입생이 없는 학교가 대부분 비수도권에 있다」는 사실을 이어 보면 알 수 있는 것은 어느 것인가요?","options":[{"t":"인구가 수도권으로 몰리면서 인구 분포의 불균형이 커지고 있다","correct":true},{"t":"비수도권에 아이들이 가장 많이 산다","mis":"SO5-1-u2-X20"},{"t":"인구가 전국에 고르게 나뉘어 있다","mis":"SO5-1-u2-X22"},{"t":"두 사실은 서로 관계가 없다","mis":"SO5-1-u2-X22"}],"explanation":["사람이 수도권으로 몰려요.","비수도권에는 학생이 줄어요.","불균형이 커지고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#10','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',4,'essay','teacher','과거와 오늘날 우리나라 인구 분포의 특징을 각각 쓰고, 영향을 준 환경이 어떻게 달라졌는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"essay","stem":"과거와 오늘날 우리나라 인구 분포의 특징을 각각 쓰고, 영향을 준 환경이 어떻게 달라졌는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 과거에는 국토의 남서쪽 평야 지대에 많은 사람이 모여 살았다. 벼농사 중심의 농업 사회라 기후가 온화하고 평야가 발달한 곳이 살기 좋았기 때문에 자연환경의 영향을 크게 받았다. 오늘날에는 수도권과 대도시에 인구가 모여 인구의 절반 정도가 수도권에 산다. 산업화로 도시가 발달해 일자리와 교통 같은 인문환경의 영향을 크게 받기 때문이다.","scoring_points":["과거 인구 분포의 특징을 썼는가","오늘날 인구 분포의 특징을 썼는가","자연환경에서 인문환경으로 바뀐 까닭을 썼는가"]},"explanation":["과거 — 남서쪽 평야예요.","오늘 — 수도권과 대도시예요.","농업 사회에서 산업 사회로 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#1','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'mc','auto','인구가 지나치게 몰리는 수도권에서 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"인구가 지나치게 몰리는 수도권에서 나타나는 문제는 어느 것인가요?","options":[{"t":"도로에 차가 많아 교통 체증이 생긴다","correct":true},{"t":"학교에 1학년 신입생이 없다","mis":"SO5-1-u2-X21"},{"t":"일손이 부족해 일할 사람을 구하기 어렵다","mis":"SO5-1-u2-X21"},{"t":"빈집이 늘어난다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 많아서 생기는 문제예요.","차가 많아 길이 막혀요.","나머지는 사람이 줄어드는 곳의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#2','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'mc','auto','인구가 줄어드는 비수도권에서 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"인구가 줄어드는 비수도권에서 나타나는 문제는 어느 것인가요?","options":[{"t":"빈집과 폐교가 늘어난다","correct":true},{"t":"주택 가격이 크게 오른다","mis":"SO5-1-u2-X21"},{"t":"지하철에 승객이 너무 많다","mis":"SO5-1-u2-X21"},{"t":"쓰레기가 너무 많아 처리하기 어렵다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 빠져나갔어요.","집과 학교가 비어요.","나머지는 몰리는 곳의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#3','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'sa','auto','한 나라가 경제·기술·사회·정치 등 여러 분야에서 다른 나라와 경쟁하는 힘을 무엇이라고 하나요? (국가 □□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"sa","stem":"한 나라가 경제·기술·사회·정치 등 여러 분야에서 다른 나라와 경쟁하는 힘을 무엇이라고 하나요? (국가 □□□)","answer":["경쟁력"],"explanation":["나라와 나라 사이의 힘이에요.","경쟁하는 힘이에요.","국가 경쟁력이에요."],"mis":"SO5-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#4','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'ox','auto','인구 분포의 불균형은 국가 경쟁력을 떨어뜨릴 수 있어요.',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"ox","stem":"인구 분포의 불균형은 국가 경쟁력을 떨어뜨릴 수 있어요.","answer":"O","reason_options":[{"t":"지역 격차가 커지면 나라 전체가 힘을 잃을 수 있기 때문에","correct":true},{"t":"불균형은 비수도권 한 곳만의 문제이기 때문에","mis":"SO5-1-u2-X22"}],"mis":"SO5-1-u2-X22","explanation":["격차가 커져요.","나라 전체의 힘이 약해져요.","그래서 균형 발전이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#5','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','되풀이되는 두 고리에서 ㉮ 고리가 계속 돌면 수도권에 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"되풀이되는 두 고리에서 ㉮ 고리가 계속 돌면 수도권에 나타나는 문제는 어느 것인가요?","options":[{"t":"주택이 부족해지고 교통과 환경 문제가 심해진다","correct":true},{"t":"빈집이 늘고 학교가 문을 닫는다","mis":"SO5-1-u2-X21"},{"t":"일손이 부족해진다","mis":"SO5-1-u2-X21"},{"t":"상점과 병원이 줄어든다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 계속 모여요.","좁은 곳에 너무 많아요.","집·교통·환경 문제가 생겨요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#6','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','되풀이되는 두 고리에서 ㉯ 고리가 계속 돌면 비수도권에 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"되풀이되는 두 고리에서 ㉯ 고리가 계속 돌면 비수도권에 나타나는 문제는 어느 것인가요?","options":[{"t":"빈집과 폐교가 늘고 일손이 부족해진다","correct":true},{"t":"집값이 크게 오른다","mis":"SO5-1-u2-X21"},{"t":"교통 체증이 심해진다","mis":"SO5-1-u2-X21"},{"t":"쓰레기를 묻을 자리가 모자란다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 계속 떠나요.","시설이 더 줄어요.","빈집·폐교·일손 부족이에요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#7','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','불균형을 보여 주는 자료에서 1학년 신입생이 없는 초등학교가 많은 곳은 어디인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X25']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"불균형을 보여 주는 자료에서 1학년 신입생이 없는 초등학교가 많은 곳은 어디인가요?","options":[{"t":"비수도권","correct":true},{"t":"수도권","mis":"SO5-1-u2-X21"},{"t":"두 곳이 같다","mis":"SO5-1-u2-X21"},{"t":"자료로 알 수 없다","mis":"SO5-1-u2-X25"}],"explanation":["수도권은 9곳이에요.","비수도권은 148곳이에요.","비수도권이 훨씬 많아요."],"asset":{"type":"passage","lines":["1학년 신입생이 없는 초등학교 — 2022년 121곳 → 2024년 157곳","2024년 157곳 가운데 — 수도권 9곳 · 비수도권 148곳","최근 10년 동안 비수도권 20대 약 60만 명이 수도권으로 옮겨 갔다.","옮겨 간 가장 큰 까닭 — 취업과 학업"],"title":"불균형을 보여 주는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#8','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','비수도권의 20대 청년이 수도권으로 옮겨 간 가장 큰 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"비수도권의 20대 청년이 수도권으로 옮겨 간 가장 큰 까닭은 어느 것인가요?","options":[{"t":"취업과 학업","correct":true},{"t":"기후와 지형","mis":"SO5-1-u2-X17"},{"t":"관광과 휴식","mis":"SO5-1-u2-X17"},{"t":"농사와 고기잡이","mis":"SO5-1-u2-X17"}],"explanation":["일할 곳과 배울 곳이에요.","인문환경과 이어져요.","취업과 학업이에요."],"asset":{"type":"passage","lines":["1학년 신입생이 없는 초등학교 — 2022년 121곳 → 2024년 157곳","2024년 157곳 가운데 — 수도권 9곳 · 비수도권 148곳","최근 10년 동안 비수도권 20대 약 60만 명이 수도권으로 옮겨 갔다.","옮겨 간 가장 큰 까닭 — 취업과 학업"],"title":"불균형을 보여 주는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#9','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'ox','auto','거주지를 옮겨 들어온 인구수에서 나간 인구수를 뺀 값을 순이동이라고 해요.',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"ox","stem":"거주지를 옮겨 들어온 인구수에서 나간 인구수를 뺀 값을 순이동이라고 해요.","answer":"O","reason_options":[{"t":"들어온 사람과 나간 사람을 견주어 남은 값을 보기 때문에","correct":true},{"t":"순이동은 한 해에 새로 태어난 아기의 수이기 때문에","mis":"SO5-1-u2-X16"}],"mis":"SO5-1-u2-X16","explanation":["들어온 수에서 나간 수를 빼요.","빼고 남은 값이에요.","순이동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#10','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',3,'mc','auto','신선 식품을 손쉽게 구할 수 없는 「식품 사막」이 생기는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"신선 식품을 손쉽게 구할 수 없는 「식품 사막」이 생기는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"인구가 줄어 신선 식품이 팔리지 않자 상점이 들여놓지 않기 때문에","correct":true},{"t":"신선 식품을 사려는 사람이 너무 많기 때문에","mis":"SO5-1-u2-X21"},{"t":"신선 식품 값이 크게 내렸기 때문에","mis":"SO5-1-u2-X21"},{"t":"도로가 넓어져 상점이 많아졌기 때문에","mis":"SO5-1-u2-X21"}],"explanation":["사는 사람이 줄었어요.","팔리지 않으면 들여놓지 않아요.","그래서 식품 사막이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#1','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',2,'match','auto','문제와 그 문제가 주로 나타나는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"match","stem":"문제와 그 문제가 주로 나타나는 곳을 알맞게 이으세요.","pairs":[{"l":"주택 가격 상승","r":"인구가 몰리는 수도권"},{"l":"폐교 증가","r":"인구가 줄어드는 비수도권"},{"l":"지하철 혼잡","r":"사람이 붐비는 대도시"},{"l":"식품 사막","r":"상점이 사라진 작은 마을"}],"mis":"SO5-1-u2-X21","explanation":["집값과 지하철은 사람이 몰리는 곳이에요.","폐교와 식품 사막은 사람이 줄어든 곳이에요.","두 곳의 문제가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#2','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',2,'sa','auto','수도권과 비수도권 사이처럼 지역 사이에 생기는 차이를 무엇이라고 하나요? (지역 □□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"sa","stem":"수도권과 비수도권 사이처럼 지역 사이에 생기는 차이를 무엇이라고 하나요? (지역 □□)","answer":["격차"],"explanation":["두 지역의 차이예요.","불균형이 심하면 커져요.","지역 격차예요."],"mis":"SO5-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#3','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'mc','auto','불균형을 보여 주는 자료에서 신입생이 없는 학교가 2022년 121곳에서 2024년 157곳으로 늘어난 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X25','SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"불균형을 보여 주는 자료에서 신입생이 없는 학교가 2022년 121곳에서 2024년 157곳으로 늘어난 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"비수도권을 중심으로 학생 수가 계속 줄고 있다","correct":true},{"t":"전국에 학교가 새로 많이 생기고 있다","mis":"SO5-1-u2-X25"},{"t":"수도권의 학생 수가 가장 크게 줄고 있다","mis":"SO5-1-u2-X21"},{"t":"학생 수 변화는 인구 분포와 관계없다","mis":"SO5-1-u2-X22"}],"explanation":["신입생 없는 학교가 늘었어요.","대부분 비수도권이에요.","학생 수가 줄고 있어요."],"asset":{"type":"passage","lines":["1학년 신입생이 없는 초등학교 — 2022년 121곳 → 2024년 157곳","2024년 157곳 가운데 — 수도권 9곳 · 비수도권 148곳","최근 10년 동안 비수도권 20대 약 60만 명이 수도권으로 옮겨 갔다.","옮겨 간 가장 큰 까닭 — 취업과 학업"],"title":"불균형을 보여 주는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#4','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'mc','auto','상점이나 공장이 사라진 마을에서 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"상점이나 공장이 사라진 마을에서 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물건을 구하기 어렵고 일자리가 줄어 다른 지역으로 떠나는 사람이 늘어난다","correct":true},{"t":"일자리가 늘어 사람들이 더 모여든다","mis":"SO5-1-u2-X21"},{"t":"집값이 크게 올라 집을 구하기 어렵다","mis":"SO5-1-u2-X21"},{"t":"아무 일도 일어나지 않는다","mis":"SO5-1-u2-X22"}],"explanation":["생활이 불편해져요.","일할 곳도 줄어요.","사람들이 또 떠나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#5','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'mc','auto','되풀이되는 두 고리에서 두 고리가 함께 돌 때 우리나라 전체에 생기는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"되풀이되는 두 고리에서 두 고리가 함께 돌 때 우리나라 전체에 생기는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지역 격차가 커져 국가 경쟁력이 떨어질 수 있다","correct":true},{"t":"두 지역의 인구가 저절로 비슷해진다","mis":"SO5-1-u2-X22"},{"t":"비수도권만 어려워지고 수도권은 문제가 없다","mis":"SO5-1-u2-X22"},{"t":"나라 전체의 힘이 저절로 강해진다","mis":"SO5-1-u2-X22"}],"explanation":["두 고리가 서로를 밀어붙여요.","격차가 점점 커져요.","나라 전체가 힘을 잃어요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#6','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'ox','auto','수도권은 사람이 많은 곳이라 주택과 시설이 늘 넉넉해요.',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"ox","stem":"수도권은 사람이 많은 곳이라 주택과 시설이 늘 넉넉해요.","answer":"X","reason_options":[{"t":"사람이 너무 많아 주택이 부족해지고 가격이 오르며 시설도 부족해지기 때문에","correct":true},{"t":"사람이 많을수록 집과 시설은 저절로 남기 때문에","mis":"SO5-1-u2-X21"}],"mis":"SO5-1-u2-X21","explanation":["사람이 너무 많아요.","집이 모자라요.","시설도 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#7','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'error','auto','인구 분포의 불균형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"error","stem":"인구 분포의 불균형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「비수도권에서는 집이 모자라서 집값이 크게 오르고 있어.」","correct":true,"mis_target":"SO5-1-u2-X21"},{"t":"정우 — 「비수도권에서는 청장년층이 빠져나가 일손이 부족해.」","mis":"SO5-1-u2-X21"},{"t":"소율 — 「수도권에서는 쓰레기가 많아 처리하기 어려워.」","mis":"SO5-1-u2-X21"}],"explanation":["집값 상승은 몰리는 곳의 문제예요.","비수도권에는 빈집이 늘어요.","하린의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#8','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',4,'mc','auto','되풀이되는 두 고리를 보고 인구 분포의 불균형을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"mc","stem":"되풀이되는 두 고리를 보고 인구 분포의 불균형을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"한쪽은 모여서 더 모이고 다른 쪽은 떠나서 더 떠나는 일이 되풀이되어, 두 지역 모두 문제가 커진다","correct":true},{"t":"사람이 모이는 곳은 문제가 없고 떠나는 곳에만 문제가 생긴다","mis":"SO5-1-u2-X22"},{"t":"시간이 지나면 두 고리가 저절로 멈춘다","mis":"SO5-1-u2-X22"},{"t":"두 고리는 서로 아무 관계가 없다","mis":"SO5-1-u2-X22"}],"explanation":["㉮는 모여서 더 모여요.","㉯는 떠나서 더 떠나요.","두 곳 모두 문제가 생겨요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#9','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',4,'mc','auto','인구가 줄어든 마을에 「찾아가는 이동형 상점」이 대안으로 떠오른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24','SO5-1-u2-X21']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"mc","stem":"인구가 줄어든 마을에 「찾아가는 이동형 상점」이 대안으로 떠오른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상점이 없어진 곳에 물건이 찾아가 주민이 신선 식품을 구할 수 있게 하기 때문에","correct":true},{"t":"마을 사람들을 도시로 옮겨 살게 하기 때문에","mis":"SO5-1-u2-X24"},{"t":"도시의 큰 상점을 더 넓히기 때문에","mis":"SO5-1-u2-X24"},{"t":"마을에 사람이 더 줄게 만들기 때문에","mis":"SO5-1-u2-X21"}],"explanation":["식품 사막의 문제를 풀어요.","물건이 마을을 찾아가요.","사는 곳에서 돕는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#10','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',4,'essay','teacher','인구가 몰리는 수도권과 인구가 줄어드는 비수도권에서 나타나는 문제를 각각 두 가지씩 쓰고, 이 문제가 나라 전체에 어떤 영향을 줄 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"essay","stem":"인구가 몰리는 수도권과 인구가 줄어드는 비수도권에서 나타나는 문제를 각각 두 가지씩 쓰고, 이 문제가 나라 전체에 어떤 영향을 줄 수 있는지 쓰세요.","answer_guide":{"answer":"예: 수도권에서는 집이 부족해 주택 가격이 오르고, 도로와 지하철이 붐벼 교통 혼잡이 심하다. 비수도권에서는 빈집과 폐교가 늘고, 청장년층이 빠져나가 일손이 부족해진다. 이런 일이 되풀이되면 지역 격차가 커져 나라 전체의 국가 경쟁력이 떨어질 수 있다.","scoring_points":["수도권의 문제를 두 가지 썼는가","비수도권의 문제를 두 가지 썼는가","국가 경쟁력과 이어 썼는가"]},"explanation":["몰리는 곳의 문제예요.","빠져나가는 곳의 문제예요.","나라 전체의 힘이 약해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#1','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'mc','auto','공공 기관을 수도권에서 전국 곳곳으로 옮기는 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"mc","stem":"공공 기관을 수도권에서 전국 곳곳으로 옮기는 까닭은 어느 것인가요?","options":[{"t":"인구 이동과 지역 발전을 이끌기 위해서","correct":true},{"t":"수도권에 사람을 더 모으기 위해서","mis":"SO5-1-u2-X23"},{"t":"수도권 건물을 더 높이 짓기 위해서","mis":"SO5-1-u2-X23"},{"t":"공공 기관의 수를 줄이기 위해서","mis":"SO5-1-u2-X23"}],"explanation":["직원과 가족도 함께 옮겨 가요.","그곳에 일자리가 생겨요.","지역이 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#2','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'mc','auto','고향이나 관심 있는 지역에 기부하면 답례품과 세금 혜택을 주는 제도는 어느 것인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X10']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"mc","stem":"고향이나 관심 있는 지역에 기부하면 답례품과 세금 혜택을 주는 제도는 어느 것인가요?","options":[{"t":"고향 사랑 기부제","correct":true},{"t":"디지털 관광 주민증","mis":"SO5-1-u2-X23"},{"t":"기상 특보","mis":"SO5-1-u2-X10"},{"t":"청년 마을 만들기","mis":"SO5-1-u2-X23"}],"explanation":["기부를 하는 제도예요.","답례품을 받아요.","고향 사랑 기부제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#3','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'sa','auto','공공 기관의 이전을 계기로 지역의 새로운 성장 동력을 만드는 미래형 도시를 무엇이라고 하나요? (□□ 도시)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"sa","stem":"공공 기관의 이전을 계기로 지역의 새로운 성장 동력을 만드는 미래형 도시를 무엇이라고 하나요? (□□ 도시)","answer":["혁신"],"explanation":["공공 기관이 옮겨 와요.","새로 자라날 힘을 만들어요.","혁신 도시예요."],"mis":"SO5-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#4','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'ox','auto','로컬 브랜딩은 지역의 자원과 문화를 살려 그 지역만의 매력을 만드는 일이에요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"ox","stem":"로컬 브랜딩은 지역의 자원과 문화를 살려 그 지역만의 매력을 만드는 일이에요.","answer":"O","reason_options":[{"t":"그 지역에만 있는 것을 살려 사람들을 끌어모으기 때문에","correct":true},{"t":"전국 모든 마을을 똑같은 모습으로 만드는 일이기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["지역만의 것을 살려요.","알릴 거리를 만들어요.","사람들이 찾아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#5','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'match','auto','균형 발전 노력 카드를 보고 카드와 노력의 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"match","stem":"균형 발전 노력 카드를 보고 카드와 노력의 이름을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"공공 기관 이전"},{"l":"㉯","r":"고향 사랑 기부제"},{"l":"㉰","r":"로컬 브랜딩"},{"l":"㉱","r":"청년 마을 만들기"}],"mis":"SO5-1-u2-X23","explanation":["㉮는 기관이 옮겨 가요.","㉯는 기부, ㉰는 지역의 매력이에요.","㉱는 청년이 머물게 도와요."],"asset":{"type":"passage","lines":["㉮ 공공 기관을 수도권에서 여러 지역으로 옮긴다.","㉯ 고향이나 관심 지역에 기부하면 답례품을 준다.","㉰ 지역의 자원과 문화로 지역만의 매력을 만든다.","㉱ 청년이 지역에 머물며 살아 보도록 돕는다.","㉲ 작은 학교에 특별한 교육과정과 시설을 지원한다.","㉳ 살지 않아도 관광객이 주민처럼 혜택을 받게 한다."],"title":"균형 발전 노력 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#6','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'mc','auto','균형 발전 노력 카드 ㉲에 알맞은 노력은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"균형 발전 노력 카드 ㉲에 알맞은 노력은 어느 것인가요?","options":[{"t":"작은 학교 살리기","correct":true},{"t":"디지털 관광 주민증","mis":"SO5-1-u2-X23"},{"t":"공공 기관 이전","mis":"SO5-1-u2-X23"},{"t":"로컬 브랜딩","mis":"SO5-1-u2-X23"}],"explanation":["학교를 지원해요.","특별한 교육과정이 있어요.","작은 학교 살리기예요."],"asset":{"type":"passage","lines":["㉮ 공공 기관을 수도권에서 여러 지역으로 옮긴다.","㉯ 고향이나 관심 지역에 기부하면 답례품을 준다.","㉰ 지역의 자원과 문화로 지역만의 매력을 만든다.","㉱ 청년이 지역에 머물며 살아 보도록 돕는다.","㉲ 작은 학교에 특별한 교육과정과 시설을 지원한다.","㉳ 살지 않아도 관광객이 주민처럼 혜택을 받게 한다."],"title":"균형 발전 노력 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#7','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'mc','auto','청년 마을 만들기 사업이 하려는 일은 어느 것인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X24']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"청년 마을 만들기 사업이 하려는 일은 어느 것인가요?","options":[{"t":"청년의 정착을 도와 지역 청년이 빠져나가는 것을 줄인다","correct":true},{"t":"청년들을 모두 수도권으로 보낸다","mis":"SO5-1-u2-X23"},{"t":"청년만 살 수 있게 다른 사람은 못 들어오게 한다","mis":"SO5-1-u2-X24"},{"t":"청년에게 농사만 짓게 한다","mis":"SO5-1-u2-X24"}],"explanation":["청년이 떠나고 있었어요.","머물러 살아 보게 도와요.","정착을 지원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#8','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C14',2,'mc','auto','내가 생각한 해결 방안을 평가할 때 살펴보지 않아도 되는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"mc","stem":"내가 생각한 해결 방안을 평가할 때 살펴보지 않아도 되는 것은 어느 것인가요?","options":[{"t":"다른 나라에서 먼저 해 본 적이 있는지","correct":true},{"t":"문제의 원인을 해결하는 데 도움이 되는지","mis":"SO5-1-u2-X24"},{"t":"도덕적으로 옳은 방안인지","mis":"SO5-1-u2-X24"},{"t":"비용과 노력을 생각할 때 실현할 수 있는지","mis":"SO5-1-u2-X24"}],"explanation":["잣대는 셋이에요.","원인·옳음·실현이에요.","먼저 한 나라는 조건이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#9','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'ox','auto','인구가 빠져나간 지역에서는 주거·교육 환경을 고치고 창업을 지원하는 등 스스로 노력하기도 해요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"ox","stem":"인구가 빠져나간 지역에서는 주거·교육 환경을 고치고 창업을 지원하는 등 스스로 노력하기도 해요.","answer":"O","reason_options":[{"t":"살기 좋은 지역을 만들어 인구를 끌어들이려 하기 때문에","correct":true},{"t":"지역은 스스로 할 수 있는 일이 하나도 없기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["지역도 노력해요.","새 일자리를 만들어요.","살기 좋은 곳으로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#10','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',3,'mc','auto','어느 바닷가 마을 이야기에서 인구가 다시 늘기 시작한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24','SO5-1-u2-X23','SO5-1-u2-X22']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"mc","stem":"어느 바닷가 마을 이야기에서 인구가 다시 늘기 시작한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주민이 참여한 사업으로 소득이 늘고 지역 경제가 활발해졌기 때문에","correct":true},{"t":"수도권 사람들을 억지로 옮겨 오게 했기 때문에","mis":"SO5-1-u2-X24"},{"t":"마을의 학교를 모두 닫았기 때문에","mis":"SO5-1-u2-X23"},{"t":"그해에 우연히 사람이 몰렸기 때문에","mis":"SO5-1-u2-X22"}],"explanation":["주민이 직접 참여했어요.","소득이 늘었어요.","경제가 살아나 사람이 늘었어요."],"asset":{"type":"passage","lines":["① 마을이 주민도 참여할 수 있는 햇빛 발전 사업을 만들었다.","② 주민들이 사업에 적극 참여했다.","③ 수익을 나누어 받아 주민 소득이 늘었다.","④ 지역 경제가 활발해지고 새로운 일거리가 생겼다.","⑤ 줄어들던 인구가 다시 늘기 시작했다."],"title":"어느 바닷가 마을 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#1','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',2,'match','auto','해결 방안을 평가하는 세 잣대와 그 잣대가 묻는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"match","stem":"해결 방안을 평가하는 세 잣대와 그 잣대가 묻는 것을 알맞게 이으세요.","pairs":[{"l":"원인","r":"문제의 원인을 푸는 데 도움이 되는가"},{"l":"옳음","r":"누구에게 억지로 시키지 않는 옳은 방안인가"},{"l":"실현","r":"비용과 노력을 생각할 때 해낼 수 있는가"}],"mis":"SO5-1-u2-X24","explanation":["먼저 원인과 이어지는지 봐요.","옳은 방안인지 봐요.","해낼 수 있는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#2','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',2,'sa','auto','지역의 자원과 문화에 새로운 생각을 더해 상품과 가치를 만드는 사람을 무엇이라고 하나요? (로컬 □□□□□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"sa","stem":"지역의 자원과 문화에 새로운 생각을 더해 상품과 가치를 만드는 사람을 무엇이라고 하나요? (로컬 □□□□□)","answer":["크리에이터"],"explanation":["지역에 활력을 가져와요.","지역만의 상품을 만들어요.","로컬 크리에이터예요."],"mis":"SO5-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#3','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',3,'mc','auto','모둠 방안 메모에서 세 잣대를 모두 지나는 방안은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"mc","stem":"모둠 방안 메모에서 세 잣대를 모두 지나는 방안은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"SO5-1-u2-X24"},{"t":"㉯","mis":"SO5-1-u2-X24"},{"t":"㉱","mis":"SO5-1-u2-X24"}],"explanation":["㉮는 억지로 시켜 옳지 않아요.","㉯는 비용이 너무 커요.","㉱는 원인과 이어지지 않아요."],"asset":{"type":"passage","lines":["문제 — 비수도권에 일자리가 줄어 청장년층이 떠난다.","방안 ㉮ 수도권 사람들을 억지로 옮겨 살게 한다.","방안 ㉯ 모든 마을에 큰 회사 본사를 하나씩 새로 짓는다.","방안 ㉰ 비수도권에 공장을 세우면 건설 비용을 지원한다.","방안 ㉱ 수도권 회사에 다니는 사람에게 상을 준다."],"title":"모둠 방안 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#4','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',3,'mc','auto','모둠 방안 메모의 방안 ㉮가 걸리는 잣대는 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"mc","stem":"모둠 방안 메모의 방안 ㉮가 걸리는 잣대는 어느 것인가요?","options":[{"t":"도덕적으로 옳은가","correct":true},{"t":"원인 해결에 도움이 되는가","mis":"SO5-1-u2-X24"},{"t":"실현할 수 있는가","mis":"SO5-1-u2-X24"},{"t":"세 잣대를 모두 지난다","mis":"SO5-1-u2-X24"}],"explanation":["사는 곳은 스스로 정해요.","억지로 옮기게 하면 안 돼요.","옳음에서 걸려요."],"asset":{"type":"passage","lines":["문제 — 비수도권에 일자리가 줄어 청장년층이 떠난다.","방안 ㉮ 수도권 사람들을 억지로 옮겨 살게 한다.","방안 ㉯ 모든 마을에 큰 회사 본사를 하나씩 새로 짓는다.","방안 ㉰ 비수도권에 공장을 세우면 건설 비용을 지원한다.","방안 ㉱ 수도권 회사에 다니는 사람에게 상을 준다."],"title":"모둠 방안 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#5','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',3,'mc','auto','어느 바닷가 마을 이야기의 차례에서 가장 먼저 있어야 할 일은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"mc","stem":"어느 바닷가 마을 이야기의 차례에서 가장 먼저 있어야 할 일은 어느 것인가요?","options":[{"t":"주민이 참여할 수 있는 사업을 만드는 일","correct":true},{"t":"인구가 늘어나는 일","mis":"SO5-1-u2-X23"},{"t":"지역 경제가 활발해지는 일","mis":"SO5-1-u2-X23"},{"t":"주민 소득이 늘어나는 일","mis":"SO5-1-u2-X23"}],"explanation":["①이 출발점이에요.","사업이 있어야 참여해요.","그다음 소득이 늘어요."],"asset":{"type":"passage","lines":["① 마을이 주민도 참여할 수 있는 햇빛 발전 사업을 만들었다.","② 주민들이 사업에 적극 참여했다.","③ 수익을 나누어 받아 주민 소득이 늘었다.","④ 지역 경제가 활발해지고 새로운 일거리가 생겼다.","⑤ 줄어들던 인구가 다시 늘기 시작했다."],"title":"어느 바닷가 마을 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#6','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',3,'ox','auto','공공 기관을 비수도권으로 옮기면 직원과 가족도 함께 옮겨 가 그 지역에 일자리와 인구가 늘 수 있어요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"ox","stem":"공공 기관을 비수도권으로 옮기면 직원과 가족도 함께 옮겨 가 그 지역에 일자리와 인구가 늘 수 있어요.","answer":"O","reason_options":[{"t":"기관과 함께 사람이 옮겨 가고 그곳에 일거리가 생기기 때문에","correct":true},{"t":"공공 기관은 사람 없이 건물만 옮기기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["사람도 함께 옮겨요.","일자리가 생겨요.","인구가 고르게 살도록 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#7','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',3,'error','auto','균형 발전 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"error","stem":"균형 발전 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「고향 사랑 기부제는 그 지역에서 태어난 사람만 할 수 있어.」","correct":true,"mis_target":"SO5-1-u2-X23"},{"t":"준서 — 「디지털 관광 주민증은 관광객도 주민처럼 혜택을 받게 해 줘.」","mis":"SO5-1-u2-X23"},{"t":"가온 — 「작은 학교 살리기는 학교가 다닐 만한 곳이 되게 해.」","mis":"SO5-1-u2-X23"}],"explanation":["고향뿐 아니라 관심 지역에도 해요.","태어난 곳이 아니어도 돼요.","태린의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#8','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',4,'mc','auto','「학생이 줄어 문을 닫는 학교가 늘어요」라는 문제에 세 잣대를 모두 지나는 방안으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C14","difficulty":4,"kind":"mc","stem":"「학생이 줄어 문을 닫는 학교가 늘어요」라는 문제에 세 잣대를 모두 지나는 방안으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작은 학교에 특별한 교육과정과 시설 개선을 지원한다","correct":true},{"t":"학생이 적은 학교는 모두 닫고 먼 학교로 다니게 한다","mis":"SO5-1-u2-X24"},{"t":"작은 학교로 전학 오지 않는 집에 벌을 준다","mis":"SO5-1-u2-X24"},{"t":"학생이 한 명뿐인 학교에도 선생님을 백 분씩 보낸다","mis":"SO5-1-u2-X24"}],"explanation":["닫으면 문제가 더 커져요.","벌주는 것은 옳지 않아요.","지나친 비용은 해내기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#9','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',4,'mc','auto','인구 분포의 불균형을 해결하는 노력을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X24']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C13","difficulty":4,"kind":"mc","stem":"인구 분포의 불균형을 해결하는 노력을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"정부와 지역, 주민이 함께 일자리와 살기 좋은 환경을 만들어 사람들이 고르게 살도록 돕는다","correct":true},{"t":"정부만 노력하면 되고 지역과 주민은 기다리면 된다","mis":"SO5-1-u2-X23"},{"t":"공공 기관을 수도권으로 더 모아야 불균형이 풀린다","mis":"SO5-1-u2-X23"},{"t":"사람들을 정해진 곳에 억지로 옮겨 살게 해야 한다","mis":"SO5-1-u2-X24"}],"explanation":["정부도 지역도 노력해요.","주민도 함께해요.","함께 잘 사는 국토예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#10','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',4,'essay','teacher','인구가 줄어드는 지역의 문제 하나를 골라 해결 방안을 한 가지 쓰고, 그 방안을 세 잣대(원인·옳음·실현)에 대어 평가하세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C14","difficulty":4,"kind":"essay","stem":"인구가 줄어드는 지역의 문제 하나를 골라 해결 방안을 한 가지 쓰고, 그 방안을 세 잣대(원인·옳음·실현)에 대어 평가하세요.","answer_guide":{"answer":"예: 상점과 병원이 줄어 생활이 불편한 문제를 골랐다. 방안은 물건을 싣고 마을을 찾아가는 이동형 상점을 지원하는 것이다. 상점이 없어 불편한 것이 원인이므로 물건이 찾아가면 원인 해결에 도움이 된다. 누구에게도 억지로 이사하게 하지 않으니 옳은 방안이다. 차 한 대로도 시작할 수 있어 비용과 노력을 생각할 때 실현할 수 있다.","scoring_points":["문제와 방안을 썼는가","원인·옳음·실현 세 잣대에 모두 대어 보았는가","각 잣대의 까닭을 썼는가"]},"explanation":["문제를 먼저 골라요.","세 잣대에 모두 대요.","까닭을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#1','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'mc','auto','이 단원에서 공부한 내용을 동시로 표현할 때 주제로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"mc","stem":"이 단원에서 공부한 내용을 동시로 표현할 때 주제로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"우리 반이 좋아하는 급식 반찬","correct":true},{"t":"기후변화에 대응하는 기후 행동","mis":"SO5-1-u2-X26"},{"t":"자연재해에 대비하는 노력","mis":"SO5-1-u2-X26"},{"t":"우리나라 인구 분포의 불균형","mis":"SO5-1-u2-X26"}],"explanation":["단원에서 공부한 내용을 골라요.","기후·재해·인구가 있었어요.","급식 반찬은 공부한 내용이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#2','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'mc','auto','동시와 그림이 함께 있는 작품을 무엇이라고 하나요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"mc","stem":"동시와 그림이 함께 있는 작품을 무엇이라고 하나요?","options":[{"t":"시화","correct":true},{"t":"만화","mis":"SO5-1-u2-X26"},{"t":"일기","mis":"SO5-1-u2-X26"},{"t":"신문","mis":"SO5-1-u2-X26"}],"explanation":["시와 그림이에요.","동시를 그림으로 꾸며요.","시화라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#3','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'sa','auto','동시를 소리 내어 읽을 때 느껴지는 가락을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"sa","stem":"동시를 소리 내어 읽을 때 느껴지는 가락을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["운율"],"explanation":["읽는 맛이에요.","비슷한 길이로 끊어 살려요.","운율이에요."],"mis":"SO5-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#4','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'ox','auto','동시를 짓기 전에 먼저 주제에 대한 내 경험과 생각을 이야기로 써요.',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"ox","stem":"동시를 짓기 전에 먼저 주제에 대한 내 경험과 생각을 이야기로 써요.","answer":"O","reason_options":[{"t":"이야기가 있어야 그것을 줄여 동시로 지을 수 있기 때문에","correct":true},{"t":"동시는 이야기 없이 아무 말이나 늘어놓는 글이기 때문에","mis":"SO5-1-u2-X26"}],"mis":"SO5-1-u2-X26","explanation":["먼저 이야기를 써요.","이야기가 바탕이에요.","그다음 동시로 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#5','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','고른 주제를 이야기로 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"고른 주제를 이야기로 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"주제에 대한 내 생각과 경험, 공부한 내용이 잘 드러나게 쓴다","correct":true},{"t":"어려운 낱말을 되도록 많이 넣어 쓴다","mis":"SO5-1-u2-X26"},{"t":"친구가 쓴 이야기를 그대로 옮겨 쓴다","mis":"SO5-1-u2-X26"},{"t":"주제와 상관없는 재미있는 일만 쓴다","mis":"SO5-1-u2-X26"}],"explanation":["내 경험이 바탕이에요.","공부한 내용도 드러나요.","글의 순서도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#6','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','내가 쓴 이야기를 동시로 옮길 때 첫 줄로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"내가 쓴 이야기를 동시로 옮길 때 첫 줄로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"친구가 내게 준 노란 손수건","correct":true},{"t":"북극곰이 나에게 편지를 보내 왔다","mis":"SO5-1-u2-X26"},{"t":"오늘 급식은 참 맛있었다","mis":"SO5-1-u2-X26"},{"t":"손을 씻고 무심코 휴지를 뜯어 물기를 닦았는데 친구가 그것을 유심히 보았다","mis":"SO5-1-u2-X26"}],"explanation":["이야기에 나온 일이에요.","짧게 줄였어요.","기후 행동과 이어져요."],"asset":{"type":"passage","lines":["손을 씻고 무심코 휴지를 뜯어 물기를 닦았다.","친구가 노란 손수건을 건네며 기후변화를 막자고 했다.","기후 행동에 앞장서겠다던 다짐이 떠올라 부끄러웠다."],"title":"내가 쓴 이야기(주제 — 기후 행동)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#7','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','지은 동시를 다시 읽어 볼 때 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"지은 동시를 다시 읽어 볼 때 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"이야기로 쓴 내용이 잘 나타나도록 고칠 곳을 고친다","correct":true},{"t":"잘못된 곳이 있어도 처음 지은 대로 둔다","mis":"SO5-1-u2-X26"},{"t":"줄마다 글자 수가 같은지만 센다","mis":"SO5-1-u2-X26"},{"t":"친구의 동시와 똑같아지도록 고친다","mis":"SO5-1-u2-X26"}],"explanation":["다시 읽어 봐요.","고칠 곳만 고쳐요.","고치는 일까지가 동시 짓기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#8','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','동시와 어울리는 그림을 그릴 때 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"동시와 어울리는 그림을 그릴 때 알맞은 것은 어느 것인가요?","options":[{"t":"동시의 내용을 잘 나타내는 장면을 그린다","correct":true},{"t":"가장 좋아하는 색만 골라 칠한다","mis":"SO5-1-u2-X26"},{"t":"동시와 상관없어도 예쁜 그림을 그린다","mis":"SO5-1-u2-X26"},{"t":"글씨가 안 보이게 그림을 크게 그린다","mis":"SO5-1-u2-X26"}],"explanation":["그림은 동시를 보여 줘요.","동시가 말하는 장면이에요.","내용을 나타내게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#9','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'ox','auto','친구들과 시화를 바꿔 볼 때는 잘 지은 작품과 못 지은 작품을 가르는 데 힘써요.',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"ox","stem":"친구들과 시화를 바꿔 볼 때는 잘 지은 작품과 못 지은 작품을 가르는 데 힘써요.","answer":"X","reason_options":[{"t":"서로의 시화에서 좋은 점을 찾아 콕 집어 말해 주는 시간이기 때문에","correct":true},{"t":"시화는 점수를 매기려고 만드는 것이기 때문에","mis":"SO5-1-u2-X26"}],"mis":"SO5-1-u2-X26","explanation":["좋은 점을 찾아요.","무엇이 좋았는지 말해요.","가르는 시간이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#10','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',3,'mc','auto','이야기를 동시로 옮길 때 한 줄로 쓰기에 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"이야기를 동시로 옮길 때 한 줄로 쓰기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"학교에서는 너무 많은 학생이 한꺼번에 운동장에서 놀다가 다치지 않도록 학년별로 요일을 정했다","correct":true},{"t":"학생이 너무 많아 우리 학교는 운동장 요일제","mis":"SO5-1-u2-X26"},{"t":"우리 학년은 목요일에만 쓸 수 있는 운동장","mis":"SO5-1-u2-X26"},{"t":"나는 목요일이 가장 좋다","mis":"SO5-1-u2-X26"}],"explanation":["동시는 짧게 줄여요.","긴 문장을 그대로 옮기면 안 돼요.","하고 싶은 말만 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
