INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#2','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',2,'sa','auto','이야기를 동시로 옮길 때 하고 싶은 말만 남기고 어떻게 쓰나요? (□□ 줄여서 쓴다)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"sa","stem":"이야기를 동시로 옮길 때 하고 싶은 말만 남기고 어떻게 쓰나요? (□□ 줄여서 쓴다)","answer":["짧게"],"explanation":["이야기보다 훨씬 짧아요.","하고 싶은 말만 남겨요.","짧게 줄여 써요."],"mis":"SO5-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#3','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'mc','auto','내가 쓴 이야기로 지은 동시에 어울리는 그림은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"내가 쓴 이야기로 지은 동시에 어울리는 그림은 어느 것인가요?","options":[{"t":"친구에게 노란 손수건을 건네받는 장면","correct":true},{"t":"밤하늘에 별이 가득한 그림","mis":"SO5-1-u2-X26"},{"t":"공장 굴뚝에서 연기가 솟는 그림","mis":"SO5-1-u2-X26"},{"t":"바닷가에서 조개를 줍는 그림","mis":"SO5-1-u2-X26"}],"explanation":["동시의 한가운데 장면이에요.","손수건을 건네받았어요.","내용을 나타내는 장면을 그려요."],"asset":{"type":"passage","lines":["손을 씻고 무심코 휴지를 뜯어 물기를 닦았다.","친구가 노란 손수건을 건네며 기후변화를 막자고 했다.","기후 행동에 앞장서겠다던 다짐이 떠올라 부끄러웠다."],"title":"내가 쓴 이야기(주제 — 기후 행동)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#4','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'mc','auto','동시를 짓다가 내가 겪지 않은 일을 넣고 싶어졌어요. 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"동시를 짓다가 내가 겪지 않은 일을 넣고 싶어졌어요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각과 경험이 드러나도록 이야기에서 나온 내용으로 쓴다","correct":true},{"t":"더 재미있어 보이니 그대로 넣는다","mis":"SO5-1-u2-X26"},{"t":"친구의 경험을 내가 겪은 일처럼 쓴다","mis":"SO5-1-u2-X26"},{"t":"주제를 아예 다른 것으로 바꾼다","mis":"SO5-1-u2-X26"}],"explanation":["내 이야기가 바탕이에요.","겪지 않은 일은 내 이야기가 아니에요.","이야기에서 나온 내용으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#5','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'mc','auto','「긴급 재난 문자 덕분에 물이 찬 낮은 길을 피해 높은 길로 돌아온 일」로 동시를 지을 때, 함께 드러나는 공부한 내용은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"「긴급 재난 문자 덕분에 물이 찬 낮은 길을 피해 높은 길로 돌아온 일」로 동시를 지을 때, 함께 드러나는 공부한 내용은 어느 것인가요?","options":[{"t":"자연재해에 대비하는 노력","correct":true},{"t":"인구 분포의 불균형","mis":"SO5-1-u2-X26"},{"t":"기후 행동","mis":"SO5-1-u2-X26"},{"t":"계절별 바람의 방향","mis":"SO5-1-u2-X26"}],"explanation":["긴급 재난 문자가 나와요.","위험을 미리 알렸어요.","자연재해 대비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#6','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'ox','auto','이 활동은 사회에서 배운 것을 국어(동시)와 미술(그림)로 이어 표현하는 창의·융합 활동이에요.',ARRAY['SO5-1-u2-X25']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"ox","stem":"이 활동은 사회에서 배운 것을 국어(동시)와 미술(그림)로 이어 표현하는 창의·융합 활동이에요.","answer":"O","reason_options":[{"t":"공부한 내용을 골라 동시와 그림으로 새롭게 바꾸기 때문에","correct":true},{"t":"배운 내용을 외워 그대로 적는 활동이기 때문에","mis":"SO5-1-u2-X25"}],"mis":"SO5-1-u2-X25","explanation":["사회 내용을 골라요.","동시와 그림으로 바꿔요.","세 과목이 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#7','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'error','auto','동시 짓기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"error","stem":"동시 짓기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「동시는 한 번에 지어야 하니까 다 짓고 나면 고치지 않아.」","correct":true,"mis_target":"SO5-1-u2-X26"},{"t":"이준 — 「줄의 차례를 생각하며 흐름을 살려 써.」","mis":"SO5-1-u2-X26"},{"t":"채이 — 「공부한 내용이 드러나도록 주제를 살려 써.」","mis":"SO5-1-u2-X26"}],"explanation":["동시는 다시 읽고 고쳐요.","고칠수록 또렷해져요.","로아의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#8','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',4,'mc','auto','「운동장 요일제」 동시가 「인구 분포의 불균형」이라는 주제를 잘 드러내는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"mc","stem":"「운동장 요일제」 동시가 「인구 분포의 불균형」이라는 주제를 잘 드러내는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"수도권에 사람이 많이 모여 학생이 넘치는 내 경험으로 인구가 몰린 곳의 모습을 보여 주기 때문에","correct":true},{"t":"운동장이라는 낱말이 들어 있기 때문에","mis":"SO5-1-u2-X26"},{"t":"요일이 많이 나와 운율이 살기 때문에","mis":"SO5-1-u2-X26"},{"t":"인구 분포와 상관없이 재미있기 때문에","mis":"SO5-1-u2-X26"}],"explanation":["학생이 너무 많았어요.","사람이 몰린 수도권의 일이에요.","경험으로 주제를 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#9','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',4,'mc','auto','좋은 시화를 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26','SO5-1-u2-X25']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"mc","stem":"좋은 시화를 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"공부한 내용과 내 경험이 담긴 짧은 동시에, 그 내용을 나타내는 장면을 그린 것","correct":true},{"t":"어려운 낱말이 많고 그림이 화려한 것","mis":"SO5-1-u2-X26"},{"t":"교과서 문장을 그대로 옮기고 아무 그림이나 그린 것","mis":"SO5-1-u2-X25"},{"t":"내가 겪지 않은 재미있는 일만 모은 것","mis":"SO5-1-u2-X26"}],"explanation":["공부한 내용이 담겨요.","내 경험이 담겨요.","그림이 동시를 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#10','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',4,'essay','teacher','이 단원에서 공부한 내용 가운데 주제 하나를 골라, 그 주제와 관련한 내 경험을 두세 문장으로 쓰고 그것을 짧게 줄인 동시 세 줄과 그릴 장면을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 내용 가운데 주제 하나를 골라, 그 주제와 관련한 내 경험을 두세 문장으로 쓰고 그것을 짧게 줄인 동시 세 줄과 그릴 장면을 쓰세요.","answer_guide":{"answer":"예: 주제 — 기후변화에 대응하는 기후 행동. 경험 — 엄마와 마트에 갈 때 장바구니를 깜빡했다. 비닐봉지를 사려다가 기후 행동을 하겠다던 다짐이 떠올라 손으로 물건을 들고 왔다. 동시 — 깜빡 잊은 장바구니 / 두 손 가득 사과와 우유 / 무거워도 지구는 가볍게. 그릴 장면 — 두 손 가득 물건을 들고 웃으며 걷는 나.","scoring_points":["단원에서 공부한 주제를 골랐는가","내 경험을 이야기로 썼는가","짧게 줄인 동시와 내용에 맞는 장면을 썼는가"]},"explanation":["주제를 골라요.","내 경험을 써요.","짧게 줄이고 장면을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#1','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C1',1,'mc','auto','다온이 일기 ②에서 「며칠째 굵은 비가 쏟아졌다」는 것은 날씨와 기후 가운데 무엇에 대한 이야기인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"다온이 일기 ②에서 「며칠째 굵은 비가 쏟아졌다」는 것은 날씨와 기후 가운데 무엇에 대한 이야기인가요?","options":[{"t":"날씨","correct":true},{"t":"기후","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"인구","mis":"SO5-1-u2-X02"}],"explanation":["며칠 동안의 일이에요.","짧은 시간의 대기 상태예요.","날씨예요."],"asset":{"type":"passage","lines":["7월 — 며칠째 굵은 비가 쏟아졌다. 하천 물이 불어 낮은 길이 잠겼다.","집에 오는 길에 휴대 전화로 긴급 재난 문자가 왔다.","물이 찬 길로 다니지 말라는 안내를 보고 높은 길로 돌아왔다."],"title":"다온이 일기 ② 여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#2','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C3',1,'mc','auto','다온이 일기 ④의 겨울에 불어온 바람은 어디에서 왔나요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"다온이 일기 ④의 겨울에 불어온 바람은 어디에서 왔나요?","options":[{"t":"북서쪽 육지","correct":true},{"t":"남쪽 바다","mis":"SO5-1-u2-X04"},{"t":"동쪽 바다","mis":"SO5-1-u2-X04"},{"t":"남서쪽 바다","mis":"SO5-1-u2-X04"}],"explanation":["차고 건조한 바람이에요.","넓은 육지를 지나왔어요.","북서쪽 육지예요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#3','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C4',1,'mc','auto','우리나라에서 연 강수량의 절반 이상이 내리는 계절은 언제인가요?',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라에서 연 강수량의 절반 이상이 내리는 계절은 언제인가요?","options":[{"t":"여름","correct":true},{"t":"겨울","mis":"SO5-1-u2-X07"},{"t":"봄","mis":"SO5-1-u2-X07"},{"t":"가을","mis":"SO5-1-u2-X07"}],"explanation":["장맛비가 내려요.","7·8월에 몰려요.","여름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#4','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C5',1,'mc','auto','다온이 일기 ①에서 날아온 모래 먼지는 어떤 자연재해인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"다온이 일기 ①에서 날아온 모래 먼지는 어떤 자연재해인가요?","options":[{"t":"황사","correct":true},{"t":"폭설","mis":"SO5-1-u2-X09"},{"t":"한파","mis":"SO5-1-u2-X09"},{"t":"태풍","mis":"SO5-1-u2-X09"}],"explanation":["사막의 모래 먼지예요.","봄에 날아와요.","황사예요."],"asset":{"type":"passage","lines":["4월 — 아침 하늘이 누렇게 뿌옜다. 모래 먼지가 날아왔다고 했다.","엄마가 마스크를 꼭 쓰라고 하셨다.","할머니가 사는 솔내 마을은 몇 주째 비가 오지 않아 논바닥이 갈라졌다."],"title":"다온이 일기 ① 봄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#5','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C7',1,'mc','auto','다온이 일기 ⑤의 뉴스처럼 「여름이 점점 길어진다」는 것은 무엇 때문에 나타나는 변화인가요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X12','SO5-1-u2-X01']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"다온이 일기 ⑤의 뉴스처럼 「여름이 점점 길어진다」는 것은 무엇 때문에 나타나는 변화인가요?","options":[{"t":"기후변화","correct":true},{"t":"인구 이동","mis":"SO5-1-u2-X16"},{"t":"지형 변화","mis":"SO5-1-u2-X12"},{"t":"하루의 날씨","mis":"SO5-1-u2-X01"}],"explanation":["기온이 꾸준히 올라요.","계절 길이가 달라져요.","기후변화 때문이에요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#6','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C9',1,'mc','auto','일정한 넓이(1 km²) 안에 사는 사람의 수를 나타내는 말은 어느 것인가요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"일정한 넓이(1 km²) 안에 사는 사람의 수를 나타내는 말은 어느 것인가요?","options":[{"t":"인구 밀도","correct":true},{"t":"인구","mis":"SO5-1-u2-X16"},{"t":"인구 분포","mis":"SO5-1-u2-X16"},{"t":"인구 구조","mis":"SO5-1-u2-X16"}],"explanation":["1 km² 안을 봐요.","빽빽한 정도예요.","인구 밀도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#7','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C10',1,'mc','auto','다온이네 한빛시가 있는 경기도는 어디에 속하나요?',ARRAY['SO5-1-u2-X20','SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"다온이네 한빛시가 있는 경기도는 어디에 속하나요?","options":[{"t":"수도권","correct":true},{"t":"비수도권","mis":"SO5-1-u2-X20"},{"t":"촌락","mis":"SO5-1-u2-X19"},{"t":"남서쪽 평야 지대","mis":"SO5-1-u2-X19"}],"explanation":["서울과 맞닿아 있어요.","서울·인천·경기예요.","수도권이에요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#8','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',1,'mc','auto','다온이 일기 ⑥에서 아빠 출근길 지하철이 꽉 차는 것은 어떤 문제인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"다온이 일기 ⑥에서 아빠 출근길 지하철이 꽉 차는 것은 어떤 문제인가요?","options":[{"t":"교통 혼잡","correct":true},{"t":"일손 부족","mis":"SO5-1-u2-X21"},{"t":"폐교","mis":"SO5-1-u2-X21"},{"t":"빈집 증가","mis":"SO5-1-u2-X21"}],"explanation":["사람이 너무 많아요.","지하철이 붐벼요.","교통 혼잡이에요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#9','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C2',2,'mc','auto','다온이 일기 ④에서 이모가 한겨울에 밭에서 무를 거둘 수 있는 것은 무엇의 영향인가요?',ARRAY['SO5-1-u2-X03','SO5-1-u2-X17','SO5-1-u2-X04']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"mc","stem":"다온이 일기 ④에서 이모가 한겨울에 밭에서 무를 거둘 수 있는 것은 무엇의 영향인가요?","options":[{"t":"겨울에도 따뜻한 남쪽의 기후","correct":true},{"t":"그날 하루의 맑은 날씨","mis":"SO5-1-u2-X03"},{"t":"이모네 마을의 인구","mis":"SO5-1-u2-X17"},{"t":"북서쪽에서 부는 차가운 바람","mis":"SO5-1-u2-X04"}],"explanation":["남쪽 섬은 겨울에도 따뜻해요.","해마다 되풀이돼요.","기후의 영향이에요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#10','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C6',2,'mc','auto','다온이 일기 ②에서 다온이가 높은 길로 돌아올 수 있었던 것은 어떤 노력 덕분인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X15','SO5-1-u2-X11']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"mc","stem":"다온이 일기 ②에서 다온이가 높은 길로 돌아올 수 있었던 것은 어떤 노력 덕분인가요?","options":[{"t":"긴급 재난 문자로 미리 위험을 알린 노력","correct":true},{"t":"사람들을 수도권으로 옮긴 노력","mis":"SO5-1-u2-X23"},{"t":"기후 행동 수첩을 쓴 노력","mis":"SO5-1-u2-X15"},{"t":"하천 물길을 함부로 바꾼 일","mis":"SO5-1-u2-X11"}],"explanation":["휴대 전화로 문자가 왔어요.","물이 찬 길을 알렸어요.","미리 알리는 노력이에요."],"asset":{"type":"passage","lines":["7월 — 며칠째 굵은 비가 쏟아졌다. 하천 물이 불어 낮은 길이 잠겼다.","집에 오는 길에 휴대 전화로 긴급 재난 문자가 왔다.","물이 찬 길로 다니지 말라는 안내를 보고 높은 길로 돌아왔다."],"title":"다온이 일기 ② 여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#11','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C8',2,'mc','auto','다온이 일기 ⑤의 수첩에 적힌 일은 어떤 주체의 기후 행동인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑤의 수첩에 적힌 일은 어떤 주체의 기후 행동인가요?","options":[{"t":"개인","correct":true},{"t":"기업","mis":"SO5-1-u2-X14"},{"t":"정부와 국회","mis":"SO5-1-u2-X14"},{"t":"세계 여러 나라","mis":"SO5-1-u2-X14"}],"explanation":["다온이가 매일 해요.","손수건과 걷기예요.","개인의 기후 행동이에요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#12','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C9',2,'mc','auto','다온이 일기 ⑦에서 젊은 사람들이 도시로 떠난 까닭과 가장 가까운 환경은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦에서 젊은 사람들이 도시로 떠난 까닭과 가장 가까운 환경은 어느 것인가요?","options":[{"t":"일자리 같은 인문환경","correct":true},{"t":"기후 같은 자연환경","mis":"SO5-1-u2-X17"},{"t":"지형 같은 자연환경","mis":"SO5-1-u2-X17"},{"t":"하천 같은 자연환경","mis":"SO5-1-u2-X17"}],"explanation":["도시에는 일할 곳이 많아요.","사람이 만든 환경이에요.","인문환경이에요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#13','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C11',2,'mc','auto','다온이 일기 ⑦의 솔내 마을처럼 젊은 사람이 떠난 곳은 어떤 인구층의 비율이 높아지기 쉬운가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦의 솔내 마을처럼 젊은 사람이 떠난 곳은 어떤 인구층의 비율이 높아지기 쉬운가요?","options":[{"t":"노년층","correct":true},{"t":"청장년층","mis":"SO5-1-u2-X20"},{"t":"유소년층","mis":"SO5-1-u2-X20"},{"t":"세 층이 모두 같아진다","mis":"SO5-1-u2-X20"}],"explanation":["젊은 사람이 떠났어요.","어르신이 많이 남아요.","노년층 비율이 높아요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#14','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',2,'mc','auto','다온이 일기 ⑦에서 마을 가게가 문을 닫아 채소를 사기 어려워진 지역을 무엇이라고 부르나요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X20']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦에서 마을 가게가 문을 닫아 채소를 사기 어려워진 지역을 무엇이라고 부르나요?","options":[{"t":"식품 사막","correct":true},{"t":"혁신 도시","mis":"SO5-1-u2-X23"},{"t":"수도권","mis":"SO5-1-u2-X20"},{"t":"지질 공원","mis":"SO5-1-u2-X23"}],"explanation":["신선 식품을 구하기 어려워요.","가게가 문을 닫았어요.","식품 사막이에요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#15','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C13',2,'mc','auto','다온이 일기 ⑧에서 엄마가 한 일은 어떤 제도인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X10']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑧에서 엄마가 한 일은 어떤 제도인가요?","options":[{"t":"고향 사랑 기부제","correct":true},{"t":"디지털 관광 주민증","mis":"SO5-1-u2-X23"},{"t":"공공 기관 이전","mis":"SO5-1-u2-X23"},{"t":"기상 특보","mis":"SO5-1-u2-X10"}],"explanation":["고향에 기부했어요.","답례품으로 쌀을 받았어요.","고향 사랑 기부제예요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#16','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C14',2,'mc','auto','해결 방안을 평가하는 세 잣대가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"mc","stem":"해결 방안을 평가하는 세 잣대가 아닌 것은 어느 것인가요?","options":[{"t":"방안 이름이 멋지게 들리는가","correct":true},{"t":"문제의 원인을 해결하는 데 도움이 되는가","mis":"SO5-1-u2-X24"},{"t":"도덕적으로 옳은가","mis":"SO5-1-u2-X24"},{"t":"비용과 노력을 생각할 때 실현할 수 있는가","mis":"SO5-1-u2-X24"}],"explanation":["잣대는 원인·옳음·실현이에요.","이름은 잣대가 아니에요.","셋을 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#17','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C3',3,'mc','auto','다온이 일기 ④에서 다온이네는 몹시 추웠고 남쪽 섬은 밭일을 할 만큼 따뜻했어요. 이것과 같은 까닭으로 설명할 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X07']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"mc","stem":"다온이 일기 ④에서 다온이네는 몹시 추웠고 남쪽 섬은 밭일을 할 만큼 따뜻했어요. 이것과 같은 까닭으로 설명할 수 있는 것은 어느 것인가요?","options":[{"t":"남북의 기온 차이가 여름보다 겨울에 훨씬 크다","correct":true},{"t":"여름에 남북의 기온 차이가 가장 크다","mis":"SO5-1-u2-X05"},{"t":"남쪽으로 갈수록 기온이 낮아진다","mis":"SO5-1-u2-X05"},{"t":"겨울에 강수량이 가장 많다","mis":"SO5-1-u2-X07"}],"explanation":["겨울엔 북쪽이 크게 추워요.","남쪽은 덜 추워요.","그래서 차이가 커요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#18','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C5',3,'mc','auto','다온이 일기 ①~④에 나온 자연재해를 계절 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"mc","stem":"다온이 일기 ①~④에 나온 자연재해를 계절 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"황사·가뭄 → 호우·홍수 → 태풍 → 한파","correct":true},{"t":"한파 → 태풍 → 호우·홍수 → 황사·가뭄","mis":"SO5-1-u2-X09"},{"t":"태풍 → 황사·가뭄 → 한파 → 호우·홍수","mis":"SO5-1-u2-X09"},{"t":"호우·홍수 → 한파 → 황사·가뭄 → 태풍","mis":"SO5-1-u2-X09"}],"explanation":["①은 4월, ②는 7월이에요.","③은 9월 초, ④는 1월이에요.","계절 차례로 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#19','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C7',3,'mc','auto','다온이 일기 ⑤의 뉴스에 나온 「역대 가장 긴 폭염」이 자주 들리는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X13','SO5-1-u2-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑤의 뉴스에 나온 「역대 가장 긴 폭염」이 자주 들리는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기후변화로 자연재해가 더 잦아지고 강해졌기 때문에","correct":true},{"t":"그해에만 우연히 더웠기 때문에","mis":"SO5-1-u2-X13"},{"t":"겨울이 점점 길어지기 때문에","mis":"SO5-1-u2-X12"},{"t":"사람들이 숲을 많이 가꾸었기 때문에","mis":"SO5-1-u2-X12"}],"explanation":["「역대」가 자주 나와요.","재해가 더 세졌어요.","기후변화의 영향이에요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#20','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C10',3,'mc','auto','다온이 일기 ⑥과 ⑦을 견줄 때 두 곳의 인구 분포를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X16']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑥과 ⑦을 견줄 때 두 곳의 인구 분포를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"한빛시는 사람이 몰려 인구 밀도가 높고, 솔내 마을은 사람이 줄어 인구 밀도가 낮다","correct":true},{"t":"두 곳 모두 사람이 몰려 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"솔내 마을이 한빛시보다 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"두 곳의 인구 분포는 견줄 수 없다","mis":"SO5-1-u2-X16"}],"explanation":["한빛시는 지하철이 꽉 차요.","솔내 마을은 사람이 떠났어요.","밀도가 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#21','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',3,'mc','auto','다온이 일기 ⑥과 ⑦에 나온 일이 계속 되풀이된다면 나라 전체에 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑥과 ⑦에 나온 일이 계속 되풀이된다면 나라 전체에 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 격차가 커져 국가 경쟁력이 떨어질 수 있다","correct":true},{"t":"두 지역의 인구가 저절로 비슷해진다","mis":"SO5-1-u2-X22"},{"t":"수도권만 좋아지고 나라 전체에는 문제가 없다","mis":"SO5-1-u2-X22"},{"t":"솔내 마을에 사람이 저절로 돌아온다","mis":"SO5-1-u2-X22"}],"explanation":["한빛시는 더 붐벼요.","솔내는 더 비어요.","격차가 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#22','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C13',3,'mc','auto','다온이 일기 ⑧의 햇빛 발전 사업이 솔내 마을에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24','SO5-1-u2-X23']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑧의 햇빛 발전 사업이 솔내 마을에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주민이 직접 참여해 소득이 늘면 지역 경제가 살아나 사람이 모일 수 있기 때문에","correct":true},{"t":"사람들을 억지로 마을로 옮겨 오게 하기 때문에","mis":"SO5-1-u2-X24"},{"t":"마을 학교를 닫게 하기 때문에","mis":"SO5-1-u2-X23"},{"t":"수도권에 사람을 더 모으기 때문에","mis":"SO5-1-u2-X23"}],"explanation":["주민이 참여했어요.","수익을 나누었어요.","경제가 살아나요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#23','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C1',4,'mc','auto','「우리나라 지리 탐구」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X01','SO5-1-u2-X25']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C1","difficulty":4,"kind":"mc","stem":"「우리나라 지리 탐구」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"우리나라는 계절마다 기후가 달라 계절별 자연재해가 생기고 기후변화로 심해지며, 인구는 수도권에 몰려 불균형 문제를 함께 풀어 가야 한다","correct":true},{"t":"우리나라는 계절이 바뀌어도 기후가 같고 인구는 전국에 고르게 퍼져 있다","mis":"SO5-1-u2-X04"},{"t":"기후는 매일 바뀌고 인구 문제는 수도권에만 있다","mis":"SO5-1-u2-X01"},{"t":"기후변화와 인구 문제는 수치와 연도만 외우면 된다","mis":"SO5-1-u2-X25"}],"explanation":["계절별 기후와 재해예요.","기후변화로 심해져요.","인구 불균형을 함께 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#24','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C3',4,'essay','teacher','다온이 일기 ②와 ④를 보고 여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 때문에 두 계절의 기온과 강수가 어떻게 다른지, 그리고 남북 기온 차이가 어느 계절에 더 큰지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C3","difficulty":4,"kind":"essay","stem":"다온이 일기 ②와 ④를 보고 여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 때문에 두 계절의 기온과 강수가 어떻게 다른지, 그리고 남북 기온 차이가 어느 계절에 더 큰지 쓰세요.","answer_guide":{"answer":"예: 여름에는 남쪽 바다에서 뜨겁고 습한 바람이 불어와 기온이 높고 일기 ②처럼 비가 많이 내린다. 겨울에는 북서쪽 육지에서 차갑고 건조한 바람이 불어와 기온이 낮고 강수가 적다. 남북의 기온 차이는 겨울에 더 커서 일기 ④처럼 다온이네가 추운 날에도 남쪽 섬에서는 밭일을 할 수 있다.","scoring_points":["두 계절 바람의 방향과 성질을 썼는가","바람과 기온·강수를 이어 썼는가","남북 기온 차이가 겨울에 더 크다고 썼는가"]},"explanation":["여름 — 남쪽 바다예요.","겨울 — 북서쪽 육지예요.","남북 차이는 겨울에 커요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#25','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',4,'essay','teacher','다온이 일기 ⑥과 ⑦에 나온 문제를 수도권과 비수도권으로 나누어 각각 두 가지씩 쓰고, 이 문제들이 되풀이되면 어떤 일이 생기는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑥과 ⑦에 나온 문제를 수도권과 비수도권으로 나누어 각각 두 가지씩 쓰고, 이 문제들이 되풀이되면 어떤 일이 생기는지 쓰세요.","answer_guide":{"answer":"예: 수도권인 한빛시에서는 지하철이 꽉 차는 교통 혼잡과 집값이 오르는 주택 문제가 있다. 비수도권인 솔내 마을에서는 신입생이 없는 학교와 가게가 문을 닫아 채소를 사기 어려운 문제가 있다. 사람이 몰리는 곳은 더 몰리고 떠나는 곳은 더 떠나는 일이 되풀이되면 지역 격차가 커지고 국가 경쟁력이 떨어질 수 있다.","scoring_points":["수도권의 문제를 두 가지 썼는가","비수도권의 문제를 두 가지 썼는가","되풀이될 때의 결과를 썼는가"]},"explanation":["몰린 곳의 문제예요.","빈 곳의 문제예요.","격차가 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#1','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C1',1,'sa','auto','오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"sa","stem":"오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기후"],"explanation":["여러 해를 모아요.","평균적인 모습이에요.","기후예요."],"mis":"SO5-1-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#2','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C3',1,'mc','auto','여름에 남쪽 바다에서 불어오는 바람의 성질은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"여름에 남쪽 바다에서 불어오는 바람의 성질은 어느 것인가요?","options":[{"t":"뜨겁고 습하다","correct":true},{"t":"차갑고 건조하다","mis":"SO5-1-u2-X04"},{"t":"차갑고 습하다","mis":"SO5-1-u2-X04"},{"t":"뜨겁고 건조하다","mis":"SO5-1-u2-X04"}],"explanation":["바다를 지나와요.","물기를 많이 머금어요.","뜨겁고 습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#3','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C4',1,'mc','auto','우리나라의 연 강수량은 대체로 어느 쪽으로 갈수록 많아지나요?',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라의 연 강수량은 대체로 어느 쪽으로 갈수록 많아지나요?","options":[{"t":"남쪽","correct":true},{"t":"북쪽","mis":"SO5-1-u2-X07"},{"t":"어디나 같다","mis":"SO5-1-u2-X07"},{"t":"동쪽에서만","mis":"SO5-1-u2-X07"}],"explanation":["제주가 서울보다 많아요.","서울이 중강진보다 많아요.","남쪽으로 갈수록 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#4','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C5',1,'mc','auto','다온이 일기 ①에서 솔내 마을의 논바닥이 갈라진 것은 어떤 자연재해 때문인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"다온이 일기 ①에서 솔내 마을의 논바닥이 갈라진 것은 어떤 자연재해 때문인가요?","options":[{"t":"가뭄","correct":true},{"t":"홍수","mis":"SO5-1-u2-X09"},{"t":"호우","mis":"SO5-1-u2-X09"},{"t":"폭설","mis":"SO5-1-u2-X09"}],"explanation":["비가 몇 주째 오지 않았어요.","물이 말랐어요.","가뭄이에요."],"asset":{"type":"passage","lines":["4월 — 아침 하늘이 누렇게 뿌옜다. 모래 먼지가 날아왔다고 했다.","엄마가 마스크를 꼭 쓰라고 하셨다.","할머니가 사는 솔내 마을은 몇 주째 비가 오지 않아 논바닥이 갈라졌다."],"title":"다온이 일기 ① 봄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#5','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C7',1,'mc','auto','기후변화로 우리나라의 겨울은 어떻게 달라지고 있나요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"기후변화로 우리나라의 겨울은 어떻게 달라지고 있나요?","options":[{"t":"짧아지고 있다","correct":true},{"t":"길어지고 있다","mis":"SO5-1-u2-X12"},{"t":"그대로이다","mis":"SO5-1-u2-X12"},{"t":"여름보다 길어지고 있다","mis":"SO5-1-u2-X12"}],"explanation":["여름은 길어져요.","겨울은 짧아져요.","22일쯤 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#6','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C9',1,'mc','auto','인구가 모이거나 흩어져 있는 정도를 나타내는 말은 어느 것인가요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"인구가 모이거나 흩어져 있는 정도를 나타내는 말은 어느 것인가요?","options":[{"t":"인구 분포","correct":true},{"t":"인구","mis":"SO5-1-u2-X16"},{"t":"인구 밀도","mis":"SO5-1-u2-X16"},{"t":"순이동","mis":"SO5-1-u2-X16"}],"explanation":["퍼져 있는 모양이에요.","모였는지 흩어졌는지 봐요.","인구 분포예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#7','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C10',1,'mc','auto','오늘날 우리나라 인구의 절반 정도가 모여 사는 곳은 어디인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"오늘날 우리나라 인구의 절반 정도가 모여 사는 곳은 어디인가요?","options":[{"t":"수도권","correct":true},{"t":"남서쪽 평야 지대","mis":"SO5-1-u2-X19"},{"t":"북동쪽 산지","mis":"SO5-1-u2-X19"},{"t":"바닷가 작은 섬","mis":"SO5-1-u2-X19"}],"explanation":["일자리가 많은 곳이에요.","서울 둘레예요.","수도권이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#8','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C12',1,'mc','auto','다온이 일기 ⑦에서 1학년 신입생이 한 명도 없는 학교가 생긴 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"다온이 일기 ⑦에서 1학년 신입생이 한 명도 없는 학교가 생긴 까닭은 어느 것인가요?","options":[{"t":"마을의 인구가 줄었기 때문에","correct":true},{"t":"마을의 인구가 너무 많기 때문에","mis":"SO5-1-u2-X21"},{"t":"마을에 학교가 새로 많이 생겼기 때문에","mis":"SO5-1-u2-X21"},{"t":"마을의 기후가 바뀌었기 때문에","mis":"SO5-1-u2-X22"}],"explanation":["젊은 사람이 떠났어요.","아이도 줄었어요.","그래서 신입생이 없어요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#9','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C2',2,'mc','auto','기후가 산업에 준 영향으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X03','SO5-1-u2-X17']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"mc","stem":"기후가 산업에 준 영향으로 알맞은 것은 어느 것인가요?","options":[{"t":"바람이 센 곳에 바람으로 전기를 만드는 시설이 생겼다","correct":true},{"t":"하루 비가 와서 축구 경기가 미뤄졌다","mis":"SO5-1-u2-X03"},{"t":"사람이 많은 도시에 지하철이 생겼다","mis":"SO5-1-u2-X17"},{"t":"산이 많은 곳에 터널을 뚫었다","mis":"SO5-1-u2-X03"}],"explanation":["바람이 늘 세요.","그 힘을 이용해요.","기후가 산업을 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#10','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C6',2,'mc','auto','다온이 일기 ③에서 아빠와 다온이가 한 일로 알맞은 설명은 어느 것인가요?',ARRAY['SO5-1-u2-X10','SO5-1-u2-X09']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"mc","stem":"다온이 일기 ③에서 아빠와 다온이가 한 일로 알맞은 설명은 어느 것인가요?","options":[{"t":"태풍 때의 국민 행동 요령을 실천했다","correct":true},{"t":"기상 특보를 무시하고 평소처럼 지냈다","mis":"SO5-1-u2-X10"},{"t":"한파에 대비해 수도관을 감쌌다","mis":"SO5-1-u2-X09"},{"t":"황사에 대비해 마스크를 썼다","mis":"SO5-1-u2-X09"}],"explanation":["날아갈 물건을 들여놓았어요.","밖에 나가지 않았어요.","태풍 행동 요령이에요."],"asset":{"type":"passage","lines":["9월 초 — 남서쪽에서 태풍이 올라온다며 태풍 주의보가 내려졌다.","아빠와 베란다의 화분과 빨래 건조대를 안으로 들여놓았다.","그날은 밖에 나가지 않고 집에서 보냈다."],"title":"다온이 일기 ③ 늦여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#11','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C8',2,'mc','auto','다온이 일기 ⑤에서 손수건을 깜빡한 날 다온이가 한 일로 가장 알맞은 설명은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑤에서 손수건을 깜빡한 날 다온이가 한 일로 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"까닭을 돌아보고 다시 실천할 방법을 찾았다","correct":true},{"t":"그 행동을 수첩에서 지웠다","mis":"SO5-1-u2-X15"},{"t":"기후 행동을 그만두었다","mis":"SO5-1-u2-X14"},{"t":"다른 사람에게 대신 하라고 했다","mis":"SO5-1-u2-X14"}],"explanation":["△를 표시했어요.","왜 잊었는지 생각했어요.","손수건을 하나 더 챙겼어요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#12','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C9',2,'mc','auto','인구 분포에 영향을 주는 자연환경끼리 바르게 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"인구 분포에 영향을 주는 자연환경끼리 바르게 묶인 것은 어느 것인가요?","options":[{"t":"기후·지형","correct":true},{"t":"일자리·교통","mis":"SO5-1-u2-X17"},{"t":"교육·교통","mis":"SO5-1-u2-X17"},{"t":"지형·일자리","mis":"SO5-1-u2-X17"}],"explanation":["자연이 만든 환경이에요.","날씨와 땅의 생김새예요.","기후·지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#13','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C11',2,'mc','auto','청장년층에 해당하는 나이는 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"mc","stem":"청장년층에 해당하는 나이는 어느 것인가요?","options":[{"t":"15~64세","correct":true},{"t":"14세 이하","mis":"SO5-1-u2-X20"},{"t":"65세 이상","mis":"SO5-1-u2-X20"},{"t":"10세 이하","mis":"SO5-1-u2-X20"}],"explanation":["일하는 나이예요.","15세부터 64세까지예요.","청장년층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#14','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C12',2,'mc','auto','다온이 일기 ⑦에 나온 문제 가운데 청장년층이 빠져나가 생긴 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦에 나온 문제 가운데 청장년층이 빠져나가 생긴 문제는 어느 것인가요?","options":[{"t":"농사일을 도울 사람이 부족하다","correct":true},{"t":"지하철이 꽉 찬다","mis":"SO5-1-u2-X21"},{"t":"집값이 많이 오른다","mis":"SO5-1-u2-X21"},{"t":"운동장 쓰는 요일이 정해져 있다","mis":"SO5-1-u2-X21"}],"explanation":["젊은 사람이 떠났어요.","일할 사람이 줄었어요.","일손 부족이에요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#15','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C13',2,'mc','auto','다온이 일기 ⑧에서 도시 청년들이 솔내 마을에 머물며 살아 보게 돕는 노력은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑧에서 도시 청년들이 솔내 마을에 머물며 살아 보게 돕는 노력은 어느 것인가요?","options":[{"t":"청년 마을 만들기","correct":true},{"t":"로컬 브랜딩","mis":"SO5-1-u2-X23"},{"t":"작은 학교 살리기","mis":"SO5-1-u2-X23"},{"t":"공공 기관 이전","mis":"SO5-1-u2-X23"}],"explanation":["청년이 머물러요.","살아 보게 도와요.","청년 마을 만들기예요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#16','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C15',2,'mc','auto','다온이 일기 ⑧에서 다온이가 동시를 지으려면 먼저 해야 할 일은 어느 것인가요?',ARRAY['SO5-1-u2-X26','SO5-1-u2-X25']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑧에서 다온이가 동시를 지으려면 먼저 해야 할 일은 어느 것인가요?","options":[{"t":"솔내 마을 이야기에서 내 경험과 생각을 이야기로 정리한다","correct":true},{"t":"그림부터 크게 그린다","mis":"SO5-1-u2-X26"},{"t":"친구의 동시를 그대로 베낀다","mis":"SO5-1-u2-X26"},{"t":"어려운 낱말 목록을 외운다","mis":"SO5-1-u2-X25"}],"explanation":["주제를 골랐어요.","이야기로 먼저 써요.","그다음 동시로 줄여요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#17','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C4',3,'mc','auto','다온이 일기 ②의 굵은 비와 ④의 차고 건조한 바람을 함께 볼 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X07']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C4","difficulty":3,"kind":"mc","stem":"다온이 일기 ②의 굵은 비와 ④의 차고 건조한 바람을 함께 볼 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"여름에는 습한 바다 바람으로 비가 많고 겨울에는 건조한 육지 바람으로 강수가 적다","correct":true},{"t":"여름과 겨울 모두 바다 바람이 분다","mis":"SO5-1-u2-X04"},{"t":"겨울에 비가 가장 많이 내린다","mis":"SO5-1-u2-X07"},{"t":"바람과 강수는 서로 관계없다","mis":"SO5-1-u2-X04"}],"explanation":["여름 바람은 습해요.","겨울 바람은 건조해요.","그래서 강수가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#18','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C6',3,'mc','auto','다온이 일기 ②와 ③을 함께 볼 때 자연재해에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X10','SO5-1-u2-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"mc","stem":"다온이 일기 ②와 ③을 함께 볼 때 자연재해에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연재해는 막을 수 없지만 미리 알리는 정보와 행동 요령으로 피해를 줄일 수 있다","correct":true},{"t":"자연재해는 미리 알 수 없으니 대비할 필요가 없다","mis":"SO5-1-u2-X10"},{"t":"자연재해 대비는 어른만 하면 된다","mis":"SO5-1-u2-X10"},{"t":"비와 바람은 언제나 자연재해이다","mis":"SO5-1-u2-X08"}],"explanation":["문자와 특보가 미리 알렸어요.","다온이도 행동했어요.","피해를 줄였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#19','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C8',3,'mc','auto','다온이 일기 ⑤의 수첩에 하나를 더 적는다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑤의 수첩에 하나를 더 적는다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빈 교실과 화장실의 전등 끄기","correct":true},{"t":"기후변화를 막는 법 만들기","mis":"SO5-1-u2-X15"},{"t":"공장의 오염 물질 줄이는 기술 개발하기","mis":"SO5-1-u2-X15"},{"t":"가까운 거리도 자가용으로 다니기","mis":"SO5-1-u2-X14"}],"explanation":["내가 매일 할 수 있는 일이에요.","법은 국회, 기술은 기업이에요.","전등 끄기가 알맞아요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#20','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C9',3,'mc','auto','넓이가 같은 두 마을 가운데 ㉮ 마을에는 1,000명, ㉯ 마을에는 100명이 살아요. 알맞은 설명은 어느 것인가요?',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"넓이가 같은 두 마을 가운데 ㉮ 마을에는 1,000명, ㉯ 마을에는 100명이 살아요. 알맞은 설명은 어느 것인가요?","options":[{"t":"㉮ 마을의 인구 밀도가 더 높다","correct":true},{"t":"㉯ 마을의 인구 밀도가 더 높다","mis":"SO5-1-u2-X18"},{"t":"두 마을의 인구 밀도는 같다","mis":"SO5-1-u2-X18"},{"t":"넓이가 같으면 인구 밀도를 견줄 수 없다","mis":"SO5-1-u2-X18"}],"explanation":["넓이가 같아요.","㉮에 사람이 더 많아요.","㉮가 더 빽빽해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#21','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C12',3,'mc','auto','다온이 일기 ⑦에서 가게가 문을 닫은 뒤 생기기 쉬운 일을 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑦에서 가게가 문을 닫은 뒤 생기기 쉬운 일을 바르게 이은 것은 어느 것인가요?","options":[{"t":"생활이 불편해짐 → 사람들이 더 떠남 → 시설이 더 줄어듦","correct":true},{"t":"생활이 편해짐 → 사람이 더 모임 → 시설이 늘어남","mis":"SO5-1-u2-X21"},{"t":"가게가 닫힘 → 집값이 오름 → 교통이 붐빔","mis":"SO5-1-u2-X21"},{"t":"가게가 닫힘 → 아무 일도 없음 → 인구가 그대로","mis":"SO5-1-u2-X22"}],"explanation":["불편하면 떠나요.","떠나면 시설이 더 줄어요.","고리가 되풀이돼요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#22','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C14',3,'mc','auto','솔내 마을의 「농사일을 도울 사람이 부족하다」는 문제에 세 잣대를 모두 지나는 방안은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"mc","stem":"솔내 마을의 「농사일을 도울 사람이 부족하다」는 문제에 세 잣대를 모두 지나는 방안은 어느 것인가요?","options":[{"t":"농촌에서 일하고 살아 보려는 청년에게 집과 일거리를 연결해 준다","correct":true},{"t":"도시 청년을 억지로 마을에 보내 농사짓게 한다","mis":"SO5-1-u2-X24"},{"t":"마을마다 큰 공장을 열 개씩 새로 짓는다","mis":"SO5-1-u2-X24"},{"t":"도시 회사에 다니는 청년에게 상을 준다","mis":"SO5-1-u2-X24"}],"explanation":["억지로 보내면 옳지 않아요.","공장 열 개는 비용이 지나쳐요.","상은 원인과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#23','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C7',4,'mc','auto','다온이 일기 ①~⑤를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09','SO5-1-u2-X13','SO5-1-u2-X14']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C7","difficulty":4,"kind":"mc","stem":"다온이 일기 ①~⑤를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"계절마다 다른 자연재해에 대비하는 동시에, 재해를 키우는 기후변화를 막는 기후 행동도 함께 해야 한다","correct":true},{"t":"자연재해는 겨울에만 생기므로 겨울에만 대비하면 된다","mis":"SO5-1-u2-X09"},{"t":"기후변화와 자연재해는 서로 관계가 없다","mis":"SO5-1-u2-X13"},{"t":"기후 행동은 어른과 기업만 하면 된다","mis":"SO5-1-u2-X14"}],"explanation":["①~④는 계절별 재해예요.","⑤는 기후 행동이에요.","대비와 막기를 함께 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#24','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C6',4,'essay','teacher','다온이 일기 ①~③에 나온 자연재해를 계절과 함께 쓰고, 그 가운데 하나를 골라 피해를 줄이려고 나라가 하는 일과 내가 할 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"essay","stem":"다온이 일기 ①~③에 나온 자연재해를 계절과 함께 쓰고, 그 가운데 하나를 골라 피해를 줄이려고 나라가 하는 일과 내가 할 일을 쓰세요.","answer_guide":{"answer":"예: 봄에는 황사와 가뭄, 여름에는 호우와 홍수, 늦여름에는 태풍이 있었다. 호우와 홍수에 대비해 나라는 제방을 쌓고 기상 특보와 긴급 재난 문자로 미리 알린다. 나는 특보나 문자를 확인하고 물이 찬 낮은 길로 다니지 않고 높은 곳으로 피하겠다.","scoring_points":["자연재해와 계절을 바르게 썼는가","나라가 하는 대비 노력을 썼는가","내가 할 행동 요령을 썼는가"]},"explanation":["계절별 재해를 써요.","시설과 특보가 있어요.","나도 행동 요령을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#25','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C13',4,'essay','teacher','다온이 일기 ⑧에 나온 솔내 마을의 노력 세 가지를 쓰고, 그 가운데 하나가 인구 분포의 불균형을 줄이는 데 어떻게 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C13","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑧에 나온 솔내 마을의 노력 세 가지를 쓰고, 그 가운데 하나가 인구 분포의 불균형을 줄이는 데 어떻게 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 솔내 마을의 노력은 주민이 참여하는 햇빛 발전 사업, 청년 마을, 고향 사랑 기부이다. 햇빛 발전 사업은 주민이 직접 참여해 수익을 나누므로 소득이 늘고 지역 경제가 활발해져 새로운 일거리가 생기고, 그래서 사람들이 마을에 머물거나 다시 모여 불균형을 줄이는 데 도움이 된다.","scoring_points":["세 가지 노력을 썼는가","하나를 골랐는가","불균형을 줄이는 까닭을 썼는가"]},"explanation":["햇빛 발전·청년 마을·기부예요.","하나를 골라요.","사람이 모이는 까닭을 써요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#1','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C1',1,'mc','auto','기후를 구성하는 요소끼리 바르게 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"기후를 구성하는 요소끼리 바르게 묶인 것은 어느 것인가요?","options":[{"t":"기온·강수·바람","correct":true},{"t":"기온·지형·인구","mis":"SO5-1-u2-X02"},{"t":"강수·하천·평야","mis":"SO5-1-u2-X02"},{"t":"바람·교통·일자리","mis":"SO5-1-u2-X02"}],"explanation":["대기의 상태예요.","따뜻함, 내린 물, 공기의 움직임이에요.","기온·강수·바람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#2','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C3',1,'sa','auto','우리나라는 대체로 남쪽과 북쪽 가운데 어느 쪽으로 갈수록 기온이 높아지나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"sa","stem":"우리나라는 대체로 남쪽과 북쪽 가운데 어느 쪽으로 갈수록 기온이 높아지나요? 두 글자로 쓰세요.","answer":["남쪽"],"explanation":["남북으로 길어요.","아래쪽이 따뜻해요.","남쪽이에요."],"mis":"SO5-1-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#3','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C4',1,'sa','auto','눈·비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"sa","stem":"눈·비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["강수"],"explanation":["비도 눈도 내려요.","땅에 내린 물이에요.","강수예요."],"mis":"SO5-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#4','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C5',1,'sa','auto','기온이 갑자기 크게 내려가 수도관이 얼기도 하는 겨울의 자연재해를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"sa","stem":"기온이 갑자기 크게 내려가 수도관이 얼기도 하는 겨울의 자연재해를 쓰세요.","answer":["한파"],"explanation":["갑자기 추워져요.","동상 피해도 생겨요.","한파예요."],"mis":"SO5-1-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
