INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#6','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C9',1,'sa','auto','일정한 지역에 살고 있는 사람의 수를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"sa","stem":"일정한 지역에 살고 있는 사람의 수를 두 글자로 무엇이라고 하나요?","answer":["인구"],"explanation":["사람의 수예요.","한 지역에 사는 사람이에요.","인구예요."],"mis":"SO5-1-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#7','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C10',1,'sa','auto','1960년대 이후 공장과 도시가 발달한 변화를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"sa","stem":"1960년대 이후 공장과 도시가 발달한 변화를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["산업화"],"explanation":["산업이 크게 자랐어요.","사람들이 도시로 갔어요.","산업화예요."],"mis":"SO5-1-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#8','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',1,'sa','auto','수도권에서 집이 모자라 집값이 오르는 문제를 무엇이라고 하나요? (□□ 문제)','{}'::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"sa","stem":"수도권에서 집이 모자라 집값이 오르는 문제를 무엇이라고 하나요? (□□ 문제)","answer":["주택"],"explanation":["살 집이 모자라요.","집값이 올라요.","주택 문제예요."],"mis":"SO5-1-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#9','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C2',2,'ox','auto','눈이 많이 오는 지역에서 해마다 겨울에 눈 축제를 여는 것은 기후의 영향을 받은 생활이에요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"ox","stem":"눈이 많이 오는 지역에서 해마다 겨울에 눈 축제를 여는 것은 기후의 영향을 받은 생활이에요.","answer":"O","reason_options":[{"t":"여러 해 되풀이되는 겨울 기후에 맞춰 축제를 열기 때문에","correct":true},{"t":"그날 하루 눈이 왔기 때문에 열기로 한 것이기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["해마다 눈이 많아요.","같은 때 축제를 열어요.","기후의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#10','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C6',2,'ox','auto','홍수에 대비해 제방을 쌓고, 가뭄에 대비해 저수지와 댐을 만들어요.',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"ox","stem":"홍수에 대비해 제방을 쌓고, 가뭄에 대비해 저수지와 댐을 만들어요.","answer":"O","reason_options":[{"t":"시설을 마련해 자연재해의 피해를 줄이기 때문에","correct":true},{"t":"시설을 만들면 자연재해가 아예 일어나지 않기 때문에","mis":"SO5-1-u2-X10"}],"mis":"SO5-1-u2-X10","explanation":["제방은 물이 넘치지 않게 해요.","저수지는 물을 모아 둬요.","피해를 줄이는 시설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#11','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C8',2,'ox','auto','기후 행동은 특별한 사람만 할 수 있는 일이에요.',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"ox","stem":"기후 행동은 특별한 사람만 할 수 있는 일이에요.","answer":"X","reason_options":[{"t":"기후변화를 막으려는 모든 노력이라 누구나 참여할 수 있기 때문에","correct":true},{"t":"나라와 기업만 기후 행동을 할 수 있기 때문에","mis":"SO5-1-u2-X14"}],"mis":"SO5-1-u2-X14","explanation":["작은 실천도 기후 행동이에요.","누구나 할 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#12','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C9',2,'ox','auto','교통이 편리하고 학교가 많은 곳에 사람이 모이는 것은 인문환경의 영향이에요.',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"ox","stem":"교통이 편리하고 학교가 많은 곳에 사람이 모이는 것은 인문환경의 영향이에요.","answer":"O","reason_options":[{"t":"교통과 교육은 사람이 만든 환경이기 때문에","correct":true},{"t":"교통과 교육은 자연이 만든 환경이기 때문에","mis":"SO5-1-u2-X17"}],"mis":"SO5-1-u2-X17","explanation":["길과 학교는 사람이 만들어요.","그래서 인문환경이에요.","사람이 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#13','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C11',2,'ox','auto','수도권은 비수도권보다 청장년층 인구 비율이 높아요.',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"ox","stem":"수도권은 비수도권보다 청장년층 인구 비율이 높아요.","answer":"O","reason_options":[{"t":"일자리와 교육 기회를 찾아 청장년층이 수도권으로 모이기 때문에","correct":true},{"t":"수도권에는 어르신만 모여 살기 때문에","mis":"SO5-1-u2-X20"}],"mis":"SO5-1-u2-X20","explanation":["경기도는 청장년층이 많아요.","일자리를 찾아 모여요.","그래서 비율이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#14','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',2,'ox','auto','다온이 일기 ⑥의 집값 걱정은 인구가 줄어드는 지역에서 주로 나타나는 문제예요.',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"ox","stem":"다온이 일기 ⑥의 집값 걱정은 인구가 줄어드는 지역에서 주로 나타나는 문제예요.","answer":"X","reason_options":[{"t":"집값 상승은 사람이 몰리는 수도권에서 주로 나타나는 문제이기 때문에","correct":true},{"t":"인구가 줄면 집이 모자라 집값이 오르기 때문에","mis":"SO5-1-u2-X21"}],"mis":"SO5-1-u2-X21","explanation":["한빛시는 수도권이에요.","사람이 몰려 집이 모자라요.","그래서 X예요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#15','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C13',2,'ox','auto','고향 사랑 기부는 태어난 곳이 아니어도 관심 있는 지역에 할 수 있어요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"ox","stem":"고향 사랑 기부는 태어난 곳이 아니어도 관심 있는 지역에 할 수 있어요.","answer":"O","reason_options":[{"t":"고향이나 관심 있는 지역 어디에나 기부할 수 있는 제도이기 때문에","correct":true},{"t":"그 지역에서 태어난 사람만 기부할 수 있기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["관심 지역에도 해요.","답례품과 세금 혜택이 있어요.","지방 재정을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#16','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C14',2,'ox','auto','좋아 보이는 방안도 세 잣대 가운데 하나에서 걸릴 수 있으니 세 가지를 모두 살펴야 해요.',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"ox","stem":"좋아 보이는 방안도 세 잣대 가운데 하나에서 걸릴 수 있으니 세 가지를 모두 살펴야 해요.","answer":"O","reason_options":[{"t":"원인·옳음·실현 가운데 하나만 보면 다른 잣대의 문제를 놓치기 때문에","correct":true},{"t":"잣대 하나만 지나면 좋은 방안이기 때문에","mis":"SO5-1-u2-X24"}],"mis":"SO5-1-u2-X24","explanation":["하나만 보면 놓쳐요.","셋을 모두 대요.","그래야 좋은 방안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#17','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C3',3,'error','auto','계절별 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X07','SO5-1-u2-X05']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"error","stem":"계절별 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로하 — 「겨울에는 남쪽 바다에서 뜨겁고 습한 바람이 불어와.」","correct":true,"mis_target":"SO5-1-u2-X04"},{"t":"채민 — 「연 강수량은 남쪽으로 갈수록 많아.」","mis":"SO5-1-u2-X07"},{"t":"도율 — 「남북 기온 차이는 겨울에 더 커.」","mis":"SO5-1-u2-X05"}],"explanation":["겨울 바람은 북서쪽 육지에서 와요.","차갑고 건조해요.","로하가 바꿔 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#18','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C6',3,'error','auto','자연재해의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X11','SO5-1-u2-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"error","stem":"자연재해의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「숲을 없애고 물길을 바꿔도 홍수 피해와는 아무 상관 없어.」","correct":true,"mis_target":"SO5-1-u2-X11"},{"t":"시윤 — 「숲은 빗물을 머금어 피해를 줄여 줘.」","mis":"SO5-1-u2-X11"},{"t":"가윤 — 「자연 현상으로 사람이 피해를 입으면 자연재해야.」","mis":"SO5-1-u2-X08"}],"explanation":["숲과 물길은 물의 흐름을 정해요.","바꾸면 피해가 커지기도 해요.","하람이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#19','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C8',3,'error','auto','다온이 일기 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"error","stem":"다온이 일기 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세율 — 「△가 나왔으니 다온이의 기후 행동은 실패야. 그만두는 게 좋아.」","correct":true,"mis_target":"SO5-1-u2-X15"},{"t":"지온 — 「돌아보고 다시 하려는 게 좋은 기후 행동이야.」","mis":"SO5-1-u2-X15"},{"t":"하늬 — 「손수건 쓰기는 개인의 기후 행동이야.」","mis":"SO5-1-u2-X14"}],"explanation":["잘 안 된 날도 있어요.","돌아보고 다시 해요.","세율이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#20','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C10',3,'error','auto','우리나라 인구 분포의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"error","stem":"우리나라 인구 분포의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「사람들이 도시에서 솔내 마을 같은 촌락으로 많이 옮겨 갔어.」","correct":true,"mis_target":"SO5-1-u2-X19"},{"t":"아린 — 「오늘날 인구 100명 중 92명 정도가 도시에 살아.」","mis":"SO5-1-u2-X19"},{"t":"재윤 — 「옛날엔 평야가 넓은 곳에 많이 살았어.」","mis":"SO5-1-u2-X19"}],"explanation":["촌락에서 도시로 옮겼어요.","도시 인구가 늘었어요.","수호가 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#21','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',3,'error','auto','수도권과 비수도권의 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X22','SO5-1-u2-X21']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"error","stem":"수도권과 비수도권의 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「수도권은 사람이 많으니까 문제가 하나도 없어.」","correct":true,"mis_target":"SO5-1-u2-X22"},{"t":"하윤 — 「수도권은 집이 부족하고 교통이 붐벼.」","mis":"SO5-1-u2-X21"},{"t":"서원 — 「비수도권은 빈집과 폐교가 늘어.」","mis":"SO5-1-u2-X21"}],"explanation":["수도권에도 문제가 있어요.","주택·교통·환경 문제예요.","예준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#22','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C14',3,'error','auto','해결 방안 평가를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"error","stem":"해결 방안 평가를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유준 — 「원인만 풀 수 있으면 사람들한테 벌을 줘도 좋은 방안이야.」","correct":true,"mis_target":"SO5-1-u2-X24"},{"t":"시은 — 「옳은 방안인지도 꼭 살펴야 해.」","mis":"SO5-1-u2-X24"},{"t":"도윤 — 「비용과 노력으로 해낼 수 있는지 봐야 해.」","mis":"SO5-1-u2-X24"}],"explanation":["잣대는 셋 다 지나야 해요.","벌주는 것은 옳지 않아요.","유준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#23','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',4,'mc','auto','다온이 일기 ⑥·⑦·⑧을 차례로 이어 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-1-u2-X22','SO5-1-u2-X24']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"mc","stem":"다온이 일기 ⑥·⑦·⑧을 차례로 이어 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"수도권은 몰려서, 솔내 마을은 비어서 문제가 생기므로 정부·지역·주민이 함께 사람이 고르게 살 수 있게 노력해야 한다","correct":true},{"t":"수도권은 문제가 없으니 솔내 마을만 노력하면 된다","mis":"SO5-1-u2-X22"},{"t":"솔내 마을 사람들을 모두 한빛시로 옮기면 해결된다","mis":"SO5-1-u2-X24"},{"t":"두 곳의 문제는 저절로 사라진다","mis":"SO5-1-u2-X22"}],"explanation":["⑥은 몰린 곳이에요.","⑦은 빈 곳, ⑧은 노력이에요.","함께 고르게 살 길을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#24','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C8',4,'essay','teacher','다온이 일기 ⑤를 보고 기후변화가 우리 생활에 준 영향을 쓰고, 다온이의 기후 행동 수첩에서 본받을 점과 내가 더할 기후 행동 한 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C8","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑤를 보고 기후변화가 우리 생활에 준 영향을 쓰고, 다온이의 기후 행동 수첩에서 본받을 점과 내가 더할 기후 행동 한 가지를 쓰세요.","answer_guide":{"answer":"예: 기후변화로 여름이 길어지고 역대 가장 긴 폭염처럼 자연재해가 더 심해졌다. 다온이는 손수건을 잊은 날 그만두지 않고 까닭을 돌아보아 손수건을 하나 더 챙겼는데, 실천한 뒤 돌아보고 다시 하는 점을 본받고 싶다. 나는 일회용 컵 대신 개인 물병을 쓰겠다.","scoring_points":["기후변화의 영향을 썼는가","실천하고 돌아보는 점을 본받을 점으로 썼는가","내가 매일 할 수 있는 기후 행동을 썼는가"]},"explanation":["여름이 길어졌어요.","돌아보고 다시 했어요.","나도 매일 할 일을 더해요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#25','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C14',4,'essay','teacher','솔내 마을의 「1학년 신입생이 없는 학교」 문제를 풀 방안을 한 가지 쓰고, 세 잣대(원인·옳음·실현)에 대어 평가하세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C14","difficulty":4,"kind":"essay","stem":"솔내 마을의 「1학년 신입생이 없는 학교」 문제를 풀 방안을 한 가지 쓰고, 세 잣대(원인·옳음·실현)에 대어 평가하세요.","answer_guide":{"answer":"예: 방안은 솔내 초등학교에 자연 속 특별 교육과정을 만들고 낡은 시설을 고쳐 다니고 싶은 학교로 만드는 것이다. 학교가 다닐 만한 곳이 되어 학생이 오게 하니 원인 해결에 도움이 된다. 누구에게도 억지로 전학을 시키지 않으니 옳은 방안이다. 이미 여러 지역에서 하는 일이라 비용과 노력을 생각할 때 해낼 수 있다.","scoring_points":["방안을 썼는가","세 잣대에 모두 대어 보았는가","각 잣대의 까닭을 썼는가"]},"explanation":["방안을 먼저 써요.","원인·옳음·실현에 대요.","까닭을 함께 써요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#1','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C1',1,'ox','auto','「우리나라는 사계절이 뚜렷하다」는 말은 기후에 대한 설명이에요.',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"ox","stem":"「우리나라는 사계절이 뚜렷하다」는 말은 기후에 대한 설명이에요.","answer":"O","reason_options":[{"t":"여러 해에 걸쳐 되풀이되어 나타나는 모습이기 때문에","correct":true},{"t":"오늘 하루의 하늘을 보고 한 말이기 때문에","mis":"SO5-1-u2-X01"}],"mis":"SO5-1-u2-X01","explanation":["사계절은 해마다 되풀이돼요.","여러 해의 모습이에요.","그래서 기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#2','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C3',1,'ox','auto','다온이 일기 ④에서 같은 날 이모가 사는 남쪽 섬이 다온이네보다 따뜻했던 것은 우리나라 기온의 특징과 맞아요.',ARRAY['SO5-1-u2-X05']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"ox","stem":"다온이 일기 ④에서 같은 날 이모가 사는 남쪽 섬이 다온이네보다 따뜻했던 것은 우리나라 기온의 특징과 맞아요.","answer":"O","reason_options":[{"t":"대체로 남쪽으로 갈수록 기온이 높기 때문에","correct":true},{"t":"북쪽으로 갈수록 기온이 높기 때문에","mis":"SO5-1-u2-X05"}],"mis":"SO5-1-u2-X05","explanation":["이모는 남쪽 섬에 살아요.","겨울에도 밭에서 무를 거둬요.","남쪽이 더 따뜻해요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#3','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C4',1,'ox','auto','다온이 일기 ②처럼 여름에 비가 많이 내리는 것은 우리나라 강수의 특징과 맞아요.',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"ox","stem":"다온이 일기 ②처럼 여름에 비가 많이 내리는 것은 우리나라 강수의 특징과 맞아요.","answer":"O","reason_options":[{"t":"연 강수량의 절반 이상이 여름에 내리기 때문에","correct":true},{"t":"우리나라는 겨울에 비가 가장 많기 때문에","mis":"SO5-1-u2-X07"}],"mis":"SO5-1-u2-X07","explanation":["여름에 비가 몰려요.","7월에 굵은 비가 왔어요.","특징과 맞아요."],"asset":{"type":"passage","lines":["7월 — 며칠째 굵은 비가 쏟아졌다. 하천 물이 불어 낮은 길이 잠겼다.","집에 오는 길에 휴대 전화로 긴급 재난 문자가 왔다.","물이 찬 길로 다니지 말라는 안내를 보고 높은 길로 돌아왔다."],"title":"다온이 일기 ② 여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#4','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C5',1,'ox','auto','태풍은 주로 겨울에 우리나라에 영향을 주는 자연재해예요.',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"ox","stem":"태풍은 주로 겨울에 우리나라에 영향을 주는 자연재해예요.","answer":"X","reason_options":[{"t":"태풍은 주로 여름과 가을 사이에 우리나라에 영향을 주기 때문에","correct":true},{"t":"태풍은 눈을 많이 내리는 겨울 재해이기 때문에","mis":"SO5-1-u2-X09"}],"mis":"SO5-1-u2-X09","explanation":["다온이 일기 ③은 9월 초예요.","여름과 가을 사이에 와요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#5','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C7',1,'ox','auto','기후변화로 폭염 같은 자연재해가 더 잦아지고 세지고 있어요.',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"ox","stem":"기후변화로 폭염 같은 자연재해가 더 잦아지고 세지고 있어요.","answer":"O","reason_options":[{"t":"기후변화로 자연재해의 횟수와 강도가 모두 늘고 있기 때문에","correct":true},{"t":"기후변화는 자연재해와 관계가 없기 때문에","mis":"SO5-1-u2-X13"}],"mis":"SO5-1-u2-X13","explanation":["「역대」라는 말이 잦아요.","더 자주, 더 세게 와요.","기후변화의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#6','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C9',1,'ox','auto','다온이네 한빛시처럼 도시가 발달한 곳은 대체로 인구 밀도가 높아요.',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"ox","stem":"다온이네 한빛시처럼 도시가 발달한 곳은 대체로 인구 밀도가 높아요.","answer":"O","reason_options":[{"t":"일자리와 교통이 갖춰져 좁은 땅에 사람이 많이 모이기 때문에","correct":true},{"t":"도시는 땅이 넓어 사람이 흩어져 살기 때문에","mis":"SO5-1-u2-X18"}],"mis":"SO5-1-u2-X18","explanation":["지하철이 꽉 차요.","사람이 많이 모여요.","인구 밀도가 높아요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#7','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',1,'ox','auto','과거 우리나라는 벼농사 중심의 농업 사회라 남서쪽 평야 지대에 사람이 많이 살았어요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"ox","stem":"과거 우리나라는 벼농사 중심의 농업 사회라 남서쪽 평야 지대에 사람이 많이 살았어요.","answer":"O","reason_options":[{"t":"기후가 온화하고 평야가 넓은 곳이 농사짓기 좋았기 때문에","correct":true},{"t":"그곳에 공장과 회사가 가장 많았기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["그때는 농사가 중요했어요.","평야가 넓었어요.","자연환경의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#8','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C12',1,'ox','auto','인구 분포의 불균형은 수도권과 비수도권 모두에 문제를 낳아요.',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"ox","stem":"인구 분포의 불균형은 수도권과 비수도권 모두에 문제를 낳아요.","answer":"O","reason_options":[{"t":"몰리는 곳은 혼잡하고 빠져나가는 곳은 시설이 줄기 때문에","correct":true},{"t":"불균형은 수도권에만 문제를 낳기 때문에","mis":"SO5-1-u2-X22"}],"mis":"SO5-1-u2-X22","explanation":["수도권엔 혼잡이 생겨요.","비수도권엔 빈집이 생겨요.","두 곳 모두 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#9','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C2',2,'error','auto','기후가 생활에 주는 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"error","stem":"기후가 생활에 주는 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다빈 — 「오늘 소나기로 소풍이 취소된 건 기후가 생활에 준 영향이야.」","correct":true,"mis_target":"SO5-1-u2-X03"},{"t":"주안 — 「덥고 비가 많은 곳은 벼농사가 활발해.」","mis":"SO5-1-u2-X03"},{"t":"예나 — 「계절마다 입는 옷이 달라져.」","mis":"SO5-1-u2-X03"}],"explanation":["오늘 소나기는 날씨예요.","기후의 영향이 아니에요.","다빈이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#10','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C6',2,'error','auto','자연재해 대비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"error","stem":"자연재해 대비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「태풍 주의보가 나오면 바닷가에 가서 큰 파도를 구경하자.」","correct":true,"mis_target":"SO5-1-u2-X10"},{"t":"시아 — 「기상 특보가 나오면 뉴스를 확인해.」","mis":"SO5-1-u2-X10"},{"t":"로운 — 「학교에서 재난 대비 훈련을 해.」","mis":"SO5-1-u2-X10"}],"explanation":["태풍 때 바닷가는 위험해요.","외출을 삼가야 해요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#11','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C8',2,'error','auto','기후 행동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X14','SO5-1-u2-X15']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"error","stem":"기후 행동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「나 하나 손수건 쓴다고 달라지는 건 없으니 안 할래.」","correct":true,"mis_target":"SO5-1-u2-X14"},{"t":"유나 — 「빈 교실 전등을 끄는 것도 기후 행동이야.」","mis":"SO5-1-u2-X14"},{"t":"건우 — 「실천한 뒤에 수첩을 보며 돌아봐야 해.」","mis":"SO5-1-u2-X15"}],"explanation":["한 사람의 실천이 모여요.","누구나 참여해요.","시후가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#12','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C9',2,'error','auto','인구 분포에 영향을 주는 환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"error","stem":"인구 분포에 영향을 주는 환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하온 — 「일자리는 자연이 만든 환경이야.」","correct":true,"mis_target":"SO5-1-u2-X17"},{"t":"지아 — 「평평한 땅에 사람이 더 많이 살아.」","mis":"SO5-1-u2-X17"},{"t":"도하 — 「교통은 사람이 만든 인문환경이야.」","mis":"SO5-1-u2-X17"}],"explanation":["일자리는 사람이 만들어요.","인문환경이에요.","하온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#13','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C11',2,'error','auto','인구 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"error","stem":"인구 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「인구 구조를 보면 그 지역의 땅 넓이를 알 수 있어.」","correct":true,"mis_target":"SO5-1-u2-X20"},{"t":"서진 — 「인구 구조는 나이별로 나누어 본 짜임새야.」","mis":"SO5-1-u2-X20"},{"t":"라희 — 「비수도권은 노년층 비율이 더 높아.」","mis":"SO5-1-u2-X20"}],"explanation":["인구 구조는 나이·성별 짜임새예요.","땅 넓이와는 관계없어요.","은재가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#14','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C12',2,'error','auto','다온이 일기 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"error","stem":"다온이 일기 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「솔내 마을은 사람이 너무 많아서 가게가 문을 닫은 거야.」","correct":true,"mis_target":"SO5-1-u2-X21"},{"t":"나은 — 「사람이 줄어 물건이 안 팔려 가게가 문을 닫았어.」","mis":"SO5-1-u2-X21"},{"t":"준우 — 「트럭 상점은 가게가 없는 마을을 도와.」","mis":"SO5-1-u2-X21"}],"explanation":["솔내 마을은 사람이 줄었어요.","물건이 안 팔렸어요.","태윤이 거꾸로 말했어요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#15','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C13',2,'error','auto','불균형을 해결하는 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"error","stem":"불균형을 해결하는 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민우 — 「공공 기관을 수도권으로 더 모으면 인구가 고르게 살게 돼.」","correct":true,"mis_target":"SO5-1-u2-X23"},{"t":"해나 — 「로컬 브랜딩은 지역만의 매력을 만들어.」","mis":"SO5-1-u2-X23"},{"t":"지성 — 「혁신 도시는 일자리를 늘려 사람을 모아.」","mis":"SO5-1-u2-X23"}],"explanation":["공공 기관은 비수도권으로 옮겨요.","수도권으로 모으면 더 몰려요.","민우가 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#16','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C15',2,'error','auto','시화 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"error","stem":"시화 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「동시와 상관없어도 예쁜 그림이면 돼.」","correct":true,"mis_target":"SO5-1-u2-X26"},{"t":"서아 — 「그림은 동시의 내용을 나타내야 해.」","mis":"SO5-1-u2-X26"},{"t":"윤재 — 「친구 시화의 좋은 점을 찾아 말해 줘.」","mis":"SO5-1-u2-X26"}],"explanation":["그림은 동시를 보여 줘요.","내용을 나타내야 해요.","하늘이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#17','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C4',3,'ox','auto','연 강수량 분포도에서 남쪽으로 갈수록 파란색이 진해지는 것은 남쪽의 강수량이 더 많다는 뜻이에요.',ARRAY['SO5-1-u2-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C4","difficulty":3,"kind":"ox","stem":"연 강수량 분포도에서 남쪽으로 갈수록 파란색이 진해지는 것은 남쪽의 강수량이 더 많다는 뜻이에요.","answer":"O","reason_options":[{"t":"분포도에서 진한 파란색일수록 강수량이 많기 때문에","correct":true},{"t":"진한 파란색일수록 기온이 낮기 때문에","mis":"SO5-1-u2-X06"}],"mis":"SO5-1-u2-X06","explanation":["파란색은 강수량이에요.","진할수록 많아요.","남쪽이 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#18','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C5',3,'ox','auto','다온이 일기 ③의 태풍이 남서쪽에서 올라온 것은 태풍이 대체로 지나가는 길과 맞아요.',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"ox","stem":"다온이 일기 ③의 태풍이 남서쪽에서 올라온 것은 태풍이 대체로 지나가는 길과 맞아요.","answer":"O","reason_options":[{"t":"태풍은 대체로 남서쪽에서 북동쪽으로 지나가기 때문에","correct":true},{"t":"태풍은 언제나 북쪽에서 남쪽으로 내려오기 때문에","mis":"SO5-1-u2-X09"}],"mis":"SO5-1-u2-X09","explanation":["남서쪽에서 올라왔어요.","북동쪽으로 지나가요.","태풍의 길과 맞아요."],"asset":{"type":"passage","lines":["9월 초 — 남서쪽에서 태풍이 올라온다며 태풍 주의보가 내려졌다.","아빠와 베란다의 화분과 빨래 건조대를 안으로 들여놓았다.","그날은 밖에 나가지 않고 집에서 보냈다."],"title":"다온이 일기 ③ 늦여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#19','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C7',3,'ox','auto','기후변화는 숲을 파괴하고 석유·석탄을 지나치게 쓰는 인간 활동과 관계가 있어요.',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"ox","stem":"기후변화는 숲을 파괴하고 석유·석탄을 지나치게 쓰는 인간 활동과 관계가 있어요.","answer":"O","reason_options":[{"t":"이런 인간 활동이 지구 온난화를 심하게 만들기 때문에","correct":true},{"t":"기후변화는 사람과 아무 관계 없이 일어나기 때문에","mis":"SO5-1-u2-X12"}],"mis":"SO5-1-u2-X12","explanation":["사람의 활동이 원인이에요.","지구가 더워져요.","기후가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#20','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',3,'ox','auto','오늘날 수도권으로 사람이 모이는 까닭은 주로 기후가 온화하고 평야가 넓기 때문이에요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"ox","stem":"오늘날 수도권으로 사람이 모이는 까닭은 주로 기후가 온화하고 평야가 넓기 때문이에요.","answer":"X","reason_options":[{"t":"오늘날에는 일자리·교통 같은 인문환경의 영향이 크기 때문에","correct":true},{"t":"수도권은 우리나라에서 평야가 가장 넓은 곳이기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["옮겨 온 까닭 1위는 직업이에요.","인문환경의 영향이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#21','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C12',3,'ox','auto','다온이 학교의 운동장 요일제는 학생이 너무 많은 수도권 학교의 모습을 보여 줘요.',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"ox","stem":"다온이 학교의 운동장 요일제는 학생이 너무 많은 수도권 학교의 모습을 보여 줘요.","answer":"O","reason_options":[{"t":"인구가 몰린 곳은 시설이 부족해 나누어 써야 하기 때문에","correct":true},{"t":"학생이 줄어든 학교라 운동장이 남기 때문에","mis":"SO5-1-u2-X21"}],"mis":"SO5-1-u2-X21","explanation":["학생이 많아요.","운동장이 부족해요.","몰린 곳의 모습이에요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#22','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C13',3,'ox','auto','솔내 마을의 트럭 상점처럼 물건을 싣고 마을을 찾아가는 방법은 사는 곳에서 주민을 돕는 노력이에요.',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"ox","stem":"솔내 마을의 트럭 상점처럼 물건을 싣고 마을을 찾아가는 방법은 사는 곳에서 주민을 돕는 노력이에요.","answer":"O","reason_options":[{"t":"주민을 이사 보내지 않고 부족한 상점을 채워 주기 때문에","correct":true},{"t":"주민을 도시로 옮겨 살게 하는 방법이기 때문에","mis":"SO5-1-u2-X24"}],"mis":"SO5-1-u2-X24","explanation":["물건이 마을로 가요.","주민은 그대로 살아요.","사는 곳에서 도와요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#23','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',4,'mc','auto','다온이 일기 ⑦과 ⑧을 함께 볼 때 솔내 마을의 노력이 인구 분포의 변화와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19','SO5-1-u2-X18']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"mc","stem":"다온이 일기 ⑦과 ⑧을 함께 볼 때 솔내 마을의 노력이 인구 분포의 변화와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오늘날 인구 분포는 일자리 같은 인문환경의 영향이 크므로 일거리와 살기 좋은 환경을 만들면 사람을 다시 모을 수 있기 때문에","correct":true},{"t":"오늘날 인구 분포는 기후만 바꾸면 달라지기 때문에","mis":"SO5-1-u2-X19"},{"t":"솔내 마을의 땅을 넓히면 인구 밀도가 높아지기 때문에","mis":"SO5-1-u2-X18"},{"t":"인구 분포는 한 번 정해지면 바뀌지 않기 때문에","mis":"SO5-1-u2-X19"}],"explanation":["사람은 일자리를 찾아 움직여요.","인문환경의 영향이 커요.","일거리가 사람을 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#24','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C9',4,'essay','teacher','다온이 일기 ⑥과 ⑦을 견주어 두 곳의 인구 밀도가 어떻게 다를지 쓰고, 그렇게 된 까닭을 자연환경과 인문환경 가운데 하나와 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑥과 ⑦을 견주어 두 곳의 인구 밀도가 어떻게 다를지 쓰고, 그렇게 된 까닭을 자연환경과 인문환경 가운데 하나와 이어 쓰세요.","answer_guide":{"answer":"예: 한빛시는 지하철이 늘 꽉 차고 학생이 많을 만큼 사람이 몰려 인구 밀도가 높을 것이고, 솔내 마을은 신입생이 없을 만큼 사람이 줄어 인구 밀도가 낮을 것이다. 한빛시에는 일자리와 교통 같은 인문환경이 잘 갖춰져 사람이 모이고, 솔내 마을은 일자리가 적어 젊은 사람이 떠났기 때문이다.","scoring_points":["한빛시의 인구 밀도를 썼는가","솔내 마을의 인구 밀도를 썼는가","환경과 이어 까닭을 썼는가"]},"explanation":["한빛시는 높아요.","솔내 마을은 낮아요.","일자리가 사람을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#25','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C15',4,'essay','teacher','다온이처럼 이 단원에서 공부한 내용으로 동시를 짓는다고 생각하고, 주제와 바탕이 될 내 경험을 쓴 뒤 동시 세 줄과 시화에 그릴 장면을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"essay","stem":"다온이처럼 이 단원에서 공부한 내용으로 동시를 짓는다고 생각하고, 주제와 바탕이 될 내 경험을 쓴 뒤 동시 세 줄과 시화에 그릴 장면을 쓰세요.","answer_guide":{"answer":"예: 주제는 자연재해에 대비하는 노력이다. 경험 — 비가 세차게 내린 날 긴급 재난 문자를 보고 높은 길로 돌아왔다. 동시 — 하늘에 구멍 났나 쏟아지는 비 / 주머니에서 울리는 고마운 문자 / 나는 높은 길로 천천히. 장면 — 우산을 쓰고 물이 찬 낮은 길을 피해 높은 길로 걷는 나.","scoring_points":["단원에서 공부한 주제를 골랐는가","내 경험을 썼는가","짧게 줄인 동시 세 줄과 알맞은 장면을 썼는가"]},"explanation":["주제를 골라요.","내 경험이 바탕이에요.","짧게 줄이고 장면을 정해요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
